        'intro' => 'கீழே உள்ள செய்திகள் புத்தம் புதிய டிக்கெட்டுக்கு நகரும். இந்த டிக்கெட் மீதமுள்ளவற்றை வைத்திருக்கும்; அவை எங்கு சென்றன என்பதைக் காட்டும் குறிப்பும் இருக்கும்.',
        'pick_intro' => 'புதிய டிக்கெட்டில் இருக்க வேண்டிய செய்திகளைத் தேர்வுசெய்யவும். அவை நகரும்; இந்த டிக்கெட் மீதமுள்ளவற்றை வைத்திருக்கும், அவை எங்கு சென்றன என்பதைக் காட்டும் குறிப்புடன்.',
