        'confirm' => 'பிரி',
        'done' => '%d செய்திகள் %s-க்கு நகர்த்தப்பட்டன',
        'would_empty' => 'அது அனைத்துச் செய்திகளையும் நகர்த்தி இந்த டிக்கெட்டை காலியாக்கிவிடும். குறைந்தது ஒரு செய்தியை இங்கே வைத்திருங்கள், அல்லது டிக்கெட்டை ஒன்றிணையுங்கள்.',
