        'effect_ref_survivor' => 'நீங்கள் தேர்ந்தெடுக்கும் டிக்கெட் தனது குறிப்பு எண்ணை வைத்திருக்கும். மற்றவை மூடப்பட்டு அதைச் சுட்டிக்காட்டும்.',
