        'effect_orig_thread' => 'உரையாடல்கள் ஒன்றிணைந்த டிக்கெட்டுக்கு நகரும்.',
        'effect_orig_thread_html' => 'உரையாடல்கள் நகரும், ஒவ்வொன்றின் நகலும் HTML கோப்பாகவும் இணைக்கப்படும்.',
        'effect_orig_html' => 'உரையாடல்கள் இருந்த இடத்திலேயே இருக்கும்; நகல்கள் ஒன்றிணைந்த டிக்கெட்டில் HTML கோப்புகளாக இணைக்கப்படும்.',
