        'ai_progress' => 'ஒன்றிணைக்கப்பட்ட உரையாடல்களைப் படிக்கிறது… %dவி. நீண்ட உரையாடலுக்கு ஒரு நிமிடம் வரை ஆகலாம்.',
        'ai_unconfigured' => 'AI வழங்குநர் எதுவும் அமைக்கப்படவில்லை, எனவே தானியங்கி சுருக்கம் இல்லை. உங்கள் சொந்தக் குறிப்பை இங்கே தட்டச்சு செய்யலாம், அல்லது மூடலாம்.',
        'ai_failed' => 'சுருக்கத்தை எழுத முடியவில்லை — ஒன்றிணைப்பு சரியாகவே நடந்தது',
