        'undo_message' => 'இந்த டிக்கெட் கொண்டுவந்த செய்திகள், குறிப்புகள் மற்றும் பதிவு செய்யப்பட்ட நேரம் திரும்பி வரும், அது முன்பிருந்தபடியே மீண்டும் திறக்கும். ஒன்றிணைப்புக்குப் பிறகு மற்ற டிக்கெட்டில் எழுதப்பட்ட பதில்கள் அங்கேயே இருக்கும் — இது முழுமையான பின்னோக்கு அல்ல.',
