            'preserved_note' => 'ஒரு சுவிட்சை அணைப்பது எதையும் நீக்காது. ஏற்கனவே வகை உள்ள டிக்கெட் அதை வைத்திருக்கும், புலத்தை மீண்டும் இயக்கினால் அது அப்படியே திரும்ப வரும்.',
            'list_heading' => 'வகைகள்',
            'list_intro' => 'ஒரு வகையைச் சேர்க்கவும், விரும்பினால் அதன் கீழ் துணை வகைகளைச் சேர்க்கவும் - மூன்று நிலைகள் வரை, எந்த நிலையும் கட்டாயம் இல்லை. ஒரு வகையை ஒரு டிக்கெட் வகையுடன் இணைத்து அந்த வகையில் மட்டும் வழங்கலாம், அல்லது அனைத்திலும் தோன்றுமாறு விடலாம்.',
