            'f_portal_help' => 'அணைத்தால் பகுப்பாய்வாளர்களுக்கு மட்டும். கோரிக்கையாளர்கள் உங்கள் முழு மரத்தையும் அல்ல, எளிய மொழியில் ஒரு சிறிய பட்டியலைக் காண வேண்டும்.',
            'f_active' => 'செயலில்',
