            'api_desc' => 'வேண்டுமென்றே தனியாக: பலகத்தை மறைப்பது திரையைச் சீராக்கும், ஆனால் API ஐ மூடுவது யாரோ உருவாக்கிய ஒருங்கிணைப்பை உடைக்கக்கூடும். தேவை என்று உறுதியாக இல்லாவிட்டால் இயக்கத்திலேயே விடவும்.',
