                'teams_step1' => 'Azure portal → Microsoft Entra ID → App registrations → New registration. "Single tenant" ஐத் தேர்ந்தெடுக்கவும், redirect URI வேண்டாம். Application (client) ID ஐ "Bot App ID" இலும், Directory (tenant) ID ஐக் கீழே உள்ள "Tenant ID" இலும் நகலெடுக்கவும்.',
                'teams_step2' => 'Certificates & secrets → New client secret. secret இன் Value ஐ (அதன் ID அல்ல) "App secret" இல் நகலெடுக்கவும். Azure அதை ஒருமுறை மட்டுமே காட்டுகிறது.',
                'teams_step3' => 'Azure Bot resource ஒன்றை உருவாக்கவும்: Single Tenant, ஏற்கனவே உள்ள app ஐப் (அதே App ID) பயன்படுத்தவும். அதன் Messaging endpoint ஐ சேனல் பட்டியலில் உள்ள webhook URL ஆக அமைத்து, Microsoft Teams சேனலை இயக்கவும்.',
                'teams_step4' => 'botId = App ID உடன் ஒரு Teams app manifest.json ஐ தொகுத்து, Teams Admin Center → Manage apps இல் பதிவேற்றவும். bot உடன் அரட்டையடிக்கும் பயனர்களுக்கு அதை அனுமதிக்கவும்.',
                'teams_step5' => 'அனுமதிகள்: எதுவுமில்லை. Microsoft Graph அனுமதிகளைச் சேர்க்க வேண்டாம். FreeITSM Bot Framework ஐ மட்டுமே பயன்படுத்துகிறது.',
                'teams_help_more' => 'முழு வழிகாட்டி (அதே படிகளுடன்):',
                'teams_download' => 'Teams app தொகுப்பைப் பதிவிறக்கு',
                'teams_download_help' => 'இந்த .zip ஐ Teams Admin Center → Manage apps இல் பதிவேற்றவும். இது இந்த சேனலின் App ID இலிருந்து உருவாக்கப்படுகிறது.',
                'teams_app_id' => 'Bot App ID',
                'teams_tenant_id' => 'Tenant ID',
                'teams_tenant_help' => 'bot பதிவு செய்யப்பட்டுள்ள Azure AD tenant (bot இன் app registration இலிருந்து).',
