        'loading' => 'ஏற்றுகிறது...',
        'merge' => [
            'reference_label' => 'டிக்கெட்டுகள் இணைக்கப்படும்போது, குறிப்பு எண் இவ்வாறு இருக்க வேண்டும்',
            'ref_survivor' => 'ஏற்கனவே உள்ள டிக்கெட்டுகளில் ஒன்று',
            'ref_survivor_help' => 'எந்த டிக்கெட் தொடர வேண்டும் என்பதை பகுப்பாய்வாளர் தேர்ந்தெடுக்கிறார், அது தனது குறிப்பு எண்ணை வைத்திருக்கும். மற்றவை மூடப்பட்டு, தங்கள் சொந்த குறிப்பு எண்களை வைத்திருந்து, அதைச் சுட்டிக்காட்டும். கோரிக்கையாளருக்கு ஏற்கனவே தெரிவிக்கப்பட்ட எதுவும் செயலற்ற குறிப்பாக மாறாது, அவர்களின் பழைய மின்னஞ்சல்களுக்கான பதில்களும் தொடர்ந்து வந்து சேரும்.',
            'ref_new' => 'புத்தம் புதிய டிக்கெட்',
            'ref_new_help' => 'இணைக்கப்பட்ட ஒவ்வொரு டிக்கெட்டும் மூடப்பட்டு, அவை அனைத்தையும் கொண்ட புதிய குறிப்பு எண் உருவாக்கப்படும். தூய்மையான தொடக்கம் — ஆனால் உங்கள் கோரிக்கையாளர்களிடம் ஏற்கனவே உள்ள ஒவ்வொரு குறிப்பு எண்ணும் மாற்றுவழியாக மாறும், புதிய டிக்கெட்டின் கடிகாரம் இன்றே தொடங்கும்.',
            'originals_label' => 'அசல் உரையாடல்கள் இவ்வாறு இருக்க வேண்டும்',
            'orig_thread' => 'இணைக்கப்பட்ட டிக்கெட்டுக்குள் நகர்த்தப்பட்டவை',
            'orig_thread_help' => 'ஒவ்வொரு செய்தியும் இணைக்கப்பட்ட டிக்கெட்டின் உரையாடலின் பகுதியாக மாறி, அது எந்த டிக்கெட்டிலிருந்து வந்தது என்று குறிக்கப்படும். உள்ளேயே படிக்கலாம், பதிலில் மேற்கோள் காட்டலாம், தேடலிலும் கிடைக்கும்.',
            'orig_thread_html' => 'நகர்த்தப்பட்டு, HTML கோப்புகளாகவும் இணைக்கப்பட்டவை',
            'orig_thread_html_help' => 'மேலே உள்ளபடி, கூடுதலாக ஒவ்வொரு அசல் டிக்கெட்டின் தனித்து இயங்கும் HTML நகல் இணைக்கப்பட்ட டிக்கெட்டில் இணைக்கப்படும் — FreeITSM க்கு வெளியே உள்ள ஒருவருக்கு முழுமையான பதிவை வழங்க வேண்டியிருக்கும்போது வசதியானது.',
            'orig_html' => 'HTML கோப்புகளாக மட்டும் இணைக்கப்பட்டவை',
            'orig_html_help' => 'செய்திகள் அவற்றின் அசல் டிக்கெட்டுகளிலேயே இருக்கும்; இணைக்கப்பட்ட டிக்கெட்டுக்கு இணைக்கப்பட்ட நகல்கள் மட்டுமே கிடைக்கும். மிகவும் ஒழுங்கான இணைக்கப்பட்ட டிக்கெட், ஆனால் தேடல் செய்திகளைப் படிக்கிறது, இணைப்புகளை அல்ல; எனவே இணைக்கப்பட்ட உரையாடல்கள் இனி தேடலில் கிடைக்காது.',
            'ai_label' => 'டிக்கெட்டுகள் இணைக்கப்படும்போது AI சுருக்கத்தை எழுது',
            'ai_help' => 'ஒவ்வொரு கோரிக்கையாளரும் என்ன கேட்டார், ஏற்கனவே என்ன செய்யப்பட்டுள்ளது என்பதைச் சுருக்கி இணைக்கப்பட்ட டிக்கெட்டில் ஒரு குறிப்பைச் சேர்க்கிறது; இதனால் அதை எடுப்பவர் ஒவ்வொரு உரையாடலையும் படிக்க வேண்டியதில்லை. Reply cleanup தத்தலில் AI வழங்குநர் உள்ளமைக்கப்பட்டிருக்க வேண்டும். அது இல்லாமலும் இணைப்பு வேலை செய்யும்.',
            'note' => 'இணைக்கப்பட்ட டிக்கெட்டுகள் ஒருபோதும் நீக்கப்படுவதில்லை. எந்த விருப்பத்தைத் தேர்ந்தெடுத்தாலும், பழைய குறிப்பு எண் எப்போதும் தேடக்கூடியதாக இருந்து அது எங்கு சென்றது என்பதைக் காட்டும் &mdash; அதைப் பற்றிய மின்னஞ்சலுக்கு வாடிக்கையாளர் பதிலளித்தாலும் அது உங்களை வந்தடையும்.',
            'saved' => 'இணைப்பு நடத்தை சேமிக்கப்பட்டது',
        ],
        'indexing' => [
            'cron_label' => 'அட்டவணைப்படி ஆவணங்களைப் படி',
            'cron_help' => 'ஒரு திட்டமிட்ட பணி காத்திருக்கும் ஆவணங்களைப் பின்னணியில் செயலாக்குகிறது. பரபரப்பான service desk க்கு இதுவே சரியான தீர்வு; உங்கள் சேவையகத்தில் திட்டமிட்ட பணி அமைக்கப்பட்டிருக்க வேண்டும். இது இல்லாவிட்டாலும் எதுவும் இழக்கப்படாது &mdash; கீழே உள்ள விருப்பத்தால் ஆவணங்கள் படிக்கப்படும், ஆனால் மெதுவாக.',
            'opportunistic_label' => 'FreeITSM பயன்பாட்டில் இருக்கும்போதெல்லாம் சிலவற்றைப் படி',
            'opportunistic_help' => 'யாரேனும் ஏற்கனவே FreeITSM இல் வேலை செய்யும்போது, காத்திருக்கும் ஆவணங்களில் சிலவற்றை எடுக்கிறது. இதனால் திட்டமிட்ட பணிகள் இல்லாத நிறுவலிலும் இணைப்புத் தேடல் உடனே வேலை செய்கிறது. யாரும் காத்திருக்காதபடி, ஒரு நேரத்தில் சிலவற்றை மட்டுமே எடுக்கும்படி வேண்டுமென்றே வடிவமைக்கப்பட்டுள்ளது.',
            'where_service' => '<strong>System &rarr; Integrations &rarr; Apache Tika</strong> இல் ஆவணம் படிக்கும் சேவை அமைக்கப்படும் வரை இந்த இரண்டு சுவிட்சுகளில் எதுவும் வேலை செய்யாது. Word, Excel, PowerPoint மற்றும் உரைக் கோப்புகள் எப்படியிருந்தாலும் உடனடியாகப் படிக்கப்படும்; இவற்றால் பாதிக்கப்படாது.',
            'saved' => 'அட்டவணையாக்க அமைப்புகள் சேமிக்கப்பட்டன',
        ],
        'reply_templates_empty' => 'பகிரப்பட்ட பதில் வார்ப்புருக்கள் இன்னும் இல்லை',
