        'scope' => [
            'field_label' => 'இதை யாருக்கு அனுப்புவது',
            'everyone' => 'அனைவருக்கும்',
            'restricted' => 'இந்த அனுப்புநர்களுக்கு மட்டும்',
            'rule_placeholder' => 'someone@example.com, அல்லது முழு டொமைனுக்கு example.com',
            'rule_help' => '@ உள்ள முகவரி அந்த ஒரு அனுப்புநருடன் பொருந்தும்; மற்றவை டொமைனாகக் கருதப்படும். மிகவும் குறிப்பிட்ட விதி வெல்லும்; எனவே சரியான முகவரியைக் குறிப்பிடும் டெம்ப்ளேட் அதன் டொமைனைக் குறிப்பிடும் டெம்ப்ளேட்டை மீறும், இரண்டும் அனைவருக்கும் செல்லும் டெம்ப்ளேட்டை மீறும். டெம்ப்ளேட்டுகள் தோன்றும் வரிசை எது அனுப்பப்படும் என்பதைப் பாதிக்காது.',
            'rule_invalid' => 'மின்னஞ்சல் முகவரியை அல்லது example.com போன்ற டொமைனை உள்ளிடவும்.',
            'rule_duplicate' => 'அது ஏற்கனவே பட்டியலில் உள்ளது.',
            'audience_requester' => 'கோரிக்கையாளர்',
            'audience_analyst' => 'ஒதுக்கப்பட்ட பகுப்பாய்வாளர்',
            'audience_title' => 'இந்த மின்னஞ்சலைப் பெறுபவர்',
            'badge_everyone' => 'அனைவருக்கும்',
            'badge_senders' => '{count} அனுப்புநர்(கள்)',
            'warn_title' => 'சில அனுப்புநர்களுக்கு பதிலே கிடைக்காது',
            'warn_body' => '{events}-க்கான ஒவ்வொரு செயலில் உள்ள டெம்ப்ளேட்டும் குறிப்பிட்ட அனுப்புநர்களுக்கு மட்டுப்படுத்தப்பட்டுள்ளது, எனவே அவற்றில் எதனுடனும் பொருந்தாதவர்களுக்கு எதுவும் கிடைக்காது. இது உங்கள் நோக்கம் அல்ல எனில், அனைவருக்கும் என அமைக்கப்பட்ட டெம்ப்ளேட்டைச் சேர்க்கவும். இது நடக்கும் இடங்களில், டிக்கெட்டிலும் அஞ்சல் பெட்டி அனுப்புதல் பதிவிலும் அனுப்பப்படவில்லை என பதிவு செய்யப்படும்.',
            'sim_label' => 'அனுப்புநருக்கு என்ன கிடைக்கும் என்பதைச் சரிபார்',
            'sim_placeholder' => 'someone@example.com',
            'sim_button' => 'சரிபார்',
            'sim_none' => 'பதில் எதுவும் அனுப்பப்படாது. இந்த முகவரி அந்த நிகழ்வுக்கான எந்த டெம்ப்ளேட்டுடனும் பொருந்தவில்லை, மேலும் அவற்றில் எதுவும் அனைவருக்கும் பொருந்தாது.',
            'sim_no_template' => 'பதில் எதுவும் அனுப்பப்படாது, ஏனெனில் அந்த நிகழ்வுக்கு செயலில் உள்ள டெம்ப்ளேட் எதுவும் இல்லை.',
            'sim_address' => 'அனுப்பப்படும், ஏனெனில் ஒரு விதி இந்தச் சரியான முகவரியைக் குறிப்பிடுகிறது ({value}).',
            'sim_domain' => 'அனுப்பப்படும், ஏனெனில் ஒரு விதி டொமைன் {value}-ஐக் குறிப்பிடுகிறது.',
            'sim_everyone' => 'அனுப்பப்படும், ஏனெனில் அது அனைவருக்கும் பொருந்தும், மேலும் இன்னும் குறிப்பிட்ட டெம்ப்ளேட் எதுவும் பொருந்தவில்லை.',
        ],
        'base_url' => [
            'label' => 'பொது வலை முகவரி',
            'placeholder' => 'https://itsm.example.com',
            'help' => '[ticket_url] மற்றும் FreeITSM அனுப்பும் பிற இணைப்புகளை உருவாக்கப் பயன்படுகிறது. FreeITSM தளத்தின் ரூட்டில் இல்லை எனில் கோப்புறையையும் சேர்க்கவும், எடுத்துக்காட்டாக https://itsm.example.com/freeitsm. இதை காலியாக விட்டால், இரவு நேர அஞ்சல் சேகரிப்பான் அனுப்பும் இணைப்புகளில் தளப் பெயர் இருக்காது, ஏனெனில் அந்த நேரத்தில் அதைக் கண்டறிய உலாவி கோரிக்கை எதுவும் இல்லை.',
            'example' => 'தற்போது ஒரு டிக்கெட் இணைப்பு இவ்வாறு வருகிறது:',
            'inherited' => 'இங்கே ஒன்றைச் சேமிக்கும் வரை உங்கள் வெப் சாட் அமைப்பிலிருந்து எடுக்கப்படுகிறது.',
            'saved' => 'பொது வலை முகவரி சேமிக்கப்பட்டது',
            'save_failed' => 'பொது வலை முகவரியைச் சேமிக்க முடியவில்லை',
            'warn_title' => 'இந்த மின்னஞ்சல்களில் உள்ள இணைப்புகள் வேலை செய்யாது',
            'warn_body' => '[ticket_url] {count} டெம்ப்ளேட்(களில்) பயன்படுத்தப்படுகிறது, ஆனால் பொது வலை முகவரி அமைக்கப்படவில்லை. நீங்கள் கிளிக் செய்து பார்க்கும்போது இது வேலை செய்கிறது, ஆனால் இரவில் அனுப்பப்படும் அஞ்சலில் தோல்வியடைகிறது — இந்த டெம்ப்ளேட்டுகள் பொதுவாக அப்போதுதான் அனுப்பப்படுகின்றன.',
        ],
        'checklists' => [
            'per_template_title' => 'ஒவ்வொரு சரிபார்ப்புப் பட்டியலிலும் உள்ள அமைப்பைப் பின்பற்று (பரிந்துரைக்கப்படுகிறது)',
            'per_template_desc' => 'ஒவ்வொரு சரிபார்ப்புப் பட்டியலும் அதை எழுதியவர் தேர்ந்தெடுத்த தனது சொந்த வாயிலைக் கொண்டுள்ளது: Standard பகுப்பாய்வாளரை எச்சரித்து மீறலைப் பதிவு செய்கிறது, Critical கட்டாயப் படிகள் அனைத்தும் தேர்வு செய்யப்படும் வரை மூடுவதை மறுக்கிறது.',
            'block_all_title' => 'நிலுவையில் படிகள் உள்ள ஒவ்வொரு டிக்கெட்டையும் தடு',
            'block_all_desc' => 'சரிபார்ப்புப் பட்டியல்களையே மீறுகிறது: பட்டியல் என்ன சொன்னாலும், கட்டாயப் படிகள் அனைத்தும் தேர்வு செய்யப்படும் வரை எந்த டிக்கெட்டும் மூடப்பட்ட நிலையை அடையாது. எதிர் திசையில் அமைப்பு வேண்டுமென்றே இல்லை — Critical சரிபார்ப்புப் பட்டியலைத் தளர்த்த, அதைப் பின்பற்றுபவர்கள் மாற்றத்தைக் காணக்கூடிய சரிபார்ப்புப் பட்டியலையே திருத்தவும்.',
            'empty_section_title' => 'சரிபார்ப்புப் பட்டியல் இணைக்கப்படாத டிக்கெட்டை மூடுதல்',
            'empty_section_desc' => 'சில குழுக்கள் ஒவ்வொரு டிக்கெட்டும் ஒரு நடைமுறையைப் பின்பற்றியிருக்க வேண்டும் என விரும்புகின்றன. பெரும்பாலானவை விரும்புவதில்லை — கடவுச்சொல் மீட்டமைப்புக்கு சரிபார்ப்புப் பட்டியல் தேவையில்லை, அதை வலியுறுத்துவது அதற்கு மிகவும் தகுதியற்ற டிக்கெட்டுகளில் சிரமத்தைச் சேர்க்கிறது.',
            'empty_off_title' => 'அனுமதி (இயல்புநிலை)',
            'empty_off_desc' => 'சரிபார்ப்புப் பட்டியல் இல்லாத டிக்கெட் மற்றவற்றைப் போலவே மூடப்படும்.',
            'empty_warn_title' => 'எச்சரித்து, பதிவு செய்',
            'empty_warn_desc' => 'பகுப்பாய்வாளரிடம் உறுதிப்படுத்தக் கேட்கப்பட்டு இணைப்பு உரையாடல் வழங்கப்படுகிறது. எப்படியும் மூடினால், டிக்கெட் சரிபார்ப்புப் பட்டியல் இல்லாமல் மூடப்பட்டது என்றும் யார் மூடினார் என்றும் கூறும் உள் குறிப்பு எழுதப்படும்.',
            'empty_block_title' => 'மூடுவதை மறு',
            'empty_block_desc' => 'குறைந்தது ஒரு சரிபார்ப்புப் பட்டியல் இணைக்கப்படும் வரை டிக்கெட் மூடப்பட்ட நிலையை அடைய முடியாது.',
            'always_recorded' => 'எப்படியிருந்தாலும், படிகள் நிலுவையில் இருக்கும்போது மூடினால், தவிர்க்கப்பட்ட படிகள், யார் மூடினார், எந்த இடைமுகம் வழியாக என்பதைக் குறிப்பிடும் உள் குறிப்பு எழுதப்படும். இந்த அமைப்புகள் அதை அனுமதிப்பதா என்பதை முடிவு செய்கின்றன, பதிவு செய்யப்படுவதா என்பதை ஒருபோதும் அல்ல.',
        ],
        'custom_fields' => [
