            'f_req_create_hint' => 'புதிய டிக்கெட் படிவம், REST API மற்றும் - கோரிக்கையாளரிடம் கேட்கப்பட்டால் - போர்டலில். மின்னஞ்சல் அல்லது சாட் மூலம் வரும் டிக்கெட்டுகளிடம் கேட்க முடியாது, எனவே அதற்காக அவை மறுக்கப்படாது.',
            'f_req_close' => 'டிக்கெட் மூடப்படுவதற்கு முன்',
