            'f_ask' => 'போர்டலில் கோரிக்கையாளரிடம் கேள்',
            'f_ask_hint' => 'கோரிக்கையாளர் இந்தப் புலத்தின் வகைகளில் ஒன்றைத் தேர்ந்தெடுக்கும்போது போர்டலின் புதிய டிக்கெட் படிவத்தில் காட்டப்படும். உங்கள் குழு மட்டுமே நிரப்ப வேண்டியவற்றுக்கு இதை அணைத்து வைக்கவும்.',
