            'need_types' => 'குறைந்தது ஒரு டிக்கெட் வகையைத் தேர்ந்தெடுக்கவும், அல்லது அனைத்து டிக்கெட் வகைகள் என்பதைத் தேர்வு செய்யவும்.',
            'need_options' => 'கீழ்விரிக்கு குறைந்தது ஒரு விருப்பம் தேவை.',
