        'mandatory' => [
            'when_heading' => 'தேர்வு செய்யப்பட்ட புலம் காலியாக இருக்கும்போது டிக்கெட் மூடப்பட்டால்',
            'warn_title' => 'எச்சரி',
            'warn_desc' => 'எந்தப் புலங்கள் காலியாக உள்ளன என்பது பகுப்பாய்வாளருக்குச் சொல்லப்படும், அவர் எப்படியும் மூடலாம்.',
            'notify_title' => 'எச்சரித்து, ஒருவருக்கு மின்னஞ்சல் அனுப்பு',
            'notify_desc' => 'அதே, மேலும் கீழே உள்ளவர்களுக்கு டிக்கெட், காலியான புலங்கள் மற்றும் யார் மூடினார் என்பதைக் குறிப்பிடும் மின்னஞ்சல் கிடைக்கும் - எடுத்துக்காட்டாக, சேவை வழங்கல் மேலாளர்.',
            'notify_label' => 'மின்னஞ்சலை இவருக்கு அனுப்பு',
            'notify_placeholder' => 'name@example.com, another@example.com',
            'block_title' => 'மூடுவதை மறு',
            'block_desc' => 'தேர்வு செய்யப்பட்ட புலங்கள் அனைத்தும் நிரப்பப்படும் வரை டிக்கெட் மூடப்பட்ட நிலையை அடைய முடியாது.',
            'record_title' => 'டிக்கெட்டில் பதிவு செய்',
            'record_desc' => 'காலியான புலங்கள், யார் டிக்கெட்டை மூடினார் மற்றும் எப்படி என்பதைக் குறிப்பிடும் உள் குறிப்பை எழுதுகிறது. இரண்டு எச்சரிக்கை விருப்பங்களுக்கு மட்டுமே பொருந்தும் - மறுக்கப்பட்ட மூடுதல் எதையும் மாற்றாது, எனவே பதிவு செய்ய எதுவும் இல்லை.',
            'record_blocked' => 'மூடுதல் மறுக்கப்படும்போது எதுவும் பதிவு செய்யப்படாது, ஏனெனில் டிக்கெட் மூடப்படுவதில்லை.',
            'fields_heading' => 'மூடுவதற்கு முன் நிரப்பப்பட வேண்டியவை',
            'fields_hint' => 'ஒரு டிக்கெட்டின் நிறுவனத்திற்கு அணைக்கப்பட்ட புலம், அல்லது குழுக்கள் இல்லாத நிறுவலில் உள்ள குழு புலம், அந்த டிக்கெட்டுக்கு தவிர்க்கப்படும் - தங்களால் பார்க்க முடியாத ஒன்றை நிரப்ப யாரிடமும் கேட்கப்படாது. டிக்கெட்டுகளை இணைப்பது இதை ஒருபோதும் தூண்டாது.',
            'choose_mode' => 'புலங்கள் காலியாக இருக்கும்போது என்ன நடக்க வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும்.',
            'need_address' => 'மின்னஞ்சல் அனுப்ப குறைந்தது ஒரு முகவரியைச் சேர்க்கவும்.',
            'fields' => [
