        ],
        'intros' => [
            'custom_fields' => 'ஒரு வகை டிக்கெட்டுக்குத் தேவையான கூடுதல் விவரங்களை உருவாக்கவும் - எடுத்துக்காட்டாக புதிய பணியாளருக்கு தொடக்கத் தேதி மற்றும் பயனர்பெயர் - மேலும் ஒவ்வொன்றும் எந்த டிக்கெட் வகைகளில் இருக்க வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும். டிக்கெட் பதிவு செய்யப்படும்போது, மூடப்படும்போது அல்லது இரண்டிலும் ஒவ்வொரு புலமும் நிரப்பப்பட வேண்டுமா என்பதையும், போர்டலில் கோரிக்கையாளரிடம் அது கேட்கப்பட வேண்டுமா என்பதையும் அதுவே தீர்மானிக்கிறது.',
            'checklists' => 'ஒரு சரிபார்ப்புப் பட்டியல் படிகளைக் கட்டாயம் எனக் குறிக்கலாம். அந்தப் படிகள் தேர்வு செய்யப்படுவதற்கு முன் யாராவது டிக்கெட்டை மூடினால் என்ன நடக்கும் என்பதை இது தீர்மானிக்கிறது.',
            'mandatory_fields' => 'டிக்கெட் மூடப்படுவதற்கு முன் எந்த டிக்கெட் புலங்கள் நிரப்பப்பட வேண்டும், அவற்றில் ஏதேனும் காலியாக இருக்கும்போது யாராவது மூடினால் என்ன நடக்கும் என்பதைத் தேர்ந்தெடுக்கவும். டிக்கெட்டை மூடக்கூடிய எல்லா இடங்களிலும் இந்த விதி பொருந்தும்: டிக்கெட் திரை, மொத்தச் செயல்கள், REST API மற்றும் பணிப்பாய்வுகள்.',
            'departments' => 'துறைகள் டிக்கெட்டுகளைக் குழுவாக்கி உங்கள் நிறுவனத்தின் சரியான பகுதிக்கு வழிநடத்துகின்றன — உங்கள் சேவை மேசை பணிகளை வகைப்படுத்தவும் ஒதுக்கவும் பயன்படுத்துபவற்றை உருவாக்கவும்.',
            'teams' => 'பகுப்பாய்வாளர்கள் எந்தத் துறைகளை அணுகலாம் என்பதை குழுக்கள் தீர்மானிக்கின்றன. துறைகளை குழுக்களுக்கு ஒதுக்கி, பின்னர் அணுகலைக் கட்டுப்படுத்த பகுப்பாய்வாளர்களை குழுக்களுக்கு ஒதுக்கவும்.',
            'ticket_types' => 'டிக்கெட் வகைகள் ஒரு கோரிக்கை என்ன என்பதை வகைப்படுத்துகின்றன (எ.கா. Incident, Service Request) — டிக்கெட்டில் பகுப்பாய்வாளர்கள் அமைக்கக்கூடிய வகைகளை வரையறுக்கவும்.',
            'ticket_origins' => 'டிக்கெட் மூலங்கள் டிக்கெட் எப்படி வந்தது என்பதைப் பதிவு செய்கின்றன (எ.கா. Email, Phone, Portal) — பகுப்பாய்வாளர்கள் தேர்ந்தெடுக்கக்கூடிய மூலங்களை வரையறுக்கவும்.',
            'mailboxes' => 'அஞ்சல் பெட்டிகள் FreeITSM-ஐ மின்னஞ்சல் கணக்குகளுடன் இணைக்கின்றன, இதனால் உள்வரும் செய்திகள் டிக்கெட்டுகளாகின்றன, பதில்கள் வெளியே செல்கின்றன — உங்கள் சேவை மேசை கண்காணிப்பவற்றைச் சேர்த்து அங்கீகரிக்கவும்.',
            'privacy' => 'டிக்கெட் என்பது அதை எழுப்பியவருடனான உங்கள் உரையாடலை மட்டும் கொண்டிருக்காது. சப்ளையருக்கு அனுப்புவது அல்லது சக ஊழியரை நகலில் சேர்ப்பது அந்தச் செய்தியை அதே டிக்கெட்டில் வைக்கிறது — அவர்களின் பதிலும் அங்கேயே வந்து சேரும். சுய சேவை போர்டலில் கோரிக்கையாளர் இதில் எவ்வளவு காண்கிறார் என்பதை இது தீர்மானிக்கிறது.',
            'indexing' => 'இணைப்புகளுக்குள் உள்ள உரை தேடப்படுவதற்காக படிக்கப்படுகிறது. Word, Excel, PowerPoint மற்றும் எளிய உரைக் கோப்புகளை அவை வந்த கணமே FreeITSM தானே படிக்கிறது. PDF-கள், பழைய Office கோப்புகள் மற்றும் ஸ்கேன் செய்த ஆவணங்களுக்கு தனி ஆவணம்-படிக்கும் சேவை தேவை — அதை <strong>System &rarr; Integrations &rarr; Apache Tika</strong> இல் அமைக்கவும் — அவை அதிக நேரம் எடுப்பதால், பின்னணியில் படிக்கப்படுகின்றன. அந்தப் பின்னணி வேலை எப்போது நடக்கும் என்பதை இந்த இரண்டு சுவிட்சுகள் தீர்மானிக்கின்றன.',
            'merge_behaviour' => 'இரண்டு டிக்கெட்டுகள் ஒன்றே என்று தெரியவரும்போது, பகுப்பாய்வாளர் அவற்றை இணைக்கலாம். உங்கள் கோரிக்கையாளர்கள் வைத்திருக்கும் டிக்கெட் குறிப்பு எண்களுக்கும், உரையாடல்களுக்கும் இது என்ன செய்கிறது என்பதை இந்த அமைப்புகள் தீர்மானிக்கின்றன. இவை அனைவருக்கும் பொருந்தும் — இணைப்பு வாடிக்கையாளர் காண்பதை மாற்றுகிறது, எனவே ஒரே அஞ்சல் பெட்டியில் உள்ள இரண்டு பகுப்பாய்வாளர்கள் இதில் மாறுபட அனுமதிக்கக் கூடாது.',
            'reply_templates' => 'பகுப்பாய்வாளர்கள் மீண்டும் தட்டச்சு செய்வதற்குப் பதிலாக பதிலில் சேர்க்கக்கூடிய தயார் பதில்கள். இவை முழுக் குழுவும் காணும் பகிரப்பட்டவை — பகுப்பாய்வாளரின் சொந்த தனிப்பட்ட டெம்ப்ளேட்டுகள் பதில் சாளரத்திலிருந்து சேமிக்கப்படுகின்றன, இங்கே பட்டியலிடப்படாது.',
            'rota_shifts' => 'ஷிப்டுகள் என்பவை பணி அட்டவணையில் பகுப்பாய்வாளர்களுக்கு ஒதுக்கப்படும் பணி முறை டெம்ப்ளேட்டுகள் (எ.கா. Early, Late, On-call) — பணி அட்டவணையை உருவாக்கும் முன் அவற்றை இங்கே வரையறுக்கவும்.',
            'analysts' => 'பகுப்பாய்வாளர்கள் உள்நுழைந்து டிக்கெட்டுகளில் பணியாற்றும் பணியாளர்கள் — அவர்களைச் சேர்க்கவும், கடவுச்சொற்களை மீட்டமைக்கவும், அவர்களின் அணுகலைக் கட்டுப்படுத்த குழுக்களுக்கு ஒதுக்கவும்.',
            'general' => 'பொது அமைப்புகள் டிக்கெட்டுகள் எப்படி நடந்துகொள்கின்றன என்பதைக் கட்டுப்படுத்துகின்றன - மீண்டும் திறத்தல், ஒத்திவைத்தல், செய்திகளும் இழைகளும் எவ்வளவு நேரம் காட்டப்படுகின்றன.',
            'statuses' => 'டிக்கெட் இருக்கக்கூடிய பணிப்பாய்வு நிலைகள். <em>Closed</em> எனக் குறிக்கப்பட்ட நிலைகள் முடிவானவையாகக் கருதப்படுகின்றன — அறிக்கைகள், watchtower கவுண்டர்கள் மற்றும் ஒதுக்கும்போது மூடிய-தேதிநேரம் தானாக அமைக்கப்படுவதில் பயன்படுத்தப்படுகின்றன. புதிய டிக்கெட்டுகளுக்கு சரியாக ஒரு நிலை இயல்புநிலையாக இருக்கும்.',
            'priorities' => 'டிக்கெட்டுகளில் காட்டப்படும் முன்னுரிமை வரம்புகள். புதிய டிக்கெட்டுகளுக்கு சரியாக ஒரு முன்னுரிமை இயல்புநிலையாக இருக்கும்.',
            'rota_locations' => 'ஒரு குறிப்பிட்ட நாளில் ஒவ்வொரு பகுப்பாய்வாளரும் எங்கே பணியாற்றுகிறார் — பணி அட்டவணையால் பயன்படுத்தப்பட்டு ஒவ்வொரு பதிவிலும் நிறமுள்ள பேட்ஜாகக் காட்டப்படுகிறது. புதிய பணி அட்டவணைப் பதிவுகளுக்கு சரியாக ஒரு இடம் இயல்புநிலையாக இருக்கும்.',
            'email_templates' => 'டிக்கெட் நிகழ்வுகளால் தூண்டப்படும் தானியங்கி மின்னஞ்சல் பதில்கள். ஒவ்வொரு நிகழ்வுக்கும் செயலில் உள்ள முதல் டெம்ப்ளேட் மட்டுமே பயன்படுத்தப்படும்.',
        ],
        'messaging' => [
            'channels_heading' => 'செய்தி சேனல்கள்',
            'channels_intro' => 'வாடிக்கையாளர்கள் WhatsApp வழியாக பகுப்பாய்வாளருடன் சாட் செய்ய அனுமதிக்கவும் — ஒவ்வொரு செய்தியும் மின்னஞ்சலைப் போலவே டிக்கெட்டாகிறது. கீழே ஒரு சேனலைச் சேர்த்து, உள்வரும் செய்திகள் இந்த நிறுவலை அடைய அதன் <strong>webhook URL</strong>-ஐ உங்கள் வழங்குநரில் (Twilio அல்லது Meta) ஒட்டவும்.',
            'base_url_label' => '<strong>பொது அடிப்படை URL</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (அல்லது சோதிக்கும்போது உங்கள் ngrok முகவரி)',
            'base_url_help' => 'வழங்குநர்கள் இந்த நிறுவலை அடையப் பயன்படுத்தும் முகவரி. இதை அமைத்தால் கீழே உள்ள webhook URL-கள் நகலெடுத்து ஒட்டத் தயாராகும். நீங்கள் உலாவும் முகவரியையே பயன்படுத்த காலியாக விடவும். உள்ளூரில் சோதிக்கிறீர்களா? <code>ngrok http 80</code> இயக்கி, அது காட்டும் <code>https://…ngrok-free.dev</code> முகவரியை ஒட்டவும்.',
            'templates_heading' => 'செய்தி டெம்ப்ளேட்டுகள்',
            'templates_intro' => 'முன்-அங்கீகரிக்கப்பட்ட டெம்ப்ளேட்டுகள் <strong>24-மணி நேர சாளரம் முடிந்த பிறகும்</strong> பகுப்பாய்வாளர் பதிலளிக்க அனுமதிக்கின்றன. வாடிக்கையாளரின் கடைசி செய்திக்குப் பிறகு 24 மணி நேரத்திற்குள் மட்டுமே WhatsApp இலவச உரையை அனுமதிக்கிறது; அதற்கு வெளியே Meta/Twilio அங்கீகரித்த டெம்ப்ளேட்டை மட்டுமே அனுப்ப முடியும். உங்கள் வழங்குநரிடம் டெம்ப்ளேட்டை உருவாக்கி அங்கீகரித்து, பின்னர் அதன் வரையறையை (<code>{{1}}</code>, <code>{{2}}</code> இடப்பிடிப்பாளர்களுடன்) இங்கே சேர்க்கவும், இதனால் பகுப்பாய்வாளர்கள் தேர்ந்தெடுத்து நிரப்பலாம்.',
        ],
        'webchat' => [
            'heading' => 'வெப் சாட் விட்ஜெட்டுகள்',
            'intro' => 'எந்த இணையதளத்திலும் சாட் சாளரத்தை வைக்கவும் — பார்வையாளர் செய்தியை தட்டச்சு செய்தால் அது டிக்கெட்டாகிறது, பகுப்பாய்வாளர்கள் மற்ற சேனலைப் போலவே இன்பாக்ஸிலிருந்து பதிலளிக்கிறார்கள். கீழே ஒரு விட்ஜெட்டைச் சேர்த்து, அதன் embed snippet-ஐ தளத்தில் ஒட்டவும்.',
            'col_key' => 'விட்ஜெட் விசை',
            'col_origins' => 'இணையதளம்(கள்)',
            'any_origin' => 'ஏதேனும் (கட்டுப்படுத்தப்படவில்லை)',
            'add_title' => 'வெப் சாட் விட்ஜெட்டைச் சேர்',
            'edit_title' => 'வெப் சாட் விட்ஜெட்டைத் திருத்து',
            'name' => 'பெயர்',
            'name_placeholder' => 'எ.கா. Acme இணையதளம்',
            'company' => 'நிறுவனம்',
            'company_help' => 'இந்த விட்ஜெட்டிலிருந்து வரும் ஒவ்வொரு உரையாடலையும் ஒரு நிறுவனத்துடன் பிணைக்கவும். ஒற்றை-நிறுவன நிறுவலில் அமைக்காமல் விடவும்.',
            'greeting' => 'வரவேற்பு',
            'greeting_placeholder' => 'வணக்கம்! நாங்கள் எப்படி உதவலாம்?',
            'accent' => 'அழுத்த நிறம்',
            'launcher' => 'துவக்கி உரை',
            'launcher_placeholder' => 'எங்களுடன் சாட் செய்யுங்கள்',
            'origins' => 'அனுமதிக்கப்பட்ட இணையதளம்(கள்)',
            'origins_help' => 'ஒரு வரிக்கு ஒரு origin (எ.கா. https://acme.com). இந்தத் தளங்கள் மட்டுமே விட்ஜெட்டைக் காட்டலாம். எந்தத் தளத்தையும் அனுமதிக்க காலியாக விடவும் (சோதனைக்கு மட்டும்).',
            'offline' => 'ஆஃப்லைன் செய்தி',
            'offline_placeholder' => 'நாங்கள் இப்போது கிடைக்கவில்லை — உங்கள் செய்தியை விட்டுச் செல்லுங்கள், நாங்கள் மின்னஞ்சலில் பதிலளிப்போம்.',
            'require_email' => 'சாட் செய்வதற்கு முன் பார்வையாளர்களிடம் பெயர் மற்றும் மின்னஞ்சல் கேள்',
            'active' => 'செயலில்',
            'embed_label' => 'Embed snippet',
            'embed_help' => 'சாட் சாளரத்தைக் காட்ட வேண்டிய ஒவ்வொரு பக்கத்திலும் முடிவு &lt;/body&gt; குறிச்சொல்லுக்கு சற்று முன் இதை ஒட்டவும்.',
            'embed_after_save' => 'விட்ஜெட்டைச் சேமித்ததும் embed snippet இங்கே தோன்றும்.',
            'avail_heading' => 'கிடைக்கும் நேரம்',
            'business_hours' => 'அலுவலக நேரம்',
            'always_open' => 'எப்போதும் திறந்திருக்கும்',
            'business_hours_help' => 'இந்த நேரங்களுக்கு வெளியே விட்ஜெட் உங்கள் ஆஃப்லைன் செய்தியைக் காட்டி, விசாரணையை பின்னர் பதிலளிக்க டிக்கெட்டாக ஏற்கிறது. நாட்காட்டிகள் SLA அமைப்புகளில் நிர்வகிக்கப்படுகின்றன.',
            'email_heading' => 'மின்னஞ்சல்',
