            'heading' => 'சேவை நிலை ஒப்பந்தங்கள்',
            'intro' => 'ஒவ்வொரு முன்னுரிமைக்கும் தனி பதில் மற்றும் தீர்வு இலக்குகளுடன், வணிக நேரத்தை அறியும் SLA-க்கள். <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">நிலைகள் தாவலில்</a> "SLA-ஐ இடைநிறுத்து" எனக் குறிக்கப்பட்ட நிலைகளில் கடிகாரம் நிற்கும். <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">வடிவமைப்புக் குறிப்புகளைப்</a> பாருங்கள்.',
