            'notify_lead' => 'மீறலில் குழுத் தலைவருக்கு மின்னஞ்சல் அனுப்பு',
            'save_global' => 'பொது அமைப்புகளைச் சேமி',
            'targets_heading' => 'முன்னுரிமைக்கு ஏற்ப SLA இலக்குகள்',
            'targets_intro' => 'ஒவ்வொரு டிக்கெட் முன்னுரிமைக்கும் பதில் மற்றும் தீர்வு நேரங்கள். நேரங்கள் நிமிடங்களில் (60 = 1 மணிநேரம், 240 = 4 மணிநேரம், 1440 = 1 நாள்). கடிகாரம் எந்த வணிக நேரங்களின்படி ஓடும் என்பதை நாட்காட்டி தீர்மானிக்கிறது. அந்த இலக்கைத் தவிர்க்க வெறுமையாக விடவும்.',
            'col_priority' => 'முன்னுரிமை',
            'col_response_mins' => 'பதில் (நிமி)',
            'col_resolution_mins' => 'தீர்வு (நிமி)',
            'col_calendar' => 'நாட்காட்டி',
            'col_save' => 'சேமி',
            'calendars_heading' => 'வணிக நாட்காட்டிகள்',
            'calendars_intro' => 'வேலை நேரங்கள், நேர மண்டலங்கள் மற்றும் விடுமுறைப் பட்டியல்களை வரையறுக்கவும். நாட்காட்டிகள் (மேலே உள்ள) SLA இலக்குகளாலும் தனிப்பட்ட முன்னுரிமைகளாலும் குறிப்பிடப்படுகின்றன. புதிய முன்னுரிமைகளுக்கு ஒரு நாட்காட்டி இயல்புநிலையாக இருக்கும்.',
            'col_name' => 'பெயர்',
            'col_timezone' => 'நேர மண்டலம்',
            'col_hours' => 'நேரங்கள்',
            'col_holidays' => 'விடுமுறைகள்',
            'col_default' => 'இயல்புநிலை',
            'col_actions' => 'செயல்கள்',
            'notifs_heading' => 'மீறல் அறிவிப்புகள்',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">அறிவிப்பு விதிகள் எவ்வாறு செயல்படுகின்றன</strong>ஒவ்வொரு விதிக்கும் நான்கு பகுதிகள் உள்ளன: ஒரு <strong>நோக்கெல்லை</strong>, ஒரு <strong>தூண்டுதல்</strong>, ஒரு <strong>இலக்கு</strong>, மற்றும் <strong>பெறுநர்களின்</strong> பட்டியல்.<br><br><strong>நோக்கெல்லை</strong> என்பது <em>இயல்புநிலை</em> (விதி ஒவ்வொரு துறையின் டிக்கெட்டுகளுக்கும் பொருந்தும்) அல்லது <em>குறிப்பிட்ட துறை</em> (விதி அந்தத் துறையின் டிக்கெட்டுகளுக்கு மட்டுமே பொருந்தும்) ஆக இருக்கலாம்.<br>ஒரு டிக்கெட் மதிப்பிடப்படும்போது, கணினி முதலில் அதன் துறைக்குப் பொருந்தும் விதியைத் தேடுகிறது &mdash; ஒன்று இருந்தால், அந்த விதியே செல்லும்; இயல்புநிலை புறக்கணிக்கப்படும். துறை சார்ந்த விதி இல்லையென்றால், இயல்புநிலை விதி பயன்படுத்தப்படும். இவ்வாறு ஒவ்வொரு துறையையும் உள்ளடக்கும் நியாயமான இயல்புநிலைகளை அமைத்து, ஒரு குழுவுக்கு வேறுபட்ட அதிகரிப்புத் தேவைகள் இருக்கும் இடங்களில் விதிவிலக்குகளை உருவாக்கலாம்.<br><br><strong>தூண்டுதல்</strong> என்பது <em>எச்சரிக்கை</em> (டிக்கெட் எச்சரிக்கை வரம்பைத் தாண்டிவிட்டது &mdash; மீறல் நெருங்குகிறது) அல்லது <em>மீறல்</em> (டிக்கெட் இப்போது அதன் SLA இலக்கைத் தாண்டிவிட்டது &mdash; உண்மையான மீறல்) ஆகும். ஒவ்வொன்றும் தனி விதி, எனவே எச்சரிக்கைகளுக்கும் மீறல்களுக்கும் வெவ்வேறு நபர்களுக்கு அறிவிக்கலாம்.<br><br><strong>இலக்கு</strong> என்பது எந்த SLA கடிகாரத்தைக் கவனிப்பது &mdash; <em>பதில்</em>, <em>தீர்வு</em>, அல்லது <em>இரண்டும்</em>.<br><br><strong>பெறுநர்கள்</strong> பின்வருவனவற்றின் எந்தக் கலவையாகவும் இருக்கலாம்: டிக்கெட்டின் தற்போதைய ஒதுக்கப்பட்டவர், டிக்கெட்டின் துறைக் குழுக்களில் உள்ள ஒவ்வொரு பகுப்பாய்வாளர், பெயரிடப்பட்ட ஒரு பகுப்பாய்வாளர், மற்றும்/அல்லது தன்னிச்சையான மின்னஞ்சல் முகவரிகளின் பட்டியல் (பகிர்ந்த இன்பாக்ஸ்கள் அல்லது Slack/Teams மின்னஞ்சல் பாலங்களுக்குப் பயனுள்ளது).<br><br><strong style="color:var(--warning-text, #92400e);">விதிகள் இல்லை = மின்னஞ்சல்கள் இல்லை.</strong> ஒரு டிக்கெட் மீறினாலும், குறைந்தது ஒரு விதியைச் சேர்க்கும் வரை எதுவும் அனுப்பப்படாது (அனைத்தையும் உள்ளடக்க, இயல்புநிலை நோக்கெல்லையில் ஒரு எச்சரிக்கை + மீறல் ஜோடியுடன் தொடங்குங்கள்).',
            'notifs_dedup' => 'ஒவ்வொரு டிக்கெட்டும் ஒரு இலக்குக்கு, ஒரு தூண்டுதலுக்கு அதிகபட்சம் ஒரு மின்னஞ்சலை அனுப்பும் &mdash; ஏற்கனவே அனுப்பப்பட்டதை cron worker கண்காணிப்பதால் நகல்கள் வராது.',
            'col_scope' => 'நோக்கெல்லை',
            'col_trigger' => 'தூண்டுதல்',
            'col_target' => 'இலக்கு',
            'col_recipients' => 'பெறுநர்கள்',
            'col_active' => 'செயலில்',
            'notifs_cron_note' => 'இந்த மின்னஞ்சல்களை அனுப்பும் cron worker <code>cron/sla_breach_check.php</code> இல் உள்ளது. Windows Task Scheduler + Linux cron அமைப்புக்கு <code>docs/sla-cron-setup.md</code> ஐப் பாருங்கள்.',
            'cron_heading' => 'Cron செயல்பாடு',
            'cron_refresh' => 'புதுப்பி',
            'cron_intro' => 'மீறல்-சரிபார்ப்பு cron இன் கடைசி <span id="slaCronRunsLimit">20</span> இயக்கங்கள் (CLI மற்றும் HTTP). நிராகரிக்கப்பட்ட கோரிக்கைகளும் (வீத வரம்பு, அங்கீகாரத் தோல்வி) உள்ளடங்கும்; இதனால் அதே தரவு மூலம் வீத வரம்புச் சரிபார்ப்புகளையும் பாதுகாப்புத் தணிக்கைகளையும் ஆதரிக்கிறது. <strong><span id="slaCronRetentionDays">30</span> நாட்களுக்குப்</strong> பிறகு தானாக நீக்கப்படும்; வெற்றிகரமான இயக்கங்களுக்கு இடையிலான குறைந்தபட்ச இடைவெளி <strong><span id="slaCronMinInterval">30</span> வி</strong> (இரண்டும் <code>system_settings</code> இல் மாற்றக்கூடியவை).',
