        'dept_confidential' => [
            'label' => 'இங்குள்ள டிக்கெட்டுகள் ரகசியமானவை',
            'help' => 'இந்தத் துறையில் உள்ள அல்லது இதற்கு நகர்த்தப்படும் ஒவ்வொரு டிக்கெட்டும் ரகசியமானது எனக் குறிக்கப்படும்; எனவே கோரிக்கையாளரின் மேலாளர்களிடமிருந்து மறைக்கப்படும். இதை இயக்கினால், ஏற்கனவே இங்குள்ள டிக்கெட்டுகளும் குறிக்கப்படும். முடக்கினால் எந்த டிக்கெட்டும் மாறாது - ஒன்றை மீண்டும் இயல்பானதாக்க, டிக்கெட்டிலேயே மாற்றுங்கள்.',
            'chip' => 'ரகசியமானது',
