            'help' => 'HR போன்ற அஞ்சல் பெட்டிக்கானது. இங்கு வரும் ஒவ்வொரு டிக்கெட்டும் யாரும் படிக்கும் முன்பே, வந்த கணத்திலேயே ரகசியமானது எனக் குறிக்கப்படும்; எனவே கோரிக்கையாளரின் மேலாளர்களிடமிருந்து மறைக்கப்படும்.',
