            'help' => 'ஒரு டிக்கெட் இந்த நிலையில் இருக்கும்போது SLA கடிகாரம் நின்றுவிடும். டிக்கெட்டில் தீவிரமாக வேலை நடக்காத நிலைகளுக்குப் பயன்படுகிறது (எ.கா. <em>நிறுத்தி வைக்கப்பட்டது</em>, <em>பதிலுக்காகக் காத்திருப்பு</em>).',
