        'rota_weekends' => 'பணி அட்டவணையில் வார இறுதிகளைச் சேர்',
        'numbering' => [
            'heading' => 'டிக்கெட் எண்ணிடல்',
            'intro' => 'ஒவ்வொரு டிக்கெட்டுக்கும் ஒரு குறிப்பு எண் உண்டு. அதைத்தான் மக்கள் தொலைபேசியில் சொல்கிறார்கள், படிவத்தில் எழுதுகிறார்கள், ஆறு மாதம் கழித்துத் தேடுகிறார்கள்; எனவே ஒருவர் சொல்லக்கூடிய வடிவில் இருப்பது மதிப்புள்ளது. வடிவத்தை இங்கே தேர்ந்தெடுங்கள்.',
            'style' => 'எண்கள் எவ்வாறு உருவாக்கப்படுகின்றன',
            'style_sequential' => 'ஏறுவரிசையில் எண்ணுதல்',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002 எனத் தொடரும். சொல்ல எளிது, அடையாளம் காண எளிது, எது முதலில் வந்தது என்பதையும் வரிசை சொல்லும்.',
            'style_random' => 'சீரற்றது',
            'style_random_help' => 'CKQ-418-73926 போன்ற மூன்று எழுத்துகளும் எட்டு இலக்கங்களும். FreeITSM எப்போதும் செய்து வந்தது இதுவே. உங்களிடம் எத்தனை டிக்கெட்டுகள் உள்ளன என்பதை யாராலும் ஊகிக்க முடியாது, ஆனால் ஒன்றைச் சத்தமாகப் படிக்கவும் முடியாது.',
            'format' => 'எண் எப்படித் தோன்றும்',
            'format_help' => 'இலக்கங்கள் வர வேண்டிய இடத்தில் <code>{######}</code> ஐ வையுங்கள் &mdash; ஒரு இலக்கத்திற்கு ஒரு #. மற்றவை நீங்கள் தட்டச்சு செய்தபடியே இருக்கும். ஆண்டுக்கு <code>{YYYY}</code> அல்லது <code>{YY}</code>, <code>{MM}</code> மற்றும் <code>{DD}</code>, டிக்கெட் வகை அல்லது நிறுவனத்திலிருந்து எடுக்கப்பட்ட சிறு குறியீட்டுக்கு <code>{TYPE}</code> அல்லது <code>{COMPANY}</code> ஆகியவற்றையும் பயன்படுத்தலாம். எடுத்துக்காட்டாக <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'அடுத்த சில இவ்வாறு இருக்கும்',
            'start' => 'இதிலிருந்து எண்ணத் தொடங்கு',
            'start_help' => 'வேறொரு அமைப்பிலிருந்து மாறி, அது விட்ட இடத்திலிருந்து தொடர விரும்பினால் பயனுள்ளது.',
            'scope' => 'தனித்தனியாக எண்ணுவது',
            'scope_global' => 'எல்லாவற்றுக்கும் ஒரே வரிசை',
            'scope_per_type' => 'ஒவ்வொரு டிக்கெட் வகைக்கும்',
            'scope_per_company' => 'ஒவ்வொரு நிறுவனத்துக்கும்',
            'scope_help' => 'டிக்கெட் வகைக்கு ஏற்ப எண்ணுவது சம்பவங்களுக்கும் கோரிக்கைகளுக்கும் தனித்தனி எண் வரிசைகளைத் தருகிறது; பெரும்பாலான பெரிய சேவை மையங்கள் இவ்வாறே செய்கின்றன. தனித்தனியாக எண்ணினால், எது எதுவென்று வடிவம் சொல்ல வேண்டும் — அதில் {TYPE} அல்லது {COMPANY} ஐச் சேருங்கள், இல்லையெனில் ஒவ்வொரு குழுவும் ஒரே எண்களை உருவாக்கும்.',
            'reset' => 'மீண்டும் தொடங்கு',
            'reset_never' => 'ஒருபோதும் இல்லை — தொடர்ந்து எண்ணு',
            'reset_yearly' => 'ஒவ்வோர் ஆண்டும்',
            'reset_monthly' => 'ஒவ்வொரு மாதமும்',
            'reset_help' => 'ஆண்டு அல்லது மாதம் எண்ணின் ஒரு பகுதியாக இருந்தால் மட்டுமே பயனுள்ளது, இல்லையெனில் நகல்கள் வரும். <code>INC-{YYYY}-{#####}</code> போன்றதுடன் இணைத்துப் பயன்படுத்துங்கள்.',
            'existing_note' => '<strong>ஏற்கனவே எண்ணிடப்பட்ட எதுவும் மாறாது.</strong> தற்போதைய டிக்கெட்டுகள் தங்களிடம் உள்ள குறிப்பு எண்ணையே வைத்திருக்கும்; FreeITSM இதுவரை வழங்கிய ஒவ்வொரு குறிப்பு எண்ணும் தொடர்ந்து வேலை செய்யும் &mdash; பழைய மின்னஞ்சல்களுக்கான பதில்களிலும். தற்போதைய டிக்கெட்டுகளையும் மறுஎண்ணிட விரும்பினால், கீழே அதற்கான கருவி உள்ளது. <strong>இலக்கங்கள் தீர்ந்துபோகாது:</strong> நீங்கள் தேர்ந்தெடுக்கும் அகலம் குறைந்தபட்சம் மட்டுமே, எனவே 1,000,001 ஆம் டிக்கெட் உடையாமல் ஒரு இலக்கம் கூடுதலாகப் பெறும்.',
            'saved' => 'டிக்கெட் எண்ணிடல் சேமிக்கப்பட்டது.',
            'renumber_heading' => 'தற்போதைய டிக்கெட்டுகளை மறுஎண்ணிடு',
            'renumber_intro' => 'தற்போதுள்ள ஒவ்வொரு டிக்கெட்டின் குறிப்பு எண்ணையும் மேலே உள்ள திட்டத்தின்படி, பழையதிலிருந்து தொடங்கி மாற்றி எழுதுகிறது. வேறொரு அமைப்பிலிருந்து மாறிய உடனே எல்லாம் ஒரே மாதிரி இருக்க வேண்டும் என்றால் முக்கியமாகப் பயனுள்ளது.',
            'renumber_safety' => '<strong>பழைய குறிப்பு எண்கள் தொடர்ந்து வேலை செய்யும்.</strong> ஒரு டிக்கெட் இதுவரை கொண்டிருந்த ஒவ்வொரு எண்ணும் நினைவில் வைக்கப்படுகிறது; எனவே பழைய எண்ணை மேற்கோள் காட்டும் மின்னஞ்சலுக்கான பதிலும் சரியான டிக்கெட்டிலேயே சேரும் &mdash; டிக்கெட்டுகள் ஒன்றிணைக்கப்படும்போது நடப்பதைப் போலவே. ஓய்வுபெற்ற எண் வேறொரு டிக்கெட்டுக்கு ஒருபோதும் வழங்கப்படாது. ஆனால் இதைத் திரும்பப் பெற முடியாது, எனவே முதலில் முன்னோட்டத்தைப் பாருங்கள்.',
            'renumber_preview' => 'முன்னோட்டம்',
            'renumber_go' => 'மறுஎண்ணிடு',
            'renumber_preview_first' => 'முதலில் முன்னோட்டம் பாருங்கள் — அது என்ன செய்யும் என்பதைப் பார்த்த பின்பே பொத்தான் செயல்படும்.',
            'renumber_preview_heading' => 'முன்னோட்டம் மட்டுமே &mdash; எதுவும் மாற்றப்படவில்லை.',
            'renumber_done_heading' => 'டிக்கெட்டுகள் மறுஎண்ணிடப்பட்டன.',
            'renumber_summary' => '{total} டிக்கெட்(டுகளில்) {changing} மறுஎண்ணிடப்படும். {skipped} ஏற்கனவே பொருந்துகின்றன.',
            'renumber_next_after' => 'அடுத்த புதிய டிக்கெட் {number} ஆக இருக்கும்.',
            'renumber_confirm_title' => 'ஒவ்வொரு டிக்கெட்டையும் மறுஎண்ணிடவா?',
            'renumber_confirm' => 'இது தற்போதுள்ள ஒவ்வொரு டிக்கெட்டின் குறிப்பு எண்ணையும் மாற்றி எழுதும்.

பழைய குறிப்பு எண்கள் தொடர்ந்து வேலை செய்யும், எனவே பழைய மின்னஞ்சல்களுக்கான பதில்கள் சரியான டிக்கெட்டைக் கண்டறியும். ஆனால் மக்கள் எழுதி வைத்துள்ள, படிவங்களில் இட்ட, தங்கள் சொந்த விரிதாள்களில் சேமித்த எண்கள் இனி FreeITSM இல் காட்டப்படும் எண்களாக இருக்காது.

இதைத் திரும்பப் பெற முடியாது. தொடரவா?',
        ],
        'general' => [
            'system_name' => 'கணினிப் பெயர்',
            'system_name_moved' => 'கணினிப் பெயர் - ஒவ்வொரு பக்கத் தலைப்பின் முதல் பகுதி - ஒவ்வொரு தொகுதிக்கும் பொருந்துவதால், {link} இல் அமைக்கப்படுகிறது.',
            'system_name_moved_link' => 'System -> Branding',
            'system_name_placeholder' => 'எ.கா. சேவை மைய டிக்கெட் அமைப்பு',
            'system_name_help' => 'ஒவ்வொரு பக்கத் தலைப்பின் தொடக்கத்திலும் காட்டப்படும் - உலாவித் தாவலிலும் புக்மார்க்குகளிலும் உள்ள பெயர். வெறுமையாக இருந்தால் "Service Desk" என்று இருக்கும்.',
            'reopen_label' => 'மீண்டும் திறத்தல்',
            'reopen_toggle' => 'கோரிக்கையாளர் பதிலளிக்கும்போது மூடப்பட்ட டிக்கெட்டை மீண்டும் திற',
            'snooze_hour_label' => 'வேலை நாளின் தொடக்கம்',
            'snooze_hour_help' => '"நாளை" அல்லது "அடுத்த வாரம்" வரை தள்ளிவைக்கப்பட்ட டிக்கெட் திரும்ப வரும் நேரம். ஒவ்வொரு பகுப்பாய்வாளரின் சொந்த நேர மண்டலத்தில் கணக்கிடப்படுகிறது; எனவே பல மண்டலங்களில் பரவிய குழுவில் ஒவ்வொருவருக்கும் அவரவர் காலை கிடைக்கும்.',
            'collapse_heading' => 'நீண்ட செய்திகள்',
            'collapse_desc' => 'நீண்ட மின்னஞ்சல்கள், டிக்கெட்டைத் திறந்தபோது நீங்கள் படிக்க வந்ததை மூடிவிடுகின்றன. கீழே உள்ள வரம்பை விட உயரமான செய்திகள் மேலும் காட்டு இணைப்புடன் சுருக்கப்படும். எதுவும் நீக்கப்படாது — முழுச் செய்தி எப்போதும் ஒரு தட்டலில் கிடைக்கும்.',
            'collapse_enabled_label' => 'நீண்ட செய்திகளைச் சுருக்கு',
            'collapse_lines_label' => 'ஏறத்தாழ இதைவிட உயரமான செய்திகளைச் சுருக்கு',
            'collapse_lines_help' => 'வரிகள். வரம்பை சிறிதளவே தாண்டிய செய்தி அப்படியே விடப்படும்; எனவே இரண்டு சொற்களுக்காக இணைப்பு தோன்றாது.',
            'collapse_newest_label' => 'புதிய செய்தியை எப்போதும் முழுமையாகக் காட்டு',
            'collapse_newest_help' => 'நீங்கள் படிக்க வந்த செய்தி ஒருபோதும் சுருக்கப்படாது.',
            'collapse_quoted_label' => 'மேற்கோள் காட்டிய வரலாற்றைச் சுருக்கு',
            'collapse_quoted_help' => 'நீண்ட மேற்கோள் தொடருடன் கூடிய சிறு பதில் எந்த வரி எண்ணிக்கையின்படியும் சுருக்கமானதே, ஆனாலும் படிக்க முடியாதது; எனவே மேற்கோள் காட்டிய வரலாறு தனியாகச் சுருக்கப்படுகிறது.',
            'collapse_remember_label' => 'நான் திறந்ததை நினைவில் வை',
            'collapse_remember_help' => 'நீங்கள் விரிவாக்கும் செய்திகள் இந்தச் சாதனத்தில் விரிவாக்கப்பட்டே இருக்கும்; எனவே ஒரு உரையாடலைப் படிக்கும்போது ஒவ்வொரு புதுப்பிப்பிலும் அது தானாக மாறாது.',
            'group_older_label' => 'பழைய செய்திகளை மடித்து வை',
            'group_older_help' => 'கீழே உள்ள எண்ணிக்கைக்கு அப்பால், பழைய செய்திகள் நீங்கள் திறக்கக்கூடிய ஒற்றை வரியாக மடிக்கப்படும். நீண்ட டிக்கெட் என்பது நீண்ட செய்தியிலிருந்து வேறுபட்ட பிரச்சினை.',
            'group_show_label' => 'சமீபத்திய இத்தனை செய்திகளைத் திறந்து வை',
            'flag_duplicates_label' => 'ஏற்கனவே வந்த செய்திகளைச் சுட்டிக்காட்டு',
            'flag_duplicates_help' => 'மீண்டும் அனுப்பப்பட்டது, நகல் விநியோகம், அல்லது அசலைத் திருப்பிக் கொண்டுவரும் பவுன்ஸ் ஆகியவை, அவை எந்தச் செய்தியுடன் பொருந்துகின்றன என்ற குறிப்புடன் மடிக்கப்படும். எதுவும் நீக்கப்படாது.',
            'ai_heading' => 'AI வாசிப்பு உதவிகள்',
            'ai_desc' => 'விருப்பத்தேர்வு, நீங்கள் இயக்கும் வரை அணைந்திருக்கும்: இந்தப் பக்கத்தில் உள்ள மற்றவற்றைப் போலன்றி, இவை உங்கள் சொந்த AI வழங்குநரைப் பயன்படுத்துகின்றன; ஒவ்வொரு பயன்பாட்டுக்கும் கட்டணம் உண்டு. வழங்குநர், மாதிரி மற்றும் API key ஆகியவை பதில் சுத்தப்படுத்தல் தாவலில் ஒருமுறை அமைக்கப்படுகின்றன. AI எழுதும் எதுவும் டிக்கெட்டை ஒருபோதும் மாற்றாது — உரையாடல் முழுமையாக, இருந்த இடத்திலேயே இருக்கும்.',
            'ai_summary_label' => 'ஒவ்வொரு டிக்கெட்டின் மேலும் ஒரு குறுகிய AI சுருக்கத்தை வை',
            'ai_summary_help' => 'டிக்கெட் எந்த நிலையில் உள்ளது என்பதைச் சொல்லும் சில வரிகள்; கோரிக்கையின் பேரில் எழுதப்பட்டு, புதுப்பித்த நிலையில் வைக்கப்படும். அது எப்போது எழுதப்பட்டது, எவ்வளவு படித்தது, அதற்குப் பிறகு உரையாடல் எவ்வளவு முன்னேறியது என்பதை எப்போதும் காட்டும். ஒவ்வொரு பதிப்பும் வைக்கப்படுவதால், மோசமான சுருக்கம் சிறந்த ஒன்றை அழிக்காது.',
            'ai_auto_label' => 'இத்தனை புதிய செய்திகளுக்குப் பிறகு தானாகப் புதுப்பி',
            'ai_auto_help' => '0 என்றால் ஒருபோதும் இல்லை — அப்போது புதுப்பி பொத்தான் மட்டுமே வழி, யாரும் கேட்காமல் எதற்கும் கட்டணம் விதிக்கப்படாது. ஒரு பகுப்பாய்வாளர் டிக்கெட்டைத் திறக்கும்போது மட்டுமே புதுப்பிப்பு நடக்கும்; எனவே யாரும் படிக்காத பரபரப்பான வரிசைக்குச் செலவில்லை.',
            'ai_max_label' => 'படிக்க வேண்டிய செய்திகள்',
            'ai_max_help' => 'சுருக்கம் எவ்வளவு பின்னோக்கிப் படிக்கிறது. நீண்ட டிக்கெட் அதன் சமீபத்திய முனையிலிருந்து படிக்கப்படும்; தான் பார்க்காத தொடக்கத்தை விவரிக்காமல், சுருக்கம் அதைத் தெரிவிக்கும்.',
            'ai_notes_label' => 'உள் குறிப்புகளைப் படிக்க அனுமதி',
            'ai_notes_help' => 'உள் குறிப்புகளில் உண்மையில் முயற்சிக்கப்பட்டவை பெரும்பாலும் இருக்கும். எப்படியிருந்தாலும் அவை பணியாளர்களுக்கு மட்டுமே — சுருக்கம் கோரிக்கையாளருக்கு ஒருபோதும் காட்டப்படாது — ஆனால் உங்கள் மையத்தின் குறிப்புகளில் வெளியே போகக்கூடாதவை இருந்தால் இதை முடக்குங்கள்.',
            'ai_read_label' => 'டிக்கெட்டில் "இதைப் படி" வழங்கு',
            'ai_confidential_label' => 'ரகசிய டிக்கெட்டுகளும் AI-யும்',
            'ai_confidential_block' => 'அவற்றை AI-க்கு ஒருபோதும் அனுப்பாதே (பரிந்துரைக்கப்படுகிறது)',
            'ai_confidential_allow' => 'மற்ற டிக்கெட்டைப் போலவே நடத்து',
            'ai_confidential_help' => 'டிக்கெட்டைப் படிக்கும் ஒவ்வொரு AI அம்சத்தையும் உள்ளடக்கும்: சுருக்கம், இதைப் படி, பதில் சுத்தப்படுத்தல், AI-ஐ கேளுங்கள், ஒன்றிணைப்புச் சுருக்கங்கள், அறிவுத்தள எழுத்துகள், சேனல் சுருக்கங்கள், சிக்கல் பகுப்பாய்வு மற்றும் war room bot. ரகசிய டிக்கெட் அனுப்பப்படாது, அல்லது - பல டிக்கெட்டுகள் ஒரே நேரத்தில் படிக்கப்படும் இடத்தில் - விடப்படும் அல்லது எண்ணால் மட்டும் காட்டப்படும்.',
            'ai_read_help' => 'முழு டிக்கெட்டையும் படித்து உங்களுக்குச் சுருக்கமாகச் சொல்லும் பொத்தான்: என்ன நடந்தது, எது தீர்க்கப்படவில்லை, அடுத்து என்ன செய்யும். கேட்கும்போது ஒருமுறை படிக்கப்படும், எங்கும் சேமிக்கப்படாது.',
            'reopen_help' => 'கோரிக்கையாளர் திரும்ப வரும் எல்லா இடங்களிலும் பொருந்தும் — சுய-சேவை போர்டல், உங்கள் அறிவிப்பு மின்னஞ்சலுக்கான பதில், WhatsApp அல்லது இணைய அரட்டை. டிக்கெட் உங்கள் முதல் திறந்த நிலைக்குத் திரும்பும். மூடப்பட்டதாகக் குறிக்கப்பட்ட நிலையில் உள்ள டிக்கெட்டுகள் மட்டுமே பாதிக்கப்படும் (அவை எவை என்பதை நிலைகள் என்பதன் கீழ் அமைக்கவும்).',
        ],
        'privacy' => [
            'third_party_label' => 'கோரிக்கையாளரைத் தவிர வேறொருவருக்கு அனுப்பிய செய்திகள்',
            'opt_hide' => 'கோரிக்கையாளரிடமிருந்து மறை',
            'opt_hide_help' => 'செய்தியும் அதன் இணைப்புகளும் கோரிக்கையாளரின் போர்டலில் தோன்றவே தோன்றாது. பரிந்துரைக்கப்படுகிறது: ஒரு டிக்கெட்டை சப்ளையருக்கு முன்னனுப்புவது தனிப்பட்டது என்று பெரும்பாலானோர் கருதுகிறார்கள்.',
            'opt_no_attachments' => 'செய்தியைக் காட்டு, ஆனால் இணைப்புகளை அல்ல',
            'opt_no_attachments_help' => 'நீங்கள் வேறொருவரைத் தொடர்பு கொண்டீர்கள் என்பதையும் என்ன எழுதப்பட்டது என்பதையும் கோரிக்கையாளர் பார்க்கலாம், ஆனால் இணைக்கப்பட்ட கோப்புகளைப் பதிவிறக்க முடியாது.',
            'opt_show' => 'அனைத்தையும் காட்டு',
            'opt_show_help' => 'முன்னனுப்புதல்கள் மற்றும் மூன்றாம் தரப்புப் பதில்கள் உட்பட, உங்கள் பகுப்பாய்வாளர்கள் பார்ப்பதைப் போலவே முழு டிக்கெட்டையும் கோரிக்கையாளர் பார்க்கிறார். இந்த அமைப்பு வருவதற்கு முன் இருந்த நடத்தை இதுவே.',
            'always_visible_note' => '<strong>கோரிக்கையாளருக்கு எப்போதும் தெரிவது:</strong> அவரது சொந்தச் செய்திகள், மற்றும் அவருக்கு அனுப்பப்பட்ட எந்தப் பதிலும். <strong>ஒருபோதும் தெரியாதது:</strong> உள் குறிப்புகள் — இந்த அமைப்பைப் பொருட்படுத்தாமல் அவை போர்டலில் மறைக்கப்படும். WhatsApp மற்றும் இணைய அரட்டைச் செய்திகள் எப்போதும் காட்டப்படும், ஏனெனில் அந்த உரையாடல்கள் வரையறையின்படியே கோரிக்கையாளருக்கும் உங்கள் மையத்துக்கும் இடையிலானவை.',
            'timezone' => 'நேர மண்டலம்',
            'timezone_help' => 'கணினி முழுவதும் தேதிகளையும் நேரங்களையும் காட்டப் பயன்படுகிறது.',
        ],
        'reply_cleanup' => [
            'intro1' => 'பகுப்பாய்வாளர் டிக்கெட் எழுதும் சாளரத்தில் ஒரு தோராயமான பதிலை எழுதும்போது, <strong>✨ Cleanup</strong> பொத்தான் அதை முறையாக வடிவமைக்கப்பட்ட மின்னஞ்சலாக மாற்றி எழுதும் — "Dear [name]," வாழ்த்து சேர்த்து, இலக்கணத்தைத் திருத்தி, கீழே நீங்கள் தேர்ந்தெடுக்கும் தொனியைப் பயன்படுத்தி, "Kind regards," என்று முடிக்கும். இது தொழில்நுட்ப விவரங்களை <strong>கற்பனையாகச் சேர்க்காது</strong>, உள்ளடக்கத்தை நீட்டவும் செய்யாது.',
            'intro2' => 'இந்த அம்சம் தனக்கென்று தனி Anthropic API key-ஐப் பயன்படுத்துகிறது (RFP AI மற்றும் Knowledge AI-இலிருந்து வேறானது), எனவே இதன் பயன்பாடு Anthropic கட்டண டாஷ்போர்டில் தனி வரியாகத் தெரியும்.',
            'tone' => 'தொனி',
            'tone_friendly' => 'நட்பான (இயல்புநிலை)',
            'tone_formal' => 'முறையான',
            'tone_brief' => 'சுருக்கமான',
            'tone_help' => 'இங்கே மாற்றாவிட்டால் ஒவ்வொரு Cleanup-க்கும் பயன்படுத்தப்படும்.',
            'custom_label' => 'தனிப்பயன் வழிமுறைகள் <span style="color: #999; font-weight: normal;">(விருப்பத்தேர்வு)</span>',
            'custom_placeholder' => 'எ.கா. எப்போதும் \'Many thanks,\' என்று முடிக்கவும்&#10;நிறுவனத்தை \'BillCorp\' என்று குறிப்பிடவும்&#10;முழுவதும் பிரிட்டிஷ் ஆங்கில எழுத்துப்பிழைகளைப் பயன்படுத்தவும்',
            'custom_help' => 'வலப்புறம் காட்டப்படும் system prompt-இன் இறுதியில் சேர்க்கப்படும். நிறுவனம் சார்ந்த மாற்றங்களுக்கு (முடிவுரை வேறுபாடுகள், நிறுவனப் பெயர், மொழி விருப்பங்கள்) இதைப் பயன்படுத்தவும். கடுமையான பாதுகாப்பு விதிகளும் வெளியீட்டு வடிவமும் தொடர்ந்து முன்னுரிமை பெறும்.',
            'prompt_summary' => 'system prompt-ஐப் பார்க்கவும் (படிக்க மட்டும்)',
            'prompt_panel_intro' => 'ஒவ்வொரு Cleanup-இலும் Claude-க்கு அனுப்பப்படும் முழு system prompt இதுவே. வாழ்த்துப் பெயர் ஒவ்வொரு டிக்கெட்டுக்கும் மாறும்; தொனி இடப்புறம் நீங்கள் தேர்ந்தெடுத்ததைப் பிரதிபலிக்கும். உங்கள் தனிப்பயன் வழிமுறைகள் (இருந்தால்) இயக்கநேரத்தில் இறுதியில் சேர்க்கப்படும் — அவை இங்கே காட்டப்படுவதில்லை, இடப்புறம் உள்ள உரைப்பெட்டியில் திருத்தவும்.',
        ],
        'csat_tab' => [
            'intro1' => 'ஒரு டிக்கெட் மூடப்படும்போது, கோரிக்கையாளருக்கு அனுபவத்தை 1&ndash;5 எனத் தரப்படுத்தக் கேட்கும் சிறு கருத்துக்கணிப்பு மின்னஞ்சலை அனுப்பவும். பதில்கள் டிக்கெட்டை மூடிய பகுப்பாய்வாளரின் பெயரில் பதிவாகும், எனவே ஒவ்வொரு பகுப்பாய்வாளருக்கான CSAT போக்குகளை எடுக்கலாம்; அவை டாஷ்போர்டில் விட்ஜெட்டாகவும் காட்டப்படும்.',
            'intro2' => 'கருத்துக்கணிப்பு மின்னஞ்சல் <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">மின்னஞ்சல் டெம்ப்ளேட்டுகள்</a> பகுதியில் அமைக்கப்படுகிறது &mdash; <strong>CSAT survey</strong> நிகழ்வுடன் ஒரு டெம்ப்ளேட்டை உருவாக்கி, ஒருமுறை பயன்படுத்தும் மதிப்பீட்டு URL-ஐச் செருக உள்ளடக்கத்தில் <code>[csat_link]</code>-ஐ இடவும்.',
            'mode_off' => 'முடக்கம்',
            'mode_off_help' => 'கருத்துக்கணிப்பு மின்னஞ்சல்கள் அனுப்பப்படாது.',
            'mode_auto' => 'மூடும்போது தானாக',
            'mode_auto_help' => 'டிக்கெட் ஏதேனும் மூடப்பட்ட நிலைக்கு மாறும்போது கருத்துக்கணிப்பு தானாக அனுப்பப்படும்.',
            'mode_manual' => 'கைமுறை மட்டும்',
            'mode_manual_help' => 'பகுப்பாய்வாளர்கள் கேட்க விரும்பும்போது டிக்கெட் கருவிப்பட்டியில் <em>Feedback</em>-ஐக் கிளிக் செய்வார்கள்.',
            'delay_help' => 'மூடிய பிறகு அனுப்புவதற்கு முன் இத்தனை நிமிடங்கள் காத்திருக்கவும். <code>0</code> = உடனடி. மதிப்பீடு கேட்கும் முன், தீர்வு உண்மையிலேயே நிலைத்ததா என்பதை பயனர் உறுதிசெய்ய விரும்பினால் பயனுள்ளது.',
