            'in_channel' => 'அரட்டை வாடிக்கையாளர்களை அவர்களின் அரட்டையிலேயே கேளுங்கள்',
            'in_channel_help' => 'WhatsApp, Telegram, Slack, Teams அல்லது Mattermost வழியாக எழுதிய வாடிக்கையாளரிடம் மின்னஞ்சலுக்குப் பதிலாக அதே அரட்டையில் கேட்கப்படும் &mdash; பொத்தான்கள் உள்ள செயலிகளில் பொத்தான்கள், இல்லாதவற்றில் &ldquo;1 முதல் 5 வரை பதிலளிக்கவும்&rdquo;. WhatsApp-இல் அதன் 24-மணிநேர சாளரம் திறந்திருக்கும்போது மட்டும்; இல்லையெனில், அல்லது அரட்டைச் செய்தி தோல்வியடைந்தால், மின்னஞ்சல் கருத்துக்கணிப்பு பயன்படுத்தப்படும்.',
