            'scale_help' => 'இரு விருப்பங்களும் ஒரே 1&ndash;5 எண்ணைச் சேமிக்கின்றன, எனவே டாஷ்போர்டுகளும் சராசரிகளும் எப்படியும் ஒரே மாதிரி செயல்படும் &mdash; இது கருத்துக்கணிப்புப் பக்கத்தின் தோற்றத்தை மட்டுமே மாற்றும்.',
