            'signin_help' => 'உள்ளூர் பயனர்கள் கடவுச்சொல்லுடன் உள்நுழைவார்கள். இந்தப் பகுப்பாய்வாளருக்கு SSO கட்டாயமாக்க ஒரு வழங்குநரை ஒதுக்கவும் — அவர்களின் அடுத்த SSO உள்நுழைவில் அவர்களின் அடையாளம் தானாக இணைக்கப்படும் (மின்னஞ்சல் மூலம் பொருத்தப்படும்).',
