            'warn_one' => '1 குழுவில் உறுப்பினர்கள் உள்ளனர் ஆனால் துறைகள் இல்லை:',
            'warn_many' => '{count} குழுக்களில் உறுப்பினர்கள் உள்ளனர் ஆனால் துறைகள் இல்லை:',
            'warn_body' => 'ஒரு குழுவில் உள்ளவர் அந்தக் குழுவின் துறைகளுக்கான டிக்கெட் கோப்புறைகளையும் எண்ணிக்கைகளையும் மட்டுமே பெறுவார், எனவே இந்த உறுப்பினர்களின் கோப்புறைகள் துறை இல்லாத டிக்கெட்டுகளையும் அவர்களுடைய சொந்த டிக்கெட்டுகளையும் மட்டுமே எண்ணும். குழுவில் உள்ள கட்டிட ஐகான் மூலம் துறைகளை இணைக்கவும், அல்லது உறுப்பினர்களைக் குழுவிலிருந்து அகற்றவும்.',
            'warn_none' => 'இன்னும் துறைகள் இல்லையா? {link} பகுதியில் உருவாக்கவும்.',
