    'help' => [
        'page_title' => 'சர்வீஸ் டெஸ்க் - டிக்கெட்டுகள் வழிகாட்டி',
        'sidebar_title' => 'வழிகாட்டி',
        'hero_title' => 'டிக்கெட்டுகள் தொகுதி வழிகாட்டி',
        'hero_sub' => 'IT ஆதரவு கோரிக்கைகளை கோப்புறை அடிப்படையிலான ஒரே இன்பாக்ஸில் பதிவு செய்து, கண்காணித்து, தீர்க்கவும் &mdash; சர்வீஸ் டெஸ்க் குழுக்களுக்காக உருவாக்கப்பட்டது.',
