        'overview' => [
            'heading' => 'மேலோட்டம்',
            'intro' => 'டிக்கெட்டுகள் தொகுதி உங்கள் IT சர்வீஸ் டெஸ்க்கின் மையமாகும். ஆதரவு கோரிக்கைகள், சம்பவங்கள் மற்றும் சேவைப் பணிகளை நிர்வகிக்க இது பழக்கமான மின்னஞ்சல் கிளையன்ட் பாணி இடைமுகத்தை வழங்குகிறது. டிக்கெட்டுகள் இறுதிப் பயனர்களிடமிருந்து மின்னஞ்சல் மூலமாகவோ கைமுறையாக உருவாக்கப்பட்டோ வருகின்றன; பகுப்பாய்வாளர்கள் கோப்புறைகள், முன்னுரிமைகள் மற்றும் SLA டைமர்களைப் பயன்படுத்தி அவற்றைக் கையாள்கிறார்கள் &mdash; விரைவான IT ஆதரவை வழங்க தேவையான அனைத்தும் இங்கே உள்ளன.',
            'card_inbox_title' => 'இன்பாக்ஸ்',
            'card_inbox_body' => 'மின்னஞ்சல் கிளையன்ட்டைப் போன்ற கோப்புறை அடிப்படையிலான இன்பாக்ஸ். எனது டிக்கெட்டுகள், ஒதுக்கப்படாதவை, அனைத்து திறந்தவை மற்றும் மூடப்பட்டவை கோப்புறைகளை உலாவலாம். எந்த டிக்கெட்டையும் கிளிக் செய்தால் முழு விவரங்கள், வரலாறு மற்றும் செயல்களுடன் வாசிப்புப் பலகம் திறக்கும்.',
            'card_dashboard_title' => 'டாஷ்போர்டு',
            'card_dashboard_body' => 'தனிப்பயனாக்கக்கூடிய Chart.js விட்ஜெட்டுகளுடன் உங்களுக்கான டாஷ்போர்டை உருவாக்குங்கள். டிக்கெட் எண்ணிக்கைகள், பதில் நேரங்கள், வகைவாரி பிரிவுகள் மற்றும் பகுப்பாய்வாளர் பணிச்சுமையை பார், பை, டோனட் மற்றும் கோட்டு வரைபடங்களில் காட்சிப்படுத்துங்கள்.',
            'card_calendar_title' => 'நாட்காட்டி',
            'card_calendar_body' => 'டிக்கெட்டுகளை அவற்றின் உருவாக்கிய, காலக்கெடு அல்லது தீர்த்த தேதிகளின் அடிப்படையில் நாட்காட்டி கட்டத்தில் பாருங்கள். காலம் கடந்த உருப்படிகளை விரைவாகக் கண்டறிந்து, டிக்கெட்டுகளின் நிலையை ஒரே பார்வையில் கண்டு உங்கள் வாரத்தைத் திட்டமிடுங்கள்.',
            'card_rota_title' => 'பணி அட்டவணை',
            'card_rota_body' => 'பகுப்பாய்வாளர் ஷிஃப்ட்கள் மற்றும் அழைப்புப் பணி அட்டவணைகளைத் திட்டமிடுங்கள். எந்த நேரத்திலும் யார் இருக்கிறார்கள் என்பதைப் பாருங்கள், வார இறுதிகள் மற்றும் விடுமுறைகளுக்கான பணியமர்வைத் திட்டமிடுங்கள், எந்த டிக்கெட்டும் கவனிக்கப்படாமல் போகாமல் உறுதிசெய்யுங்கள்.',
        ],
        'inbox' => [
            'heading' => 'இன்பாக்ஸ்',
            'intro' => 'இன்பாக்ஸ் பகுப்பாய்வாளர்களின் முதன்மைப் பணியிடமாகும். இது மூன்று-பலக அமைப்பைப் பயன்படுத்துகிறது &mdash; இடதுபுறம் கோப்புறைகள், நடுவில் டிக்கெட் பட்டியல், வலதுபுறம் வாசிப்புப் பலகம் &mdash; எனவே பக்கத்தை விட்டு வெளியேறாமலேயே வகைப்படுத்தவும் பதிலளிக்கவும் முடியும்.',
            'p_live' => '<strong>இது தானாகவே புதுப்பித்துக்கொள்கிறது.</strong> ஒவ்வொரு நிமிடமும் இன்பாக்ஸ் உங்கள் அஞ்சல் பெட்டிகளைச் சரிபார்த்து, நீங்கள் பார்க்கக்கூடிய டிக்கெட்டுகளில் புதிதாக ஏதேனும் உள்ளதா என்று பார்க்கிறது &mdash; பின்னணியில் சேகரிக்கப்பட்ட மின்னஞ்சல், WhatsApp, Telegram, Slack, Teams அல்லது Mattermost செய்தி, சக ஊழியரின் பதில் &mdash; ஏதாவது வந்திருந்தால், புதுப்பி பொத்தானைப் போலவே பட்டியலும் கோப்புறை எண்ணிக்கைகளும் தாமாகவே புதுப்பிக்கப்படும். நீங்கள் படித்துக்கொண்டிருக்கும் டிக்கெட்டும் தட்டச்சு செய்துகொண்டிருக்கும் பதிலும் தொடப்படாது.',
            'p_folders' => 'கோப்புறை பலகம் டிக்கெட்டுகளை தருக்கக் குழுக்களாக ஒழுங்கமைக்கிறது. ஒவ்வொரு கோப்புறையும் படிக்காதவற்றின் எண்ணிக்கையைக் காட்டுவதால் புதிய வேலையை உடனே கண்டறியலாம்:',
            'field_my' => '<strong>எனது டிக்கெட்டுகள்</strong> &mdash; உங்களுக்கு ஒதுக்கப்பட்ட டிக்கெட்டுகள். இது உங்கள் தனிப்பட்ட வரிசை; ஒவ்வொரு நாளையும் இங்கிருந்து தொடங்குவது சிறந்தது.',
            'field_unassigned' => '<strong>ஒதுக்கப்படாதவை</strong> &mdash; வந்துவிட்டு இன்னும் பகுப்பாய்வாளர் இல்லாத டிக்கெட்டுகள். பொறுப்பேற்க இங்கிருந்து உருப்படிகளைத் தேர்ந்தெடுங்கள்.',
            'field_all_open' => '<strong>அனைத்து திறந்தவை</strong> &mdash; யாருடையது என்பதைப் பொருட்படுத்தாமல், இன்னும் மூடப்படாத ஒவ்வொரு டிக்கெட்டும். ஒட்டுமொத்த அளவைக் கண்காணிக்கும் மேலாளர்கள் மற்றும் குழுத் தலைவர்களுக்குப் பயனுள்ளது.',
            'field_closed' => '<strong>மூடப்பட்டவை</strong> &mdash; தீர்க்கப்பட்ட டிக்கெட்டுகள். கடந்த காலத் தீர்வைக் குறிப்பிட வேண்டியிருக்கும்போது அல்லது சிக்கலை மீண்டும் திறக்க வேண்டியிருக்கும்போது இங்கே தேடுங்கள்.',
            'field_dept' => '<strong>துறை கோப்புறைகள்</strong> &mdash; துறை வாரியாகக் குழுவாக்கப்பட்ட டிக்கெட்டுகள் (எ.கா. IT, HR, Finance). துறைகள் அமைப்புகளில் உள்ளமைக்கப்பட்டு துணைக் கோப்புறைகளாகத் தானாகவே தோன்றும்.',
            'switch_heading' => '<strong>துறை மற்றும் பகுப்பாய்வாளர் குழுவாக்கத்திற்கு இடையே மாறுதல்</strong>',
            'switch_body' => 'கோப்புறை பலகத்தின் மேலே உள்ள சிறிய இரு-பொத்தான் மாற்றி, ஒரே தரவின் இரு காட்சிகளுக்கு இடையே மாற்றுகிறது. <strong>துறை</strong> குழுவாக்கம் (இயல்புநிலை) ஒவ்வொரு துறையின் கீழும் நிலை துணைக் கோப்புறைகளுடன் டிக்கெட்டுகளைப் பட்டியலிடுகிறது; <strong>பகுப்பாய்வாளர்</strong> குழுவாக்கம் அதைப் புரட்டி, ஒவ்வொரு மேல்நிலைக் கோப்புறையும் ஒரு பகுப்பாய்வாளரின் தனிப்பட்ட வரிசையைக் குறிக்கும்படி நிலை துணைக் கோப்புறைகளுடன் காட்டுகிறது. <strong>ஒதுக்கப்படாதவை</strong> கோப்புறை ஒவ்வொரு காட்சியிலும் சூழலுக்கேற்ப செயல்படும் &mdash; துறைக் காட்சியில் துறை அமைக்கப்படாத டிக்கெட்டுகளையும், பகுப்பாய்வாளர் காட்சியில் ஒதுக்கப்பட்டவர் இல்லாத டிக்கெட்டுகளையும் பட்டியலிடும் &mdash; எனவே எடுத்துக்கொள்ள வேண்டியவை எவை என்பதை எப்போதும் காணலாம். உங்கள் தேர்வு ஒவ்வொரு பகுப்பாய்வாளருக்கும் தனியாகச் சேமிக்கப்படுவதால், ஒவ்வொரு குழு உறுப்பினரும் தமக்குப் பிடித்த காட்சியை அமர்வுகள் முழுவதும் வைத்திருக்கலாம்.',
            'p_actions' => 'டிக்கெட் பட்டியலுக்கு மேலே நான்கு செயல் பொத்தான்கள் உள்ளன: டிக்கெட்டை உருவாக்க <strong>புதியது</strong>, முக்கியச்சொல், குறிப்பு எண் அல்லது கோரிக்கையாளர் மூலம் டிக்கெட்டுகளைக் கண்டறிய <strong>தேடு</strong>, நீங்கள் காண்பதைக் குறுக்க <strong>வடிகட்டு</strong>, தற்போதைய கோப்புறையை மீண்டும் ஏற்ற <strong>புதுப்பி</strong>.',
            'filter_body' => '<strong>வடிகட்டு</strong> பொத்தான் (புனல்) கோப்புறைகளையும் பட்டியலையும் சேர்த்துக் குறுக்குகிறது, அவை எவ்வாறு குழுவாக்கப்பட்டிருந்தாலும். <strong>என்னுடையவை</strong> உங்களுக்கு ஒதுக்கப்பட்ட டிக்கெட்டுகளை மட்டும் காட்டும்; <strong>மூடியவற்றை மறை</strong> நிலை மூடப்பட்டதாகக் குறிக்கப்பட்ட ஒவ்வொரு டிக்கெட்டையும் விலக்கும். வடிகட்டி இயக்கத்தில் இருக்கும்போது புனலில் ஒரு புள்ளியும் பட்டியல் தலைப்பின் அருகில் ஒரு லேபிளும் தோன்றும்; எனவே நீங்கள் அனைத்தையும் பார்க்கவில்லை என்பது உங்களுக்கு எப்போதும் தெரியும். கோப்புறைகள் <strong>பகுப்பாய்வாளர்</strong> வாரியாகக் குழுவாக்கப்படும்போது, உங்கள் சொந்தக் கோப்புறை <strong>எனது டிக்கெட்டுகள்</strong> என்ற பெயரில் மேலே இருக்கும். தேடலுக்கு அதன் சொந்த <strong>மூடிய டிக்கெட்டுகளையும் சேர்</strong> சுவிட்ச் உள்ளது, இது இயல்பாக இயக்கத்தில் இருக்கும்; ஏனெனில் தேடல் பெரும்பாலும் பழைய டிக்கெட்டைத் தேடுவதே. இரு தேர்வுகளும் உங்களுக்கு மட்டுமே சேமிக்கப்படும்.',
            'row_name' => 'ஒவ்வொரு வரிசையும் டிக்கெட் குறிப்பு எண்ணையும் அதன் பின் ஒரு பெயரையும் காட்டுகிறது. இயல்பாக அது <strong>டிக்கெட்டை எழுப்பியவர்</strong>, டிக்கெட்டின் வாழ்நாள் முழுவதும் அது மாறாது. சமீபத்திய செய்தியை அனுப்பியவரைப் பார்க்க விரும்பினால் &mdash; நீங்கள் பதிலளித்த பிறகு அது உங்கள் சொந்த அஞ்சல் பெட்டியாக மாறும் &mdash; <strong>டிக்கெட் எண்ணின் அருகிலுள்ள பெயர்</strong> என்பதை <strong>அமைப்புகள் &rarr; வரிசைக் காட்சி</strong> என்பதன் கீழ் மாற்றுங்கள்; அங்கேயே பெயரை மறைத்து குறிப்பு எண்ணை மட்டும் வைக்கவும் முடியும். அந்த தத்தல் உங்கள் சொந்த அமைப்பு: இது வேறு யாருக்கும் எதையும் மாற்றாது.',
            'tip' => 'பட்டியலில் எந்த டிக்கெட்டையும் கிளிக் செய்தால் அது வாசிப்புப் பலகத்தில் ஏற்றப்படும். அங்கிருந்து புலங்களைப் புதுப்பிக்கலாம், கருத்துகளைச் சேர்க்கலாம், மின்னஞ்சலில் பதிலளிக்கலாம் அல்லது கோப்புகளை இணைக்கலாம் &mdash; இன்பாக்ஸை விட்டு வெளியேறாமலேயே.',
        ],
        'faster' => [
            'heading' => 'விரைவாகப் பணியாற்றுதல்',
            'intro' => 'பரபரப்பான காலையை எளிதாக்கும் நான்கு விஷயங்கள்: சேமித்த பதில்கள், பல டிக்கெட்டுகளில் ஒரே நேரத்தில் செயல்படுதல், உரையாடல்களை அவை சேர வேண்டிய இடத்தில் வைத்தல்.',
            'templates_heading' => 'தயார் பதில்கள்',
            'templates_body' => 'ஒரே சில பதில்களை நீங்கள் மீண்டும் மீண்டும் அனுப்புகிறீர்கள். ஒன்றை ஒருமுறை எழுதி, பின்னர் பதில் சாளரத்தின் கீழ் இடதுபுறத்தில் உள்ள <strong>டெம்ப்ளேட்கள்</strong> என்பதைக் கிளிக் செய்து உங்கள் கர்சர் இருக்கும் இடத்தில் சேருங்கள் &mdash; நீங்கள் ஏற்கனவே தட்டச்சு செய்ததை மாற்றாமல் அதனுடன் சேர்க்கப்படும். டெம்ப்ளேட்கள் rich text ஆகும்; தானியங்கி மின்னஞ்சல்களில் உள்ள அதே <code>[merge_code]</code> இடக்குறிகளை ஆதரிக்கும், எனவே <code>[requester_first_name]</code> சேர்க்கும்போதே உண்மையான பெயராக மாறும்.',
            'templates_team' => '<strong>குழு டெம்ப்ளேட்கள்</strong> &mdash; அனைவருடனும் பகிரப்படும், அமைப்புகள் &rarr; பதில் டெம்ப்ளேட்கள் என்பதில் அமைக்கப்படும்.',
            'templates_mine' => '<strong>உங்களுடையவை</strong> &mdash; <em>வரைவை டெம்ப்ளேட்டாகச் சேமி</em> மூலம் வரைவைச் சேமிக்கலாம். உங்களுக்கு மட்டுமே, அனுமதி தேவையில்லை.',
            'templates_tip' => 'டெம்ப்ளேட்டுக்கு அதன் வாசகத்தால் அல்ல, அது பயன்படும் சூழ்நிலையால் பெயரிடுங்கள் ("பிரிண்டர் ஆஃப்லைன் &mdash; முதல் படிகள்"). காலை 9 மணிக்கு நீங்கள் தேடப்போவது அதைத்தான்.',
            'select_heading' => 'பல டிக்கெட்டுகளைத் தேர்ந்தெடுத்தல்',
            'select_body' => 'டிக்கெட் பட்டியல் Outlook அல்லது File Explorer போலவே செயல்படுகிறது. தேர்வுப்பெட்டிகள் இல்லை.',
            'key_click' => 'கிளிக்',
            'key_click_d' => 'ஒன்றைத் தேர்ந்தெடுத்துத் திற',
            'key_ctrl' => 'Ctrl+கிளிக்',
            'key_ctrl_d' => 'மற்றவற்றைத் தொடாமல் ஒன்றைச் சேர் அல்லது நீக்கு',
            'key_shift' => 'Shift+கிளிக்',
            'key_shift_d' => 'கடைசியாகக் கிளிக் செய்த இடத்திலிருந்து முழுத் தொகுதியையும் தேர்ந்தெடு',
            'key_kb' => 'விசைப்பலகை',
            'key_kb_d' => 'நகர அம்புக்குறிகள், நீட்டிக்க Shift+அம்புக்குறிகள், சிதறிய டிக்கெட்டுகளைத் தேர்ந்தெடுக்க Ctrl+அம்புக்குறிகள் மற்றும் Space, அனைத்திற்கும் Ctrl+A, அழிக்க Escape',
            'select_actions' => 'பலவற்றைத் தேர்ந்தெடுத்த நிலையில், அவை அனைத்திற்கும் ஒரே நேரத்தில் நிலை, முன்னுரிமை, துறை, வகை அல்லது ஒதுக்கப்பட்டவரை அமைக்க <strong>அவற்றில் ஏதேனும் ஒன்றில் வலது-கிளிக் செய்யவும்</strong> &mdash; அல்லது முழுத் தொகுப்பையும் ஒரு கோப்புறைக்கு இழுக்கவும். பல டிக்கெட்டுகள் தேர்ந்தெடுக்கப்பட்டிருக்கும்போது திரை எதைக் காட்ட வேண்டும் என்பது உங்கள் தேர்வு; கணக்கு மெனுவில் விருப்பத்தேர்வுகளில் அமைக்கலாம்.',
            'select_tip' => 'உங்கள் தேர்வில் <em>இல்லாத</em> டிக்கெட்டில் வலது-கிளிக் செய்தால் தேர்வு அழிந்து, அந்த ஒன்று மட்டுமே இலக்காகும். இது வேண்டுமென்றே செய்யப்பட்டது &mdash; நீங்கள் விட்டுவிட்டதாக நினைத்த தொகுப்பில் ஒருபோதும் செயல்பட நேராது.',
            'merge_heading' => 'நகல்களை இணைத்தல்',
            'merge_body' => 'இரண்டு பேர் ஒரே செயலிழப்பைப் புகாரளித்தார்களா? டிக்கெட்டுகளைத் தேர்ந்தெடுத்து, வலது-கிளிக் செய்து, <strong>இணை</strong> என்பதைத் தேர்ந்தெடுங்கள். உரையாடல்கள் ஒன்றாகச் சேரும்; AI வழங்குநர் உள்ளமைக்கப்பட்டிருந்தால், ஒவ்வொருவரும் என்ன கேட்டார்கள், ஏற்கனவே என்ன செய்யப்பட்டது என்பதன் சுருக்கமான விளக்கத்தை FreeITSM எழுதும்; இதனால் அதை எடுப்பவர் நான்கு இழைகளைப் படிக்க வேண்டியதில்லை.',
            'merge_tip' => 'எதுவும் ஒருபோதும் நீக்கப்படாது. இணைக்கப்பட்ட டிக்கெட் தனது குறிப்பு எண்ணை வைத்திருக்கும், தேடக்கூடியதாகவே இருக்கும், எங்கே சென்றது என்பதைக் காட்டும் &mdash; அதைப் பற்றிய பழைய மின்னஞ்சலுக்கு வாடிக்கையாளர் பதிலளித்தாலும் அது உங்களை வந்தடையும்.',
            'split_heading' => 'டிக்கெட்டைப் பிரித்தல்',
            'split_body' => 'இதற்கு நேர்மாறான வேலை. உரையாடலின் நடுவில் யாராவது தொடர்பில்லாத இரண்டாவது விஷயத்தை எழுப்பினால், அந்தச் செய்தியில் <strong>பிரி</strong> என்பதைக் கிளிக் செய்யுங்கள் (அல்லது செய்தித் தலைப்பில் வலது-கிளிக் செய்யுங்கள்). அது புதிய டிக்கெட்டுக்குச் செல்லும்; விருப்பப்பட்டால் அதற்குப் பின் வந்த ஒவ்வொரு செய்தியையும் உடன் எடுத்துச் செல்லும்; அசல் டிக்கெட் அவை எங்கே சென்றன என்பதைக் காட்டும் குறியை வைத்திருக்கும்.',
            'split_tip' => 'புதிய டிக்கெட்டுக்கு சரியான பொருள் கொடுங்கள். இயல்பாக அது நகர்த்தப்பட்ட செய்தியின்&rsquo; பொருளாக இருக்கும்; அது பெரும்பாலும் <em>பழைய</em> சிக்கலின் "RE:" ஆக இருக்கும்.',
            'undo_heading' => 'மனம் மாறினால்',
            'undo_body' => 'இரண்டையும் டிக்கெட்டில் உள்ள பேனரிலிருந்து செயல்தவிர்க்கலாம். புதிய டிக்கெட்டில் யாராவது பதிலளித்திருந்தாலோ, குறிப்பைச் சேர்த்திருந்தாலோ, நேரத்தைப் பதிவு செய்திருந்தாலோ <strong>பிரித்தலை</strong> செயல்தவிர்ப்பது மறுக்கப்படும் &mdash; எது தடையாக உள்ளது என்பது சரியாகச் சொல்லப்படும். <strong>இணைப்பைச்</strong> செயல்தவிர்ப்பது டிக்கெட்டுக்கு அதன் செய்திகள், குறிப்புகள் மற்றும் பதிவு செய்த நேரத்தைத் திருப்பித் தந்து, அது இருந்தபடியே மீண்டும் திறக்கும்; ஆனால் இணைத்த பிறகு மற்ற டிக்கெட்டில் எழுதப்பட்ட பதில்கள் அங்கேயே இருக்கும்.',
        ],
        'working' => [
            'heading' => 'டிக்கெட்டுகளுடன் பணியாற்றுதல்',
            'intro' => 'ஒவ்வொரு ஆதரவு கோரிக்கையும் ஒரு வாழ்க்கைச் சுழற்சியைப் பின்பற்றுகிறது: உருவாக்கப்படுகிறது, வகைப்படுத்தப்படுகிறது, கையாளப்படுகிறது, இறுதியில் தீர்க்கப்படுகிறது. ஆரம்பப் பதிவிலிருந்து மூடல் வரை ஒவ்வொரு கட்டத்தையும் திறம்பட நிர்வகிக்க டிக்கெட்டுகள் தொகுதி கருவிகளை வழங்குகிறது.',
            'creating_heading' => '<strong>புதிய டிக்கெட்டை உருவாக்குதல்</strong>',
            'step1' => '<strong>புதியது என்பதைக் கிளிக் செய்யவும்</strong> &mdash; இன்பாக்ஸ் கருவிப்பட்டியிலிருந்து புதிய டிக்கெட் சாளரத்தைத் திறக்கவும். புதுப்பிப்புகளைப் பெறும்படி கோரிக்கையாளரின் பெயரையும் மின்னஞ்சல் முகவரியையும் உள்ளிடவும்.',
            'step2' => '<strong>பொருளை அமைக்கவும்</strong> &mdash; சிக்கலின் தெளிவான, சுருக்கமான சுருக்கத்தை எழுதவும். இது டிக்கெட் பட்டியலிலும் இறுதிப் பயனருக்கு அனுப்பப்படும் மின்னஞ்சல் அறிவிப்புகளிலும் தோன்றும்.',
            'step3' => '<strong>துறை, வகை மற்றும் முன்னுரிமையைத் தேர்ந்தெடுக்கவும்</strong> &mdash; பொருத்தமான துறை, டிக்கெட் வகை (எ.கா. Incident, Service Request) மற்றும் முன்னுரிமை நிலையைத் தேர்ந்தெடுக்கவும். இந்தப் புலங்கள் SLA டைமர்களையும் வழித்தட விதிகளையும் இயக்குகின்றன.',
            'step4' => '<strong>விளக்கத்தைச் சேர்க்கவும்</strong> &mdash; rich text எடிட்டரைப் பயன்படுத்தி சிக்கலின் முழு விவரங்களை வழங்கவும். மீண்டும் நிகழ்த்தும் படிகள், பிழைச் செய்திகள் மற்றும் தீர்க்கும் பகுப்பாய்வாளருக்குத் தேவையான சூழலைச் சேர்க்கவும்.',
            'step5' => '<strong>சேமி</strong> &mdash; டிக்கெட் தனித்துவமான குறிப்பு எண்ணுடன் உருவாக்கப்பட்டு பொருத்தமான கோப்புறையில் தோன்றும். முன்னுரிமையின் அடிப்படையில் SLA கடிகாரம் உடனே தொடங்கும்.',
            'editing_heading' => '<strong>டிக்கெட்டுகளைத் திருத்துதலும் நிர்வகித்தலும்</strong>',
            'editing_body' => 'டிக்கெட் உருவான பிறகு, வாசிப்புப் பலகத்திலிருந்து எந்தப் புலத்தையும் புதுப்பிக்கலாம். முக்கியப் புலங்கள்:',
            'card_status_title' => 'நிலை',
            'card_status_body' => 'டிக்கெட் வாழ்க்கைச் சுழற்சியைக் கண்காணிக்கவும்: புதியது, திறந்தது, செயலில், நிலுவையில், தீர்க்கப்பட்டது, மூடப்பட்டது',
            'card_priority_title' => 'முன்னுரிமை',
            'card_priority_body' => 'அவசரத்தையும் தாக்கத்தையும் அமைக்கவும்: முக்கியமானது, அதிகம், நடுத்தரம், குறைவு. ஒவ்வொரு நிலைக்கும் அதன் சொந்த SLA இலக்கு உண்டு',
            'card_category_title' => 'வகை',
            'card_category_body' => 'சிக்கலின் வகையைப் பிரிக்கவும்: வன்பொருள், மென்பொருள், நெட்வொர்க், அணுகல், பொது. அறிக்கையிடலுக்குப் பயனுள்ளது',
            'card_analyst_title' => 'ஒதுக்கப்பட்ட பகுப்பாய்வாளர்',
            'card_analyst_body' => 'டிக்கெட்டைத் தீர்க்கும் பொறுப்புள்ள நபர். மறுஒதுக்கீடு செயல்பாட்டுப் பதிவில் பதிவு செய்யப்படும்',
            'card_enduser_title' => 'இறுதிப் பயனர்',
            'card_enduser_body' => 'கோரிக்கையை எழுப்பியவர். ஏற்கனவே உள்ள பயனர் பதிவுடன் இணைக்க பெயர் அல்லது மின்னஞ்சல் மூலம் தேடவும்',
            'card_dept_title' => 'துறை',
            'card_dept_body' => 'டிக்கெட்டுகளை சரியான குழுவுக்கு வழிநடத்தவும். துறைகள் கோப்புறைக் குழுவாக்கத்தையும் டாஷ்போர்டு வடிகட்டிகளையும் இயக்குகின்றன',
            'flow_new' => 'புதியது',
            'flow_in_progress' => 'செயலில்',
            'flow_resolved' => 'தீர்க்கப்பட்டது',
            'flow_closed' => 'மூடப்பட்டது',
            'triage_heading' => '<strong>இழுத்துவிட்டு வகைப்படுத்துதல்</strong>',
            'triage_body' => 'டிக்கெட்டை வகைப்படுத்த அதைத் திறக்க வேண்டியதில்லை. டிக்கெட் பட்டியலில் எந்த வரிசையையும் ஒரு கோப்புறைக்கு இழுத்து, ஒரே நகர்வில் புலங்களைப் புதுப்பிக்கலாம்:',
            'triage_dept' => '<strong>துறைக் காட்சி</strong> &mdash; மறுஒதுக்கீடு செய்ய துறைக் கோப்புறையில் விடவும்; இரண்டையும் ஒரே நேரத்தில் புதுப்பிக்க துறையின் கீழுள்ள நிலை துணைக் கோப்புறையில் விடவும்; துறையை அழிக்க <strong>ஒதுக்கப்படாதவை</strong> மீது விடவும்.',
            'triage_analyst' => '<strong>பகுப்பாய்வாளர் காட்சி</strong> &mdash; அந்த பகுப்பாய்வாளரை உரிமையாளராக ஒதுக்க அவரது கோப்புறையில் விடவும் (வாசிப்புப் பலகத்தில் உள்ள உரிமையாளர் புலம் ஒத்திசைவில் இருக்க <code>assigned_analyst_id</code> மற்றும் <code>owner_id</code> இரண்டையும் அமைக்கும்); இரண்டையும் புதுப்பிக்க நிலை துணைக் கோப்புறையில் விடவும்; ஒதுக்கப்பட்டவரை அழிக்க <strong>ஒதுக்கப்படாதவை</strong> மீது விடவும்.',
            'triage_spring' => '<strong>தானாக விரியும் கோப்புறைகள்</strong> &mdash; இழுக்கும்போது சுருங்கிய கோப்புறை மீது நிற்கவும், அது தானாக விரியும் (Outlook பாணி); இதனால் முதலில் விடாமலேயே உள்ளமைந்த எந்த நிலையையும் அடையலாம்.',
            'fullscreen_heading' => '<strong>முழுத்திரைக் காட்சி</strong>',
            'fullscreen_body' => 'நீண்ட உரையாடல், சிக்கலான மாற்றம் அல்லது விரிவான பதிலை வரைவது &mdash; போன்ற &mdash; ஒரே டிக்கெட்டில் கவனம் செலுத்த வேண்டியிருக்கும்போது, முழுத்திரைக் காட்சிக்கு மாறவும். கோப்புறைப் பட்டியலும் டிக்கெட் பட்டியலும் மறைந்து, உரையாடல் கிடைக்கும் முழு அகலத்தையும் நிரப்பும்; பண்புகள் (துறை, வகை, நிலை, மூலம், First Time Fix, IT Training, உரிமையாளர்) வலதுபுற செங்குத்துப் பக்கப்பட்டிக்கு நகரும்.',
            'fullscreen_max' => '<strong>பெரிதாக்கு ஐகான்</strong> &mdash; டிக்கெட் பொருள் வரியின் வலது முனையில் உள்ள சிறிய ஐகான். முழுத்திரைக்குள் செல்ல கிளிக் செய்யவும்; 3-பலக அமைப்புக்குத் திரும்ப மீண்டும் கிளிக் செய்யவும்.',
            'fullscreen_dbl' => '<strong>வரிசையை இருமுறை கிளிக் செய்யவும்</strong> &mdash; பட்டியலில் எந்த டிக்கெட்டையும் இருமுறை கிளிக் செய்தால் அது நேரடியாக முழுத்திரையில் திறக்கும்; இது Outlook பாணியில் "இதை உண்மையிலேயே திற" என்ற சைகை.',
            'fullscreen_sticks' => '<strong>தேர்வுகள் முழுவதும் நிலைத்திருக்கும்</strong> &mdash; முழுத்திரையில் இருக்கும்போது அடுத்த டிக்கெட்டுக்கு மாறினாலும் அங்கேயே இருப்பீர்கள். டிக்கெட் தேர்ந்தெடுக்காமல் பக்கத்தை மீண்டும் ஏற்றினால் (F5) இயல்புநிலை 3-நெடுவரிசை அமைப்புக்குத் திரும்பும்; எனவே கோப்புறைப் பட்டியல் மறைந்த நிலையில் சிக்கிக்கொள்ள முடியாது.',
            'rightclick_heading' => '<strong>விரைவு செயல்களுக்கு வலது-கிளிக்</strong>',
            'rightclick_body' => 'சூழல் மெனுவைத் திறக்க பட்டியலில் எந்த டிக்கெட்டிலும் வலது-கிளிக் செய்யவும். எதில் செயல்படுகிறீர்கள் என்று தெரிய மெனுவின் மேலே டிக்கெட் குறிப்பு எண் காட்டப்படும்; ஒவ்வொரு செயலும் வாசிப்புப் பலகத்தில் தற்போது திறந்திருப்பதை <em>மாற்றாமல்</em> வலது-கிளிக் செய்த டிக்கெட்டில் செயல்படும் &mdash; டிக்கெட் A-ஐப் படித்துக்கொண்டிருக்கும்போது இடத்தை இழக்காமல் டிக்கெட் B-ஐ வகைப்படுத்த வேண்டியிருந்தால் பயனுள்ளது.',
            'rightclick_status' => '<strong>நிலையை அமை &rarr;</strong> &mdash; ஒவ்வொரு செயலில் உள்ள நிலையையும் அதன் நிற மாதிரியுடன் பட்டியலிடும் துணை மெனு. நீங்கள் திறந்து வைத்துள்ள டிக்கெட்டில் வலது-கிளிக் செய்தால், தற்போதைய மதிப்புக்கு அருகில் டிக் குறி தோன்றும். தேர்வுகள் உடனே டிக்கெட்டைப் புதுப்பிக்கும், தணிக்கைப் பதிவில் உள்ளீடு எழுதும், கோப்புறை எண்ணிக்கைகளைப் புதுப்பிக்கும், பொருந்தினால் வாசிப்புப் பலகத்தின் நிலை கீழ்விரியையும் ஒத்திசைக்கும்.',
            'rightclick_priority' => '<strong>முன்னுரிமையை அமை &rarr;</strong> &mdash; அதே துணை மெனு முறை; செயலில் உள்ள முன்னுரிமைகள் பட்டியலிலிருந்து எடுக்கப்பட்டு ஒவ்வொன்றின் நிறமும் மாதிரியாகக் காட்டப்படும். முதல் வரிசை ஒதுக்கீட்டை அழிக்கும் <em>(முன்னுரிமை இல்லை)</em> விருப்பம் (முன்னுரிமை காலியாக இருக்கலாம்).',
            'rightclick_assign' => '<strong>ஒதுக்கு &rarr;</strong> &mdash; ஏற்றப்பட்ட ஒவ்வொரு பகுப்பாய்வாளரையும் சாம்பல் நிற முதலெழுத்துச் சிப்புடன் பட்டியலிடும் துணை மெனு; அழிப்பதற்காக மேலே <em>(ஒதுக்கப்படாதது)</em> வரிசையும் உண்டு. வாசிப்புப் பலகத்தின் உரிமையாளர் புலம் ஒத்திசைவில் இருக்க தேர்வுகள் <code>assigned_analyst_id</code> மற்றும் <code>owner_id</code> இரண்டையும் அமைக்கும்.',
            'rightclick_cmdb' => '<strong>CMDB பொருளை இணை&hellip;</strong> &mdash; தட்டச்சு செய்யும்போதே தேடும் தேர்வியைத் திறக்கும். இணைக்க ஒரு முடிவைக் கிளிக் செய்து, தொடர்ந்து தேர்ந்தெடுக்கலாம் &mdash; உள்ளீடு அழிந்து அடுத்ததற்காக மீண்டும் கவனம் பெறும்; சாளரத்தினுள் "சமீபத்தில் இணைக்கப்பட்டவை" பதிவு பச்சை டிக் உறுதிப்படுத்தல்களின் தொடர் பட்டியலைக் காட்டும்.',
            'rightclick_time' => '<strong>நேரத்தைப் பதிவு செய்&hellip;</strong> &mdash; நிமிடங்கள் + தேதிநேரத் தேர்வி ("இப்போது" என்பது இயல்பு, எனவே பின்தேதியிடவும் முடியும்) + விருப்பக் குறிப்புப் பெட்டியுடன் சாளரத்தைத் திறக்கும்.',
            'rightclick_phone' => '<strong>தொலைபேசியில்</strong>, டிக்கெட்டை அரை வினாடி அழுத்திப் பிடித்தால் அதே மெனு முழுத்திரைப் பலகமாகத் திறக்கும். மேலும் விருப்பங்கள் கொண்ட தேர்வு &mdash; நிலையை அமை, முன்னுரிமையை அமை, ஒதுக்கு &mdash; அவற்றுக்குப் பக்கவாட்டில் நகரும்; திரும்ப <strong>பின்</strong> உள்ளது.',
            'rightclick_tip' => 'சூழல் மெனு வழியாக நீங்கள் செயல்படும் டிக்கெட்டே வாசிப்புப் பலகத்தில் திறந்திருப்பதாக இருந்தால், சாளரம் மூடும்போது அங்குள்ள தொடர்புடைய பகுதி (நிலை / முன்னுரிமை கீழ்விரிகள், CMDB பொருள்கள், நேர உள்ளீடுகள்) தானாகப் புதுப்பிக்கப்படும்; இதனால் இடைமுகம் ஒத்திசைவில் இருக்கும்.',
            'time_heading' => '<strong>நேரத்தைப் பதிவு செய்தல்</strong>',
            'time_body' => 'டிக்கெட்டில் செலவிட்ட நேரம், வாசிப்புப் பலகத்தில் இணைக்கப்பட்ட CMDB பொருள்கள் பலகத்திற்கும் குறிப்புகள் பலகத்திற்கும் இடையே உள்ள தனிப்பட்ட <strong>நேர உள்ளீடுகள்</strong> பிரிவில் பதிவு செய்யப்படுகிறது. தலைப்பு மொத்தத்தைக் காட்டும் (எ.கா. "மொத்தம் 2h 30m"); கீழுள்ள ஒவ்வொரு உள்ளீடும் செலவிட்ட நேரம், பகுப்பாய்வாளர், தேதி மற்றும் நீங்கள் சேர்த்த குறிப்புகளைக் காட்டும்.',
            'time_step1' => '<strong>இன்லைன் படிவம்</strong> &mdash; எண் உள்ளீட்டில் செலவிட்ட நிமிடங்களையும், குறிப்பு உள்ளீட்டில் விருப்பமான சிறு விளக்கத்தையும் தட்டச்சு செய்து, <strong>சேர்</strong> என்பதைக் கிளிக் செய்யவும். புதிய உள்ளீடு உங்கள் பெயர் மற்றும் தற்போதைய நேரமுத்திரையுடன் பட்டியலின் மேலே உடனே தோன்றும்.',
            'time_step2' => '<strong>வலது-கிளிக் மூலம் பின்தேதியிடல்</strong> &mdash; முன்பே பதிவு செய்ய மறந்த நேரத்தைப் பதிவு செய்ய வேண்டுமானால், பட்டியலில் டிக்கெட்டை வலது-கிளிக் செய்து <strong>நேரத்தைப் பதிவு செய்&hellip;</strong> என்பதைத் தேர்ந்தெடுக்கவும். வேலை செய்யப்பட்ட உண்மையான நேரத்தை உள்ளீட்டில் குறிக்க சாளரத்தில் தேதிநேரத் தேர்வி உள்ளது.',
            'time_step3' => '<strong>உங்கள் சொந்த உள்ளீடுகளை நீக்கு</strong> &mdash; நீங்கள் பதிவு செய்த உள்ளீடுகளுக்கு அருகில் சிறிய &times; பொத்தான் தோன்றும். அதைக் கிளிக் செய்து (உறுதிப்படுத்தி) மென்-நீக்கம் செய்யலாம் &mdash; வரிசை தணிக்கைக்காக <code>is_active = 0</code> உடன் தரவுத்தளத்தில் இருக்கும், ஆனால் பட்டியலிலிருந்து மறையும். பிற பகுப்பாய்வாளர்களின் உள்ளீடுகளை நீக்க முடியாது.',
            'time_tip1' => 'நேரங்கள் வெறும் நிமிடங்களாகச் (45 நிமி, 90 நிமி போன்றவை) சேமிக்கப்பட்டு, இடைமுகத்தில் <code>45m</code> அல்லது <code>1h 30m</code> என்று காட்டப்படும் &mdash; சிறிய திருத்தங்களுக்குப் போதுமான நுணுக்கம், தசம-மணி வட்டமிடும் தொந்தரவு இல்லை.',
            'time_tip2' => 'ஒவ்வொரு புல மாற்றமும் டிக்கெட்டின் செயல்பாட்டுப் பதிவில் பதிவு செய்யப்படுகிறது. யார் எதை எப்போது மாற்றினார் என்பதை எப்போதும் பார்க்கலாம்; தணிக்கை இணக்கத்திற்கும் பகுப்பாய்வாளர்களுக்கு இடையிலான ஒப்படைப்புக்கும் இது அவசியம்.',
        ],
        'comments' => [
            'heading' => 'கருத்துகள் &amp; இணைப்புகள்',
            'intro' => 'செயல்பாட்டுப் பதிவே ஒவ்வொரு டிக்கெட்டின் இதயம். எடுக்கப்பட்ட ஒவ்வொரு செயலையும் &mdash; கருத்துகள், புல மாற்றங்கள், அனுப்பிய மின்னஞ்சல்கள், இணைத்த கோப்புகள் &mdash; காலவரிசைப்படி ஒரு காலவரிசையில் பதிவு செய்து, ஒரு ஆதரவு கோரிக்கையின் முழுக் கதையையும் சொல்கிறது.',
            'adding_heading' => '<strong>கருத்துகளைச் சேர்த்தல்</strong>',
            'step1' => '<strong>டிக்கெட்டைத் திறக்கவும்</strong> &mdash; இன்பாக்ஸில் உள்ள எந்த டிக்கெட்டையும் கிளிக் செய்து அதன் வாசிப்புப் பலகத்தை ஏற்றவும். முழு செயல்பாட்டுப் பதிவையும் கீழே உள்ள கருத்துப் பெட்டியையும் காண கீழே உருட்டவும்.',
            'step2' => '<strong>உங்கள் குறிப்பை எழுதவும்</strong> &mdash; கருத்து எடிட்டரைத் திறக்க குறிப்பைச் சேர் பொத்தானைப் பயன்படுத்தவும். குறிப்புகள் இயல்பாக உள்நிலையானவை; சேவை மேசையில் உள்ள பகுப்பாய்வாளர்களுக்கு மட்டுமே தெரியும்.',
            'step3' => '<strong>மின்னஞ்சலில் பதிலளிக்கவும் அல்லது முன்னனுப்பவும்</strong> &mdash; இறுதிப் பயனருக்கோ மூன்றாம் தரப்புக்கோ செய்தி அனுப்ப பதிலளி அல்லது முன்னனுப்பு செயல்களைப் பயன்படுத்தவும். அனுப்பிய செய்தி உள்ளடக்கத்துடன் சேர்த்து மின்னஞ்சல் செயல்பாட்டுப் பதிவில் பதிவு செய்யப்படும்.',
            'files_heading' => '<strong>கோப்பு இணைப்புகள்</strong>',
            'files_body' => 'ஸ்கிரீன்ஷாட்கள், பதிவுகள், ஆவணங்கள் அல்லது எந்த ஆதரவுக் கோப்பையும் நேரடியாக டிக்கெட்டில் இணைக்கலாம். கோப்புகளை இணைப்பு இடும் பகுதியில் இழுத்து விடலாம் அல்லது கோப்பு உலாவியில் தேர்ந்தெடுக்கலாம். இணைப்புகள் சேவையகத்தில் சேமிக்கப்பட்டு டிக்கெட்டின் செயல்பாட்டுப் பதிவுடன் இணைக்கப்படுவதால் எதுவும் தொலையாது.',
            'audit_heading' => '<strong>தணிக்கைப் பதிவு</strong>',
            'audit_body' => 'பகுப்பாய்வாளரின் தலையீடு இல்லாமலே செயல்பாட்டுப் பதிவு ஒவ்வொரு செயலையும் தானாகப் பதிவு செய்கிறது. முன்னுரிமை நடுத்தரத்திலிருந்து அதிகத்துக்கு மாற்றப்படும்போது, பழைய மற்றும் புதிய மதிப்புகள் பதிவாகின்றன. டிக்கெட் மறுஒதுக்கீடு செய்யப்படும்போது, முந்தைய மற்றும் புதிய பகுப்பாய்வாளர் இருவரும் பதிவாகிறார்கள். இது ITIL தணிக்கைத் தேவைகளைப் பூர்த்தி செய்யும் முழுமையான, மாற்ற முடியாத வரலாற்றை உருவாக்குகிறது; டிக்கெட்டுகள் எவ்வாறு கையாளப்படுகின்றன என்பதை மேலாளர்கள் புரிந்துகொள்ளவும் உதவுகிறது.',
            'tip' => 'மின்னஞ்சலில் பதிலளிக்கும்போது, அதே செயலில் Cc பெறுநர்களைச் சேர்த்து கோப்புகளையும் இணைக்கலாம். முழு மின்னஞ்சல் உரையாடலும் டிக்கெட்டின் செயல்பாட்டுப் பதிவில் இழையாக இணைக்கப்படுவதால் எல்லாத் தொடர்பும் ஒரே இடத்தில் இருக்கும்.',
        ],
        'ai' => [
            'heading' => 'AI கருவிகள்',
            'intro' => 'டிக்கெட் பணிப்பாய்வுக்குள் Claude இயக்கும் இரண்டு அம்சங்கள் உள்ளன: <strong>பதில் சீரமைப்பு</strong> ஒரு கரடுமுரடான வரைவை சரியாக வடிவமைக்கப்பட்ட மின்னஞ்சலாக மாற்றி எழுதுகிறது; <strong>AI-ஐ கேளுங்கள்</strong> டிக்கெட்டின் சூழலைப் பயன்படுத்தி அறிவுத்தளத்தை இயல்பு மொழியில் தேடுகிறது.',
            'cleanup_heading' => '<strong>பதில் சீரமைப்பு &mdash; பதில் எடிட்டரில் உள்ள ✨ பொத்தான்</strong>',
            'cleanup_body' => 'பதிலில் ஒரு விரைவான கரடுமுரடான வரைவை (அல்லது *"need to restart the print service, take screenshot for them"* போன்ற புள்ளிகளை மட்டும்) தட்டச்சு செய்து <strong>✨ சீரமை</strong> பொத்தானைக் கிளிக் செய்யவும். Claude அதை சரியாக வடிவமைக்கப்பட்ட மின்னஞ்சலாக மீண்டும் எழுதுகிறது &mdash; கோரிக்கையாளரிடமிருந்து <em>அன்புள்ள [பெயர்],</em> வணக்கம் சேர்க்கிறது, இலக்கணத்தைத் திருத்துகிறது, உள்ளமைக்கப்பட்ட தொனியைப் பயன்படுத்துகிறது, <em>வாழ்த்துகளுடன்,</em> என முடிக்கிறது. நீங்கள் எழுதியதற்கு மேல் தொழில்நுட்ப விவரங்களை உருவாக்கவோ, போலி மன்னிப்புகளைச் சேர்க்கவோ, உள்ளடக்கத்தை நீட்டவோ கூடாது என்று கட்டளை இறுக்கமாக வரையறுக்கப்பட்டுள்ளது.',
            'cleanup_streams' => '<strong>நேரலையில் வருகிறது</strong> &mdash; Claude உருவாக்கும்போதே மறுஎழுத்து எடிட்டரில் தோன்றும் (சுழலும் குறியைப் பார்த்துக் காத்திருக்க வேண்டாம்).',
            'cleanup_undo' => '<strong>30 வினாடிகளுக்கு செயல்தவிர் இணைப்பு</strong> &mdash; Claude மறுஎழுத்தைக் கெடுத்துவிட்டால், மறுஎழுத்து முடிந்த 30 வினாடிகளுக்கு எடிட்டருக்குக் கீழே ஒரு சிறிய <em>செயல்தவிர்</em> இணைப்பு தோன்றி, அசல் வரைவை மீட்டெடுக்கும்.',
            'cleanup_tone' => '<strong>தொனிக்கு ஏற்ப</strong> &mdash; <strong>அமைப்புகள் &rarr; பதில் சீரமைப்பு</strong> இல் உள்ளமைக்கக்கூடிய மூன்று தொனி முன்னமைவுகள்: <em>நட்பாக</em> (இயல்புநிலை), <em>முறையாக</em>, <em>சுருக்கமாக</em>. உங்கள் குழுவின் பாணிக்குப் பொருந்துவதைத் தேர்ந்தெடுக்கவும்.',
            'cleanup_key' => '<strong>சொந்த API key</strong> &mdash; RFP / அறிவுத்தளம் / பணிப்பாய்வு AI அம்சங்களிலிருந்து தனியான Anthropic key; இதனால் அதன் பயன்பாடு Anthropic கட்டணப் பலகையில் தனி வரியாகத் தெரியும். <strong>அமைப்புகள் &rarr; பதில் சீரமைப்பு</strong> இல் உள்ளமைக்கப்படுகிறது.',
            'cleanup_tip' => 'சீரமைப்பு வழக்கமான "நான் இதை முயன்றேன், தயவுசெய்து X முயலுங்கள்" பாணிப் பதில்களுக்கு மிகவும் ஏற்றது. நீண்ட, நுணுக்கமான செய்திகளை நீங்களே எழுதுவது நல்லது &mdash; AI கட்டமைப்பில் சிறந்தது, ஆனால் உங்கள் குறிப்பிட்ட சூழல் அதற்குத் தெரியாது.',
            'ask_heading' => '<strong>AI-ஐ கேளுங்கள் &mdash; டிக்கெட் கருவிப்பட்டியில் உள்ள 🤖 பொத்தான்</strong>',
            'ask_body' => 'திறந்துள்ள டிக்கெட்டின் பொருள், உள்ளடக்கம் மற்றும் வாசிப்புப் பலகச் சூழலை அறிந்த ஒரு சறுக்கும் அரட்டைப் பலகத்தைத் திறக்க டிக்கெட் கருவிப்பட்டியில் உள்ள <strong>AI-ஐ கேளுங்கள்</strong> பொத்தானை (🤖) கிளிக் செய்யவும். *"have we seen this before?"* அல்லது *"what\'s the usual fix for this error?"* போன்ற கேள்விகளைக் கேளுங்கள்; அது <a href="../knowledge/" style="color:#0078d4;">அறிவுத்தளத்தை</a> (Claude + OpenAI embeddings மூலம்) பொருள் அடிப்படையில் தேடி, தொடர்புடைய கட்டுரைகளையும் அவற்றைத் திறக்க நேரடி இணைப்புகளையும் தருகிறது.',
            'ask_context' => '<strong>சூழல் அறிந்தது</strong> &mdash; நீங்கள் எந்த டிக்கெட்டைப் பார்க்கிறீர்கள் என்பதை பலகம் அறியும்; எனவே பொதுவான கேள்விகளைக் கேட்கலாம், தொடர்புடைய சூழலை அது கண்டறியும்.',
            'ask_linked' => '<strong>இணைக்கப்பட்ட கட்டுரைகள்</strong> &mdash; பரிந்துரைகளைக் கிளிக் செய்யலாம்; பொருந்தும் அறிவுத்தளக் கட்டுரை புதிய தாவலில் திறக்கும்.',
            'ask_shared' => '<strong>அறிவுத்தளத் தொகுதியுடன் பகிரப்பட்டது</strong> &mdash; அறிவுத்தள AI தேடலின் அதே key + மாதிரியை AI பயன்படுத்துவதால், ஒருமுறை உள்ளமைத்தால் இரண்டுக்கும் போதும். அமைப்பு விவரங்களுக்கு அறிவுத்தளத் தொகுதி உதவியைப் பார்க்கவும்.',
        ],
        'csat' => [
            'heading' => 'வாடிக்கையாளர் திருப்தி கணக்கெடுப்புகள் (CSAT)',
            'intro' => 'டிக்கெட் தீர்க்கப்படும்போது கோரிக்கையாளருக்கு 1&ndash;5 திருப்தி கணக்கெடுப்பை மின்னஞ்சலில் அனுப்பவும், உள்நுழைவு தேவையில்லாத பக்கத்தில் பதிலைப் பெறவும், பிரத்யேக பகுப்பாய்வுப் பக்கத்தில் ஒவ்வொரு பகுப்பாய்வாளரின் போக்குகளைக் கண்காணிக்கவும்.',
            'modes_heading' => '<strong>இரண்டு தூண்டுதல் முறைகள் &mdash; ஒன்றைத் தேர்ந்தெடுக்கவும்</strong>',
            'mode_auto' => '<strong>மூடும்போது தானாக</strong> &mdash; டிக்கெட் ஏதேனும் மூடிய நிலைக்கு மாறும்போது கணக்கெடுப்பு தானாக வரிசையில் சேரும். பகுப்பாய்வாளர் எதுவும் செய்யத் தேவையில்லை &mdash; தீர்வே கணக்கெடுப்பைத் தூண்டுகிறது.',
            'mode_manual' => '<strong>கைமுறை மட்டும்</strong> &mdash; கேட்க விரும்பும்போது பகுப்பாய்வாளர் டிக்கெட் கருவிப்பட்டியில் உள்ள ⭐ <strong>பின்னூட்டம்</strong> பொத்தானைக் கிளிக் செய்கிறார். ஒவ்வொரு டிக்கெட்டுக்கும் பின்னூட்டம் கேட்கலாமா என்று நீங்களே முடிவு செய்ய விரும்பினால் பயனுள்ளது.',
            'mode_off' => '<strong>அணை</strong> &mdash; அம்சம் முடக்கப்பட்டுள்ளது; கணக்கெடுப்பு மின்னஞ்சல்கள் அனுப்பப்படாது.',
            'modes_choose' => '<strong>டிக்கெட்டுகள் &rarr; அமைப்புகள் &rarr; CSAT</strong> இல் தேர்ந்தெடுக்கவும். <em>தானியங்கி</em> முறையிலும் கைமுறை பொத்தான் வேலை செய்யும் &mdash; தேவைப்பட்டால் ஏற்கனவே கணக்கெடுக்கப்பட்ட டிக்கெட்டுக்கு பகுப்பாய்வாளர்கள் மீண்டும் பின்னூட்டம் கோரலாம்.',
            'template_heading' => '<strong>மின்னஞ்சல் வார்ப்புரு</strong>',
            'template_body' => 'கணக்கெடுப்பு மின்னஞ்சலின் உள்ளடக்கம் ஏற்கனவே உள்ள <strong>மின்னஞ்சல் வார்ப்புருக்கள்</strong> தாவலிலிருந்து வருகிறது &mdash; நிகழ்வு <strong>CSAT survey</strong> (<em>Ticket assigned</em> / <em>Ticket closed</em> உடன் உள்ள புதிய நிகழ்வு) கொண்ட ஒரு வார்ப்புருவை உருவாக்கி, மதிப்பீட்டு URL தோன்ற வேண்டிய இடத்தில் <code>[csat_link]</code> மெர்ஜ் குறியீட்டைச் சேர்க்கவும். வழக்கமான மெர்ஜ் குறியீடுகளும் (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) வழக்கம்போல் கிடைக்கும்.',
            'template_tip' => 'செயலில் உள்ள CSAT வார்ப்புரு இல்லையென்றால், <em>பின்னூட்டம்</em> பொத்தான் தெளிவான பிழையுடன் மறுக்கும், தானியங்கித் தூண்டுதல் அமைதியாகத் தவிர்க்கும் &mdash; செயலற்ற கணக்கெடுப்பு இணைப்புகளை நீங்கள் ஒருபோதும் உருவாக்க மாட்டீர்கள்.',
            'survey_heading' => '<strong>கணக்கெடுப்புப் பக்கம்</strong>',
            'survey_body' => 'கோரிக்கையாளர் மின்னஞ்சலில் உள்ள இணைப்பைக் கிளிக் செய்து, 1&ndash;5 தேர்வியும் விருப்பமான கருத்துப் பெட்டியும் கொண்ட, உள்நுழைவு தேவையில்லாத பக்கத்தை அடைகிறார். <strong>அமைப்புகள் &rarr; CSAT</strong> இல் இரண்டு காட்சிப் பாணிகளை உள்ளமைக்கலாம்:',
            'survey_stars' => '<strong>நட்சத்திரங்கள்</strong> &mdash; மேல்வைக்கும்போது நிரம்பும் கிளாசிக் பின்தொடரும் நடத்தை. 3-ஆம் நட்சத்திரத்தின் மேல் வைத்தால் 1+2+3 தங்க நிறத்தில் நிரம்பும். உறுதிசெய்ய கிளிக் செய்யவும்.',
            'survey_emojis' => '<strong>எமோஜிகள்</strong> &mdash; 😡 🙁 😐 🙂 😀 ஆகிய 5 முகங்கள் 40% ஒளிபுகாமையுடன் சாம்பல்நிறத்தில் தொடங்கும்; மேல்வைக்கப்பட்ட அல்லது தேர்ந்தெடுக்கப்பட்டது 1.25&times; அளவில் முழு நிறத்துக்குத் திரும்பும். உறுதிசெய்ய கிளிக் செய்யவும்.',
            'survey_store' => 'எந்தப் பாணியைப் பயன்படுத்தினாலும் இரண்டு முறைகளும் ஒரே 1&ndash;5 எண்ணைச் சேமிப்பதால் டாஷ்போர்டுகளும் சராசரிகளும் ஒரே மாதிரி செயல்படும். கணக்கெடுப்பு URL ஒருமுறை மட்டுமே பயன்படும் &mdash; பயனர் சமர்ப்பித்ததும், அதே இணைப்பு மீண்டும் சமர்ப்பிப்பை மறுக்கும்.',
            'chat_heading' => '<strong>அரட்டை வாடிக்கையாளர்களை அவர்களின் அரட்டையிலேயே கேட்டல்</strong>',
            'chat_body' => '<strong>அரட்டை வாடிக்கையாளர்களை அவர்களின் அரட்டையிலேயே கேள்</strong> தேர்வுசெய்யப்பட்டிருந்தால், WhatsApp, Telegram, Slack, Microsoft Teams அல்லது Mattermost இல் தொடர்பு கொண்ட வாடிக்கையாளரிடம் மின்னஞ்சலுக்குப் பதிலாக அந்த அரட்டையிலேயே கேட்கப்படும் &mdash; Telegram, Teams, Mattermost இல் ஐந்து பொத்தான்கள், மற்றவற்றில் &ldquo;ஒற்றை இலக்கத்துடன் பதிலளிக்கவும்&rdquo;. அவர்களின் பதில் மின்னஞ்சல் கணக்கெடுப்பின் அதே முடிவுகளுக்குள் செல்லும்.',
            'chat_rules' => 'WhatsApp இன் 24 மணிநேர பதில் சாளரம் திறந்திருக்கும்போது மட்டுமே கேட்கப்படும்; அதற்கு வெளியே, அல்லது அரட்டைச் செய்தியை அனுப்ப முடியாவிட்டால், மின்னஞ்சல் கணக்கெடுப்பு பயன்படுத்தப்படும். கேள்விக்குப் பிறகு உடனடியாக வரும் இலக்கம் மட்டுமே மதிப்பீடாகக் கருதப்படும் &mdash; அதே அரட்டையில், ஒரு வாரத்துக்குள், வாடிக்கையாளர் வேறு எதுவும் எழுதுவதற்கு முன் &mdash; எனவே பகுப்பாய்வாளரின் கேள்விக்கான பதிலாக வரும் &ldquo;3&rdquo; செய்தியாகவே இருக்கும். மேம்படுத்திய பின் அணைந்திருக்கும்; புதிய நிறுவலில் இயங்கும்.',
            'analytics_heading' => '<strong>பகுப்பாய்வுப் பக்கம்</strong>',
            'analytics_body' => '<code>tickets/csat/</code> இல் உள்ள பகுப்பாய்வு டாஷ்போர்டைத் திறக்க (பணி அட்டவணைக்கும் அமைப்புகளுக்கும் இடையிலான) ⭐ <strong>CSAT</strong> வழிசெலுத்தல் பொத்தானைக் கிளிக் செய்யவும். தேர்ந்தெடுக்கக்கூடிய காலம்: 7 / 30 / 90 / 365 நாட்கள்.',
            'card_kpi_title' => 'KPI டைல்கள்',
            'card_kpi_body' => 'சராசரி மதிப்பீடு (5-இல்), பதில்களின் எண்ணிக்கை, பதில் விகிதம் (பதிலளித்தவை ÷ அனுப்பியவை)',
            'card_dist_title' => 'மதிப்பெண் விநியோகம்',
            'card_dist_body' => '1–5 மதிப்பீடுகளின் பட்டை வரைபடம்; சரியான எண்ணிக்கைகளையும் சதவீதங்களையும் காட்டுகிறது',
            'card_leader_title' => 'பகுப்பாய்வாளர் வாரியான முன்னணிப் பட்டியல்',
            'card_leader_body' => 'ஒவ்வொரு பகுப்பாய்வாளருக்கும் சராசரி மதிப்பீடு + பதில்களின் எண்ணிக்கை, சராசரியின் இறங்குவரிசையில். மேம்பாட்டு உரையாடல்களுக்குப் பயன்படுத்தவும்',
            'card_recent_title' => 'சமீபத்திய பதில்கள்',
            'card_recent_body' => 'மதிப்பீடுகள் புதியவை முதலில், ஒரு பக்கத்துக்கு 25, அவற்றின் இலவச உரைக் கருத்துகளுடனும் அவற்றை அளித்த வாடிக்கையாளருடனும், மூல டிக்கெட்டுக்கு இணைக்கப்பட்டவை',
            'analytics_filters' => 'தலைப்பின் கீழுள்ள வடிப்பான்களால் பக்கத்தைச் சுருக்கலாம்: (நாள் பொத்தான்களுக்குப் பதிலாக) <strong>From / To</strong> தேதி வரம்பு, <strong>Rating</strong> வரம்பு (நேர்மறை 4-5, நடுநிலை 3, எதிர்மறை 1-2), ஒரு <strong>பகுப்பாய்வாளர்</strong> மற்றும் ஒரு <strong>வாடிக்கையாளர்</strong>. பகுப்பாய்வாளரும் வாடிக்கையாளரும் பக்கத்தில் உள்ள ஒவ்வொரு எண்ணையும் சுருக்குகின்றன; மதிப்பீட்டு வரம்பு பதில்களின் பட்டியலை மட்டுமே சுருக்குவதால் சராசரி தொடர்ந்து அர்த்தமுள்ளதாக இருக்கும். தொலைபேசியில் வடிப்பான்கள் திரையின் கீழே உள்ள <strong>வடிப்பான்கள்</strong> பொத்தானுக்குப் பின்னால் இருக்கும். வடிகட்டிய பக்கத்தை புக்மார்க் செய்யலாம்.',
            'analytics_company' => 'ஒவ்வொரு எண்ணும் தலைப்பில் உள்ள <strong>நிறுவன மாற்றியைப்</strong> பின்பற்றும்: நீங்கள் தேர்ந்தெடுத்த நிறுவனம், அல்லது <strong>அனைத்து நிறுவனங்கள்</strong> என்பதில் நீங்கள் காணக்கூடிய ஒவ்வொரு நிறுவனமும்.',
            'analytics_tip' => 'அனுப்பும் நேரத்தில் பகுப்பாய்வாளர் id கணக்கெடுப்பு வரிசையில் பதிவு செய்யப்படுவதால் (நேரலையில் தேடப்படுவதில்லை), டிக்கெட் மறுஒதுக்கீடு செய்யப்பட்டாலும் பகுப்பாய்வாளர் வாரியான கணக்கீடு நிலைத்திருக்கும். மூடுவதற்கு முன் டிக்கெட் பலரிடம் கைமாறினால், உண்மையில் அதை மூடிய பகுப்பாய்வாளரே மதிப்பீட்டுக்கு உரியவர்.',
            'one_heading' => '<strong>ஒரு டிக்கெட்டுக்கு ஒரு கணக்கெடுப்பு</strong>',
            'one_body' => '<em>ஒரு டிக்கெட்டுக்கு ஒரு கணக்கெடுப்பு</em> இயக்கத்தில் இருந்தால் (இயல்புநிலை), மீண்டும் திறந்து மூடப்பட்ட டிக்கெட்டுக்கு பகுப்பாய்வாளர் கைமுறையாகத் தூண்டும்போது மட்டுமே இன்னொரு கணக்கெடுப்பு செல்லும் &mdash; மீண்டும் மீண்டும் சுழலும் சிக்கலான டிக்கெட்டுக்கு கணக்கெடுப்பு அஞ்சல் குவிவதைத் தடுக்கிறது. ஒவ்வொரு மூடலுக்கும் புதிய கணக்கெடுப்பு செல்ல வேண்டுமென்றால் இதை அணைக்கவும்.',
        ],
        'users' => [
            'heading' => 'பயனர் மேலாண்மை',
            'intro' => '<strong>பயனர்கள்</strong> வழிசெலுத்தல் பொத்தான் <code>tickets/users.php</code>-ஐத் திறக்கிறது &mdash; ஒவ்வொரு இறுதிப் பயனரின் (டிக்கெட் எழுப்புபவர்கள், பகுப்பாய்வாளர்கள் அல்ல) அடைவு, ஒவ்வொருவரின் டிக்கெட் வரலாற்றுடன்.',
            'p_intro' => 'பயனர்கள் அமைப்பிற்குள் நான்கு எதிர்வினை வழிகளில் வருகிறார்கள் &mdash; போர்டல் சுய-பதிவு, புதிய அனுப்புநரிடமிருந்து வரும் மின்னஞ்சல், அஞ்சல் பெட்டி போலர், அல்லது தூண்டப்பட்ட டிக்கெட்டிலிருந்து ஒருவரை உருவாக்கும் பணிப்பாய்வு இயந்திரம். இது பெரும்பாலான நிகழ்வுகளை உள்ளடக்கும், ஆனால் பயனர்கள் பக்கத்தில் ஒரு பயனரை <strong>முன்கூட்டியே உருவாக்கவும்</strong> (எ.கா. விரைவில் அணுகல் தேவைப்படும் புதிய பணியாளர்) இருக்கும் வரிசைகளை <strong>திருத்தவும்</strong> அல்லது <strong>நீக்கவும்</strong> முடியும்.',
            'add_heading' => '<strong>பயனரைச் சேர்</strong>',
            'add_body' => 'பயனர்-பட்டியல் தலைப்பில் உள்ள <strong>சேர்</strong> பொத்தான் நபர் எடிட்டரைத் திறக்கிறது. இது <strong>சொத்துகள் &rarr; பயனர்கள்</strong> திறக்கும் அதே எடிட்டர், எனவே எந்தத் திரையில் இருந்தாலும் ஒரு நபர் ஒரே முறையில் சேர்க்கப்பட்டு மாற்றப்படுகிறார்:',
            'add_email' => '<strong>மின்னஞ்சல்</strong> &mdash; விருப்பத்தேர்வு, ஏனெனில் அடைவு மூலம் உள்நுழைபவர்களுக்கு அஞ்சல் பெட்டி இல்லாமல் இருக்கலாம்; அவர்கள் உள்நுழைவுப் பெயரால் கண்டறியப்படுவார்கள். மின்னஞ்சல் முகவரி அல்லது காட்சிப் பெயர் இரண்டில் ஒன்றைக் கொடுக்கவும். முகவரி தனித்துவமாக இருக்க வேண்டும், மேலும் அது ஒரு பகுப்பாய்வாளருக்குச் சொந்தமானதாக இருக்கக்கூடாது.',
            'add_names' => '<strong>காட்சிப் பெயர் / விருப்பப் பெயர்</strong> &mdash; விருப்பத்தேர்வு. மின்னஞ்சல்களில் பயனர் தன்னை எவ்வாறு வாழ்த்தப்படுவதைக் காண்கிறாரோ அதுவே விருப்பப் பெயர் (எ.கா. <em>"Ed Mozley"</em> என்பதற்குப் பதிலாக <em>"Ed"</em>).',
            'add_password' => '<strong>கடவுச்சொல்</strong> &mdash; விருப்பத்தேர்வு. காலியாக விட்டால் <em>கடவுச்சொல் இல்லாத</em> கணக்கு உருவாகும் &mdash; உள்வரும் டிக்கெட் பயனர்கள் தொடங்கும் அதே நிலை. பயனர் பின்னர் சுய-சேவை போர்ட்டலின் பதிவு வழியாகத் தனது சொந்தக் கடவுச்சொல்லை அமைத்து கணக்கைக் கோரலாம்.',
            'add_details' => '<strong>பணிப்பெயர், துறை, அலுவலகம், தொலைபேசி, கைப்பேசி, பணியாளர் ID மற்றும் மேலாளர்</strong> &mdash; அனைத்தும் விருப்பத்தேர்வு, மேலும் அனைத்தும் உள்நுழைவை அல்ல <em>நபரை</em> விவரிக்கின்றன. நிரப்புவது பயனுள்ளது: <strong>அலுவலகம்</strong> ஒருவரைத் தேடுவதற்கு முன் அவர் எந்தத் தளத்தில் இருக்கிறார் என்பதைச் சொல்கிறது, <strong>மேலாளர்</strong> அறிக்கையிடல் வரிசையைப் பதிவு செய்கிறது (கண்டுபிடிக்க பெயரின் ஒரு பகுதியைத் தட்டச்சு செய்யவும்), <strong>பணியாளர் ID</strong> என்பது மின்னஞ்சல் முகவரியையே அறியாத சம்பள அமைப்புடன் ஒப்பிடும்போது இணைக்கும் விசை. அடைவிலிருந்து இறக்குமதி செய்தால் இவை அனைத்தும் நிரப்பப்பட்டு வரும். CardDAV முகவரிப் புத்தகம் பணியாளர் ID மற்றும் மேலாளர் தவிர அனைத்தையும் நிரப்புகிறது, ஏனெனில் தொடர்பு அட்டையில் அவற்றைச் சேமிக்க இடமில்லை.',
            'managed_heading' => '<strong>வேறு இடத்தில் பராமரிக்கப்படும் நபர்கள்</strong>',
            'source_body' => '<strong>ஒரு நபர் எங்கிருந்து வருகிறார்</strong> என்பது அவர்களின் விவரங்களில் குறிப்பிடப்படுகிறது (<em>விவரங்கள் வந்தது: Contoso AD - directory</em>), மேலும் தேடல் பெட்டியின் கீழுள்ள <strong>மூலம்</strong> வடிகட்டி ஒரு அடைவு அல்லது முகவரிப் புத்தகத்திலிருந்து வந்தவர்களை மட்டும், அல்லது FreeITSM-இல் சேர்க்கப்பட்டவர்களை மட்டும், ஒவ்வொன்றின் அருகிலும் எண்ணிக்கையுடன் பட்டியலிடுகிறது. யாராவது ஒரு மூலத்துடன் இணைக்கப்பட்டவுடன் இது தோன்றும்.',
            'add_book_body' => '<strong>முகவரிப் புத்தகத்தில் சேர்.</strong> மின்னஞ்சல் அனுப்பிய ஒருவர் இங்கே இருக்கிறார் ஆனால் எந்த முகவரிப் புத்தகத்திலும் இல்லை. <em>இந்த முகவரிப் புத்தகத்தில் பகுப்பாய்வாளர்கள் நபர்களைச் சேர்க்க அனுமதி</em> என்பதை நிர்வாகி இயக்கியிருந்தால் (முகவரிப் புத்தகத்தில், கணினி &rarr; அங்கீகாரம்), அந்த நபருக்கு திருத்து பொத்தானின் அருகில் <strong>முகவரிப் புத்தகத்தில் சேர்</strong> பொத்தான் தோன்றும். அது முதலில் கேட்கிறது, அட்டையில் என்ன போகும் என்பதைக் காட்டுகிறது, பின்னர் அவர்களின் தொடர்பை உருவாக்கி இணைக்கிறது &mdash; அதே நபர், நகல் அல்ல. புத்தகத்தில் ஏற்கனவே மின்னஞ்சல் முகவரி உள்ள ஒருவரை அது சேர்க்காது (அதற்குப் பதிலாக இறக்குமதியை இயக்கவும்), மேலும் அடுத்த இறக்குமதி புதிய தொடர்பை எடுத்துக்கொள்வதை உறுதிசெய்கிறது, இல்லையெனில் அட்டையைத் திரும்பப் பெறுகிறது.',
            'managed_body' => 'ஒரு நபர் இறக்குமதி செய்யப்பட்டிருந்தால் &mdash; LDAP அல்லது Active Directory-இலிருந்து, அல்லது CardDAV முகவரிப் புத்தகத்திலிருந்து &mdash; அந்த மூலத்துக்குச் சொந்தமான விவரங்கள் <strong>படிக்க-மட்டும்</strong>, மேலும் மோடல் அவற்றை சாம்பல் நிறமாக்குகிறது. அவை எங்கிருந்து வந்தனவோ அதுவே உண்மையின் மூலம், அடுத்த இறக்குமதி இங்கே தட்டச்சு செய்த எதையும் மேலெழுதும், எனவே சேமிப்பு ஏற்கப்பட்டு ஒரு மணி நேரம் கழித்து அமைதியாக மாற்றப்படுவதற்குப் பதிலாக முற்றிலுமாக மறுக்கப்படுகிறது. <strong>எந்த</strong> விவரங்கள் என்பது மூலத்தைப் பொறுத்தது: அடைவு ஏழையும் வைத்திருக்கும், முகவரிப் புத்தகம் ஐந்தை வைத்திருக்கும் &mdash; அதில் பணியாளர் எண்ணையோ அறிக்கையிடல் வரிசையையோ வைக்க இடமில்லை, எனவே அந்த இரண்டும் உங்களால் நிரப்பப்படுபவை. மேலும் முகவரிப் புத்தகத்தில் <em>மாற்றங்களைத் திருப்பி எழுது</em> இயக்கப்பட்டிருந்தால், எதுவும் பூட்டப்படாது: நீங்கள் தட்டச்சு செய்தது தொடர்பு அட்டைக்கு அனுப்பப்படும், எனவே அடுத்த இறக்குமதி மாற்றியமைக்க எதுவும் இல்லை. நிறுவனம் மற்றும் கடவுச்சொல் உட்பட பதிவில் உள்ள மற்ற அனைத்தும் எப்போதும் திருத்தக்கூடியவை.',
            'edit_heading' => '<strong>பயனரைத் திருத்து</strong>',
            'edit_body' => 'பட்டியலில் ஒரு பயனரைத் தேர்ந்தெடுத்து, விவரத் தலைப்பில் <strong>திருத்து</strong> என்பதைக் கிளிக் செய்யவும். அதே எடிட்டர், முன்பே நிரப்பப்பட்டது. கடவுச்சொல் இல்லாமல் சேமித்தால் இருக்கும் ஹாஷ் தொடப்படாது; ஒன்றை வழங்கினால் அது மீட்டமைக்கப்படும். அவர்களின் மேலாளர் நீங்கள் பார்க்க முடியாத நிறுவனத்தில் இருந்தால், மேலாளர் பெட்டி அதைச் சொல்லும், வேறொருவரைத் தேர்ந்தெடுக்காத வரை மேலாளர் அப்படியே வைக்கப்படுவார்.',
            'signin_body' => '<strong>இதன் மூலம் உள்நுழைகிறார்</strong> ஒரு நபர் எந்த ஒற்றை உள்நுழைவு வழங்குநருடன் இணைக்கப்பட்டுள்ளார் என்பதைக் காட்டுகிறது. அதன் அருகிலுள்ள <strong>இணைப்பை நீக்கு</strong> உறுதிப்படுத்தலுக்குப் பிறகு அந்த இணைப்பை அகற்றுகிறது, எனவே அவர்களின் அடுத்த உள்நுழைவு புதிதாகத் தொடங்கும் &mdash; வேறு வழங்குநருக்கு மாறியவர்களுக்கு, அல்லது தவறான கணக்குடன் இணைக்கப்பட்டவர்களுக்கு. அடைவு ஒத்திசைவால் நிர்வகிக்கப்படுபவர்களுக்கு இது வழங்கப்படாது, ஏனெனில் அது அவர்களை மீண்டும் இணைத்துவிடும்.',
            'company_body' => 'உங்களிடம் ஒன்றுக்கு மேற்பட்ட நிறுவனங்கள் இருக்கும்போது <strong>நிறுவனம்</strong> தோன்றும். புதிய நபருக்கு, காலியாக விட்டால் அவர்களின் மின்னஞ்சல் முகவரியிலிருந்து நிறுவனம் கண்டறியப்படும்; இருக்கும் நபருக்கு, காலி என்றால் நிறுவனம் இல்லை, அவர்களின் டிக்கெட்டுகள் ட்ரையாஜுக்குச் செல்லும்.',
            'managers_heading' => '<strong>மேலாளர்கள்</strong>',
            'managers_body' => 'சுய-சேவை போர்ட்டலில் ஒரு நபரை <strong>மேலாளராக</strong> ஆக்கலாம்: அவர்கள் நிர்வகிக்கும் நபர்களின் டிக்கெட்டுகளைப் பட்டியலிடும் <strong>குழு டிக்கெட்டுகள்</strong> தாவலைப் பெறுவார்கள். நிர்வாகி <strong>கணினி &rarr; மேலாளர்கள்</strong> என்பதில் இயக்கும் வரை இது அணைந்திருக்கும்; அங்குதான் அந்த டிக்கெட்டுகளுக்கு மேலாளர்கள் பதிலளிக்கலாமா அல்லது மூடலாமா என்பதும், ரகசியமான டிக்கெட்டில் அவர்கள் எதைப் பார்ப்பார்கள் என்பதும் (இயல்பாக எதுவுமில்லை) தீர்மானிக்கப்படுகிறது.',
            'managers_sources' => 'ஒருவர் இரண்டு வழிகளில் மேலாளராக இருக்கிறார், இரண்டும் ஒரே நேரத்தில்: அவர்கள் மற்றவர்களின் பதிவுகளில் <strong>மேலாளர்</strong> (கையால், அல்லது உங்கள் அடைவிலிருந்து), மேலும் அவர்களுக்காக <strong>மேலாண்மை வரிசைகள்</strong> அமைக்கப்பட்டுள்ளன. அந்த நபருக்கான முழுத்திரைப் பக்கத்தைத் திறக்க திருத்து பொத்தானின் அருகிலுள்ள <strong>மேலாளர் அணுகல்</strong> என்பதைக் கிளிக் செய்யவும்; அங்கு அவர்களுக்கு அனைவரையும், குறிப்பிட்ட நபர்களை, நபர் குழுக்களை, துறைகளை அல்லது அவர்களின் முழு அறிக்கையிடல் வரிசையை வழங்கலாம், மேலும் நபர்களை <strong>விலக்கலாம்</strong> &mdash; விலக்கு எப்போதும் வெல்லும், மேலாளர் புலத்தையும் விட. மேலாளர்கள் ஏற்கனவே இயக்கப்பட்டிருப்பதாகக் கணக்கிட்டு, அவர்களால் எத்தனை பேரைப் பார்க்க முடியும் என்பதை பக்கம் காட்டி அவர்களைப் பட்டியலிடுகிறது, எனவே இயக்குவதற்கு முன் சரிபார்க்கலாம். மேலாளரால் ஒருவரை <strong>ஏன்</strong> பார்க்க முடிகிறது, அதை எப்படி நிறுத்துவது என்பதைக் காண அந்தப் பட்டியலில் யாரையாவது கிளிக் செய்யவும்.',
            'managers_rules' => 'ஒரு மேலாளர் தனது சொந்த நிறுவனத்தில் உள்ளவர்களை மட்டுமே பார்ப்பார், தன்னை ஒருபோதும் பார்க்க மாட்டார், பணியிலிருந்து விலகிய பிறகு எதையும் பார்க்க மாட்டார். துறைகள் ஒவ்வொரு நபரிலும் தட்டச்சு செய்த பெயரால் பொருத்தப்படுகின்றன, எனவே மறுபெயரிடப்பட்ட துறை பொருந்துவதை நிறுத்தும் &mdash; யாரையும் பொருத்தாத துறை வரியைப் பற்றி பக்கமும் கணினி &rarr; மேலாளர்களும் எச்சரிக்கின்றன. இயல்பாக நிர்வாகிகள் மட்டுமே மேலாண்மை வரிகளை மாற்ற முடியும்; நபர்களைத் திருத்தக்கூடிய எவருக்கும் அதைத் திறக்க கணினி &rarr; மேலாளர்கள் உதவும்.',
            'delete_heading' => '<strong>பயனரை நீக்கு</strong>',
            'delete_body' => '<strong>நீக்கு</strong> பொத்தான் <strong>FK-பாதுகாப்பானது</strong>: பயனர் ஏதேனும் டிக்கெட்டுகளில் கோரிக்கையாளராக இருந்தாலோ <code>users_assets</code>-இல் வரிசைகள் இருந்தாலோ அது மறுக்கிறது, தெளிவான <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em> செய்தியைத் தருகிறது. தணிக்கை வரலாறு ஒருபோதும் அமைதியாக உடையாது.',
            'tip' => 'அனைத்து மோடல் புலங்களிலும் உலாவி தானியங்கு நிரப்புதல் முடக்கப்பட்டுள்ளது (கடவுச்சொல் புலத்தில் <code>autocomplete="new-password"</code> உட்பட), இதனால் <em>வேறொருவரின்</em> பதிவை உருவாக்குவதே முழு நோக்கமான படிவத்தில் பகுப்பாய்வாளரின் சொந்தச் சேமிக்கப்பட்ட நற்சான்றுகள் பரிந்துரைக்கப்படுவதில்லை.',
            'groups_heading' => '<strong>குழுக்கள்</strong>',
            'groups_body' => '<strong>நபர்கள்</strong> அருகிலுள்ள <strong>குழுக்கள்</strong> தாவல் பெயரிடப்பட்ட நபர் குழுக்களை வைத்திருக்கிறது &mdash; பகுப்பாய்வாளர்களும் சுய-சேவை போர்டல் பயனர்களும் ஒரே குழுவில். ஒரு குழு இங்கே ஒருமுறை உருவாக்கப்பட்டு FreeITSM முழுவதும் பயன்படுத்தப்படுகிறது, எனவே ஒரே பட்டியலை இருமுறை உருவாக்காமல் அறிவுத்தள கோப்புறைக்கு அணுகல் வழங்கலாம் அல்லது பயிற்சிப் பாடநெறியை ஒதுக்கலாம்.',
            'groups_make' => 'குழுக்கள் தாவலில் <strong>சேர்</strong> மூலம் <strong>ஒன்றை உருவாக்கவும்</strong>: ஒரு பெயர், மேலும் நிரப்பத் தகுந்த விளக்கம், ஏனெனில் அடுத்த நபர் குழு எதற்காக என்பதைச் சொல்ல முடிய வேண்டும்.',
            'groups_add' => 'தேடுவதன் மூலம் <strong>நபர்களைச் சேர்க்கவும்</strong> &mdash; இது பகுப்பாய்வாளர்களையும் போர்டல் பயனர்களையும் சேர்த்துக் கண்டறிகிறது, எனவே ஒருவர் எந்த வகை என்பதை நீங்கள் அறிய வேண்டியதில்லை.',
            'groups_expiry' => 'அணுகல் தற்காலிகமானால் <strong>உறுப்பினர் தகுதிக்கு முடிவு தேதி கொடுங்கள்</strong>. இரண்டு வாரங்களுக்கு தளத்தில் இருக்கும் மூன்று பொறியாளர்கள் கடைசி நாளுடன் சேர்க்கப்படுவார்கள், அது கடந்ததும் குழுவிலிருந்து தானாகவே வெளியேறுவார்கள். காலாவதியான உறுப்பினர் தகுதி பட்டியலில் இருக்கும், காலாவதியானது எனக் குறிக்கப்பட்டு, யாருக்கு எவ்வளவு காலம் வரை அணுகல் இருந்தது என்பதை நீங்கள் இன்னும் காணலாம்.',
            'groups_uses' => '<strong>ஒரு குழு எதற்குப் பயன்:</strong> அறிவுத்தள கோப்புறைக்கு அணுகல் வழங்குதல், மற்றும் ஒரு தொகுதி நபர்களுக்கு ஒரே நேரத்தில் LMS பயிற்சியை ஒதுக்குதல். உறுப்பினர் மாற்றங்கள் உடனடியாக நடைமுறைக்கு வரும் &mdash; பின்னர் மீண்டும் பயன்படுத்த எதுவும் இல்லை.',
            'groups_admin' => '<strong>டிக்கெட்டுகள் தொகுதி உள்ள எவரும் குழுக்களைப் பார்க்கலாம்; நிர்வாகி மட்டுமே ஒன்றை மாற்ற முடியும்.</strong> ஒருவரை குழுவில் சேர்ப்பது கட்டுப்படுத்தப்பட்ட அறிவுத்தள கோப்புறைக்கான அணுகலையும் வழங்கக்கூடும், எனவே இது கோப்பு வைப்பு அல்ல, அணுகல் வழங்கல்.',
        ],
        'dash' => [
            'heading' => 'டாஷ்போர்டு',
            'intro' => 'டிக்கெட் டாஷ்போர்டு தனிப்பயனாக்கக்கூடிய Chart.js விட்ஜெட்டுகளுடன் ஒரே பார்வையில் பகுப்பாய்வுகளை வழங்குகிறது. ஒவ்வொரு பகுப்பாய்வாளருக்கும் தனது சொந்த டாஷ்போர்டு அமைப்பு உண்டு, எனவே உங்கள் பங்குக்கு முக்கியமான அளவீடுகளில் கவனம் செலுத்தலாம் &mdash; தனிப்பட்ட பணிச்சுமை, குழு செயல்திறன், அல்லது SLA இணக்கம் எதுவானாலும்.',
            'step1' => '<strong>நூலகத்தைத் திறக்கவும்</strong> &mdash; திருத்தும் பயன்முறைக்குச் செல்ல டாஷ்போர்டைத் திருத்து என்பதைக் கிளிக் செய்து, பின்னர் விட்ஜெட் நூலகத்தை உலாவவும். முன்பே உருவாக்கப்பட்ட விட்ஜெட்டுகளைத் தேர்ந்தெடுக்கவும் அல்லது வரைபட வகையையும் திரட்ட வேண்டிய தரவுப் பண்பையும் தேர்ந்தெடுத்து சொந்தமாக உருவாக்கவும்.',
            'step2' => '<strong>விட்ஜெட்டுகளைச் சேர்க்கவும்</strong> &mdash; உங்கள் டாஷ்போர்டில் சேர்க்க நூலகத்தில் உள்ள எந்த விட்ஜெட்டிலும் + பொத்தானைக் கிளிக் செய்யவும். அது உடனடியாகத் தோன்றி உங்கள் டிக்கெட் தரவுத்தளத்திலிருந்து நேரடித் தரவைக் காட்டத் தொடங்குகிறது.',
            'step3' => '<strong>உள்ளமைக்கவும்</strong> &mdash; எந்த விட்ஜெட்டிலும் கியர் ஐகானைக் கிளிக் செய்து அதன் தலைப்பு, வரைபட வகை (பார், பை, டோனட், கோடு, அடுக்கு பார், பல-கோடு), தேதி வரம்பு வடிகட்டி, துறை வடிகட்டி, நேரக் குழுவாக்கம் (தினசரி, வாராந்திர, மாதாந்திர) ஆகியவற்றைத் தனிப்பயனாக்கவும்.',
            'step4' => '<strong>ஒழுங்குபடுத்தவும்</strong> &mdash; விட்ஜெட்டுகளை மறுவரிசைப்படுத்த இழுத்து விடவும். உங்கள் அமைப்பு ஒவ்வொரு பகுப்பாய்வாளருக்கும் சேமிக்கப்படுவதால் அமர்வுகளுக்கு இடையே நிலைத்திருக்கும்.',
            'examples' => 'பொதுவான விட்ஜெட் எடுத்துக்காட்டுகள்: <strong>நிலை வாரியாக டிக்கெட்டுகள்</strong> (திறந்தவை, தீர்க்கப்பட்டவை, மூடப்பட்டவற்றைக் காட்டும் டோனட் வரைபடம்), <strong>முன்னுரிமை வாரியாக டிக்கெட்டுகள்</strong> (தீவிரத்தன்மை வாரியாக அளவைக் காட்டும் பார் வரைபடம்), <strong>வாராந்திர அளவு</strong> (காலப்போக்கில் புதிய டிக்கெட்டுகளைக் கண்காணிக்கும் கோடு வரைபடம்), மற்றும் <strong>பகுப்பாய்வாளர் பணிச்சுமை</strong> (ஒவ்வொரு பகுப்பாய்வாளரின் செயலில் உள்ள டிக்கெட்டுகளைக் காட்டும் அடுக்கு பார்).',
            'tip' => 'தற்போதைய செயல்திறனை முந்தைய காலங்களுடன் ஒப்பிட தனிப்பட்ட விட்ஜெட்டுகளில் தேதி வரம்பு வடிகட்டிகளைப் பயன்படுத்தவும். எடுத்துக்காட்டாக, "இந்த மாதம் vs கடந்த மாதம்" பார்வை டிக்கெட் அளவின் போக்குகளை முன்கூட்டியே கண்டறிய உதவும்.',
        ],
        'cal_rota' => [
            'heading' => 'நாட்காட்டி &amp; பணி அட்டவணை',
            'intro' => 'உங்கள் குழு ஒழுங்காக இருக்க இரண்டு திட்டமிடல் கருவிகள் உதவுகின்றன: காலப்போக்கில் பணிச்சுமையைக் காட்டும் டிக்கெட் நாட்காட்டி, மற்றும் ஷிப்டுகளையும் அழைப்புப் பணி கிடைப்பையும் நிர்வகிக்கும் பணியாளர் பணி அட்டவணை.',
            'cal_heading' => '<strong>நாட்காட்டிக் காட்சி</strong>',
            'cal_body' => '&mdash; டிக்கெட்டிலேயே உள்ள, இன்பாக்ஸ் வலது-கிளிக் மெனுவிலும் உள்ள <strong>பணியைத் திட்டமிடு</strong> மூலம் நீங்கள் திட்டமிட்ட ஒவ்வொரு டிக்கெட்டையும் &mdash; நிலையான மணி நேரமாக அல்லாமல் அதன் <strong>உண்மையான நீளத்தில்</strong>, திட்டமிட்ட நேரத்தில் வண்ணத் தொகுதியாக நாட்காட்டி வரைகிறது. சிவப்புத் தொகுதிகள் <em>அதிக</em> முன்னுரிமை, பச்சை <em>குறைவு</em>, நீலம் மற்ற அனைத்தும். வழிசெலுத்த <em>இன்று</em>, <em>&lt;</em> / <em>&gt;</em> செவ்ரான்கள், மற்றும் <strong>மாதம் / வாரம் / நாள்</strong> மாற்றியைப் பயன்படுத்தவும்.',
            'cal_scope' => '<strong>என்னுடையவை அல்லது அனைவரும்.</strong> நாட்காட்டி உங்கள் சொந்தத் திட்டமிட்ட பணியில் திறக்கிறது, காட்சி பொத்தான்களின் அருகில் <strong>அனைவரும்</strong> என்ற மாற்றியுடன்; உங்கள் தேர்வு நினைவில் வைக்கப்படும். அனைவரும் என்பதில் ஒவ்வொரு டிக்கெட்டும் அதன் உரிமையாளருக்கான <strong>நிறத்தைக்</strong> கொண்டிருக்கும், திரையில் உள்ள நபர்களின் பெயர்களுடன் ஒரு குறிவிளக்கம் இருக்கும், ஒரு டிக்கெட்டின் மேல் வட்டமிட்டால் பார்வையை விலக்காமல் அது யாருடையது என்பதைச் சொல்லும். யாரிடமிருந்தும் எதுவும் மறைக்கப்படுவதில்லை &mdash; இவை இன்பாக்ஸ் ஏற்கனவே பட்டியலிடும் அதே டிக்கெட்டுகள்.',
            'cal_edit' => '<strong>பணியை மறுசீரமைத்தல்.</strong> வேறு நாள் அல்லது நேரத்துக்கு <strong>டிக்கெட்டை இழுக்கவும்</strong>: மாதக் காட்சியில் அது தனது நேரத்தை வைத்திருக்கும், வாரம் மற்றும் நாள் காட்சியில் நீங்கள் விடும் நேரத்தை, அருகிலுள்ள கால் மணி நேரத்துக்குப் பொருத்தி எடுத்துக்கொள்ளும். அதன் நீளம் ஒருபோதும் மாறாது &mdash; இழுப்பது <em>அப்போது தொடங்கு</em> என்பதைச் சொல்கிறது, <em>நீளமாக்கு</em> என்பதை அல்ல. அல்லது <strong>டிக்கெட்டைக் கிளிக் செய்து</strong> திறக்கலாம், அங்கு தேதி, நேரம், கால அளவு மற்றும் நாள் முழுவதும் அமைப்பை மாற்றலாம், அல்லது திட்டத்தை முழுவதுமாக அழிக்கலாம். நாட்காட்டி <strong>சில வினாடிகளுக்கு ஒருமுறை தானாகப் புதுப்பிக்கப்படும்</strong>, எனவே சக ஊழியர் எதையாவது திட்டமிட்டால் நீங்கள் மீண்டும் ஏற்றாமல் தோன்றும் &mdash; டிக்கெட்டைத் திறந்திருக்கும்போது அல்லது இழுத்துக்கொண்டிருக்கும்போது அது நிறுத்தி வைக்கும்.',
            'cal_month' => '<strong>மாதக் காட்சி</strong> &mdash; வார நாள் தலைப்புப் பட்டையுடன் கூடிய வழக்கமான 6-வரிசை கட்டம்; ஒவ்வொரு நாள் கலமும் தொடக்க நேரத்துடன் மூன்று டிக்கெட் மாத்திரைகள் வரை காட்டுகிறது, மேலும் அந்தத் தேதிக்கான நாள் காட்சிக்கு அழைத்துச் செல்லும் <em>+N மேலும்</em> இணைப்பையும். இன்று முன்னிலைப்படுத்தப்படும்.',
            'cal_week' => '<strong>வாரக் காட்சி</strong> &mdash; 24-மணி நேர செங்குத்து காலவரிசைக்கு மேலே திங்கள்&ndash;ஞாயிறு. டிக்கெட்டுகள் திட்டமிட்ட நீளத்தில் வரையப்படுகின்றன, எனவே 15 நிமிடப் பணியும் ஒரு மதிய மறுகட்டமைப்பும் வேறுபடத் தெரியும். நாள் முழுவதுமான டிக்கெட் முழு நெடுவரிசையையும் விழுங்காமல் அதன் நாளின் மேலே மெல்லிய பட்டையாக அமரும். இன்றைய நெடுவரிசை முன்னிலைப்படுத்தப்படும்; மணி கட்டம் உருளும்போது வார நாள் தலைப்பு அப்படியே இருக்கும்.',
            'cal_day' => '<strong>நாள் காட்சி</strong> &mdash; தேர்ந்தெடுத்த நாளுக்கான ஒற்றை உயரமான நெடுவரிசை, அதே 24-மணி நேர காலவரிசையுடன். டிக்கெட்டுகள் <code>ticket_number &mdash; subject</code> மற்றும் தொடக்க நேரத்தைக் காட்டும் பெரிய தொகுதிகளாக வரையப்படுகின்றன; அதன் விவரங்களைத் திறக்க அல்லது அது எப்போது நடக்கிறது என்பதை மாற்ற ஒன்றைக் கிளிக் செய்யவும்.',
            'rota_heading' => '<strong>பணியாளர் பணி அட்டவணை</strong>',
            'rota_body' => 'பணி அட்டவணைப் பக்கம் குழுத் தலைவர்களும் மேலாளர்களும் வாரம் முழுவதும் பகுப்பாய்வாளர் ஷிப்டுகளைத் திட்டமிட உதவுகிறது. நிலையான பணி நேரங்களை வரையறுக்கவும், அழைப்புப் பணிக் காலங்களை ஒதுக்கவும், விடுமுறைகள் அல்லது வராமையைக் குறிக்கவும், இதனால் யார் கிடைக்கிறார்கள் என்பது குழுவுக்கு எப்போதும் தெரியும்.',
            'rota_step1' => '<strong>பணி அட்டவணைக் கட்டத்தைப் பாருங்கள்</strong> &mdash; பணி அட்டவணை ஒரு அச்சில் பகுப்பாய்வாளர்களையும் மறு அச்சில் நாட்களையும் காட்டுகிறது, ஷிப்ட் தொகுதிகள் ஒரே பார்வையில் கவரேஜைக் காட்டுகின்றன.',
            'rota_step2' => '<strong>ஷிப்டுகளைச் சேர்க்கவும் அல்லது திருத்தவும்</strong> &mdash; ஷிப்ட் வகையை (எ.கா. காலை, மாலை, இரவு, அழைப்புப் பணி) ஒதுக்க ஒரு கலத்தில் கிளிக் செய்யவும். மாற்றங்கள் உடனடியாகச் சேமிக்கப்படும்.',
            'rota_step3' => '<strong>முன்கூட்டியே திட்டமிடுங்கள்</strong> &mdash; பணி அட்டவணையை முன்கூட்டியே உருவாக்க வாரம் வாரமாக முன்னோக்கிச் செல்லுங்கள். இது அறியப்பட்ட பரபரப்பான காலங்கள், விடுமுறைகள் அல்லது பயிற்சி நாட்களில் போதுமான கவரேஜை உறுதிசெய்கிறது.',
            'rota_step4' => '<strong>பல கலங்களை ஒரே நேரத்தில் நிரப்புங்கள்</strong> &mdash; ஒரு கலத்தில் <strong>வலது-கிளிக்</strong> செய்து அதிலுள்ள ஷிப்டை எடுக்க <em>நகலெடு</em> என்பதைத் தேர்ந்தெடுங்கள், பின்னர் மற்றொன்றில் வலது-கிளிக் செய்து <em>ஒட்டு</em>. ஒன்றுக்கு மேற்பட்ட கலங்களுக்கு, அவற்றின் <strong>தொகுதியின் குறுக்கே இழுக்கவும்</strong> (அல்லது கலங்களை ஒவ்வொன்றாக ctrl-கிளிக் செய்யவும்) அனைத்திலும் ஒட்டவும். <strong>நாள் தலைப்பின்</strong> மேல் வட்டமிட்டால் அந்த முழு நாளும் ஒளிரும், <strong>பகுப்பாய்வாளரின் பெயரின்</strong> மேல் வட்டமிட்டால் அவர்களின் முழு வாரமும் ஒளிரும் &mdash; இரண்டில் எதிலும் வலது-கிளிக் செய்து முழுவதிலும் ஒட்டலாம். சில கலங்களில் ஏற்கனவே ஷிப்ட் இருந்தால், மெனு இரு வழிகளையும் எளிய சொற்களில் வழங்குகிறது &mdash; <em>7 அனைத்திலும் ஒட்டு</em> மற்றும் <em>6 காலி கலங்களில் ஒட்டு</em> &mdash; எனவே உறுதிசெய்த பிறகு அல்ல, முன்பே தேர்வு செய்கிறீர்கள். மேலெழுதுவது உறுதிப்படுத்தலைக் கேட்டு எத்தனை ஷிப்டுகளை மாற்றும் என்று சொல்கிறது; இடைவெளிகளை நிரப்புவது எதுவும் இழக்கப்படாததால் உடனே நடக்கிறது. அதே மெனுக்கள் ஒரு நாள், ஒரு வாரம் அல்லது தேர்வை <strong>அழிக்கவும்</strong> செய்யும், அதுவும் எத்தனை ஷிப்டுகள் நீக்கப்படும் என்று சொன்ன பிறகு.',
            'rota_step5' => '<strong>ஒருவருக்கான முழு நாளையோ முழு வாரத்தையோ நகலெடுங்கள்</strong> &mdash; அந்த நாளின் ஒவ்வொரு ஷிப்டையும் எடுக்க <strong>நாள் தலைப்பில்</strong> வலது-கிளிக் செய்து <em>நகலெடு</em> என்பதைத் தேர்ந்தெடுங்கள், அல்லது அவர்களின் முழு வாரத்தையும் எடுக்க <strong>பகுப்பாய்வாளரின் பெயரில்</strong>. வேறு நாளில் அல்லது வேறு பகுப்பாய்வாளரில் ஒட்டினால் அது பொருந்தும்: நகலில் இல்லாத ஷிப்டுகள் அழிக்கப்படும், எனவே இரண்டின் கலவையல்ல, நீங்கள் நகலெடுத்த நாளே கிடைக்கும். ஒரு நாளை மற்றொரு நாளில் மட்டுமே ஒட்ட முடியும், ஒரு பகுப்பாய்வாளரை மற்றொரு பகுப்பாய்வாளரில் மட்டுமே &mdash; ஒரு நாள் என்பது <em>ஒவ்வொரு நபருக்கும்</em> ஒரு ஷிப்ட், ஒரு வாரம் என்பது <em>ஒவ்வொரு நாளுக்கும்</em> ஒரு ஷிப்ட், எனவே ஒன்றை மற்றொன்றின் மேல் வைக்க பொருத்தமான வழி இல்லை. முயற்சித்தால் மெனு அதைச் சொல்லி, அதற்குப் பதிலாக எங்கே போகலாம் என்றும் சொல்லும்.',
            'rota_step6' => '<strong>முழு வாரத்தையும் நகலெடுங்கள்</strong> &mdash; மேல் வலதுபுறத்திலுள்ள <strong>வாரத்தை நகலெடு</strong> மற்றும் <strong>வாரத்தை ஒட்டு</strong> நீங்கள் பார்க்கும் வாரத்தின் ஒவ்வொரு ஷிப்டையும் எடுத்து மற்றொன்றில் இடுகின்றன, இது மீண்டும் வரும் பணி அட்டவணையை உருவாக்கும் வேகமான வழி. ஒட்டுவது இலக்கு வாரத்தை <em>மாற்றுகிறது</em>, எனவே எத்தனை பதிவுகள் நீக்கப்படப் போகின்றன என்பதை உறுதிப்படுத்தல் சொல்கிறது. கட்டம் உண்மையில் காட்டும் நாட்களையும் நபர்களையும் மட்டுமே அது தொடும்.',
            'tip' => 'திறமையான திறன் திட்டமிடலுக்கு நாட்காட்டியையும் பணி அட்டவணையையும் ஒன்றாகப் பயன்படுத்துங்கள். ஒவ்வொரு திங்கள் காலையும் டிக்கெட்டுகளில் உயர்வை நாட்காட்டி காட்டினால், அந்த நேரத்துக்கு பணி அட்டவணையில் கூடுதல் கவரேஜ் திட்டமிடப்பட்டுள்ளதை உறுதிசெய்யுங்கள்.',
        ],
        'settings' => [
            'heading' => 'அமைப்புகள்',
            'intro' => 'உங்கள் டிக்கெட் அமைப்பின் அடிப்படைக் கூறுகளை அமைப்புகள் பக்கத்தில் உள்ளமைக்கிறீர்கள். அனைத்து தேடல் மதிப்புகள், SLA இலக்குகள், மின்னஞ்சல் ஒருங்கிணைப்பு மற்றும் தனிப்பயன் புலங்கள் இங்கேயே நிர்வகிக்கப்படுகின்றன.',
            'sla_callout_title' => 'SLA மேலாண்மை &mdash; முழு வழிகாட்டி',
            'sla_callout_body' => 'உள்ளமைக்கக்கூடிய விருப்பங்கள், வணிக நாட்காட்டிகள், இடைநிறுத்த நிலைகள், மீறல் அறிவிப்புகள், cron job அமைப்பு, மேலும் ஒரே நேர மண்டலம் மற்றும் பல நேர மண்டலக் குழுக்களுக்கான எடுத்துக்காட்டுகள். தனிப் பக்கத்துக்கு தகுதியான அளவுக்கு விரிவானது.',
            'card_dept_title' => 'துறைகள்',
            'card_dept_body' => 'IT, HR, Finance போன்ற துறைகளை உருவாக்குங்கள். ஒவ்வொரு துறையும் இன்பாக்ஸில் ஒரு கோப்புறையாகவும் டாஷ்போர்டில் ஒரு வடிப்பானாகவும் மாறும்',
            'card_types_title' => 'டிக்கெட் வகைகள்',
            'card_types_body' => 'உங்கள் சேவை மையம் கையாளும் கோரிக்கை வகைகளை வரையறுக்கவும்: Incident, Service Request, Problem, Change. வகைகள் பகுப்பாய்வாளர்கள் வேலையை வகைப்படுத்த உதவுகின்றன',
            'card_priorities_title' => 'முன்னுரிமைகள்',
            'card_priorities_body' => 'பெயர்கள், நிறங்கள், வரிசை எண்களுடன் முன்னுரிமை நிலைகளை அமைக்கவும். ஒவ்வொரு முன்னுரிமையும் பதில் மற்றும் தீர்வுக்கான SLA இலக்குடன் இணைக்கப்பட்டுள்ளது',
            'card_statuses_title' => 'நிலைகள்',
            'card_statuses_body' => 'டிக்கெட் வாழ்க்கைச் சுழற்சிக் கட்டங்களை தனிப்பயனாக்குங்கள். இயல்புநிலை நிலைகள்: புதியது, திறந்தது, செயலில், நிலுவையில், தீர்க்கப்பட்டது, மூடப்பட்டது',
            'card_categories_title' => 'வகைகள்',
            'card_categories_body' => 'டிக்கெட்டுகளை தொழில்நுட்பப் பகுதியின்படி தொகுக்கவும்: Hardware, Software, Network, Access. வகைகள் அறிக்கைப் பிரிவுகளுக்கு அடிப்படையாகின்றன',
            'card_sla_title' => 'SLA இலக்குகள்',
            'card_sla_body' => 'ஒவ்வொரு முன்னுரிமைக்கும் பதில் மற்றும் தீர்வு நேர இலக்குகளை வரையறுக்கவும். SLA டைமர்கள் டிக்கெட்டுகளில் தோன்றி மீறல் எச்சரிக்கைகளை இயக்குகின்றன',
            'card_email_title' => 'மின்னஞ்சல் இறக்குமதி',
            'card_email_body' => 'ஒரு அஞ்சல் பெட்டியை (Exchange, Microsoft 365) இணைத்து மின்னஞ்சல்களை புதிய டிக்கெட்டுகளாக தானாக இறக்குமதி செய்யுங்கள். பதில்கள் ஏற்கனவே உள்ள டிக்கெட்டுகளில் இணைந்துவிடும்',
            'card_custom_title' => 'தனிப்பயன் புலங்கள்',
            'card_custom_body' => 'இயல்புநிலை புலங்களில் இல்லாத, உங்கள் நிறுவனம் பதிவு செய்ய வேண்டிய தரவுக்காக டிக்கெட்டுகளில் உங்கள் சொந்த புலங்களைச் சேர்க்கவும்',
            'card_templates_title' => 'மின்னஞ்சல் வார்ப்புருக்கள்',
            'card_templates_body' => 'டிக்கெட்டுகள் உருவாக்கப்படும்போது, புதுப்பிக்கப்படும்போது, தீர்க்கப்படும்போது அல்லது CSAT கருத்துக்கணிப்புக்காக இறுதிப் பயனர்களுக்கு அனுப்பப்படும் அறிவிப்பு வார்ப்புருக்களை உள்ளமைக்கவும். [requester_name], [csat_link] போன்ற இணைப்புக் குறியீடுகளைச் சேர்க்கலாம்',
            'card_checklists_title' => 'சரிபார்ப்புப் பட்டியல்கள்',
            'card_checklists_body' => 'கட்டாயச் சரிபார்ப்புப் பட்டியல் படிகள் முடிக்கப்படாத டிக்கெட்டை யாராவது மூடும்போது என்ன நடக்க வேண்டும் என்பதைத் தீர்மானியுங்கள்: <strong>எச்சரிக்கை</strong> செய்து, அந்தப் படிகளையும் மூடியவரையும் குறிப்பிடும் உள்குறிப்பைப் பதிவு செய்தல், அல்லது அவை முடியும் வரை மூடுவதைத் <strong>தடுத்தல்</strong>. டிக்கெட்டை மூடக்கூடிய எல்லா இடங்களிலும் செயல்படுத்தப்படும் - மொத்தச் செயல்கள், REST API மற்றும் பணிப்பாய்வு தானியக்கம் உட்பட',
            'card_custom_fields_title' => 'தனிப்பயன் புலங்கள்',
            'card_custom_fields_body' => 'ஒரு வகை டிக்கெட்டுக்குத் தேவையான கூடுதல் விவரங்களை உருவாக்குங்கள் - உரை, எண், தேதி, ஆம் / இல்லை, உங்கள் சொந்த விருப்பங்களுடன் கீழ்விரி, இணைய அல்லது மின்னஞ்சல் முகவரி - ஒவ்வொன்றையும் சில டிக்கெட் வகைகளுடன் அல்லது அனைத்துடனும் இணைக்கவும். ஒவ்வொரு புலமும் <strong>டிக்கெட் பதிவு செய்யப்படும்போது</strong> (புதிய டிக்கெட் படிவம், REST API மற்றும் கேட்டால் போர்டல்), <strong>மூடுவதற்கு முன்</strong> (கட்டாயப் புலங்கள் விதியைப் பின்பற்றி), அல்லது இரண்டிலும் நிரப்பப்பட வேண்டுமா என்பதையும், போர்டலில் <strong>கோரிக்கையாளரிடம் கேட்கப்படுமா</strong> என்பதையும் தேர்வு செய்கிறது - கேட்கப்படுவது மாறும்போது டிக்கெட் வகைத் தேர்வி தோன்றும். பதில்கள் டிக்கெட்டின் பண்புகள் பலகத்திலும் வரலாற்றிலும் காட்டப்படும். டிக்கெட்டின் வகையை மாற்றினால், புதிய வகையில் இல்லாத பதில்கள் மறைக்கப்படும்; ஒருபோதும் நீக்கப்படாது',
            'card_mandatory_title' => 'கட்டாயப் புலங்கள்',
            'card_mandatory_body' => 'டிக்கெட் மூடப்படுவதற்கு முன் நிரப்பப்பட வேண்டிய புலங்களைத் தேர்வு செய்யுங்கள் - வகை, தீர்வுக் குறியீடு, உரிமையாளர் போன்றவை. பிறகு ஒரு புலம் காலியாக இருக்கும்போது யாராவது மூடினால் என்ன நடக்கும் என்பதைத் தேர்வு செய்யுங்கள்: <strong>எச்சரிக்கை</strong>, சேவை வழங்கல் மேலாளர் போன்ற ஒருவருக்கு <strong>எச்சரித்து மின்னஞ்சல்</strong>, அல்லது மூடுவதை <strong>மறுத்தல்</strong>. தனி சுவிட்ச் அதை டிக்கெட்டில் உள்குறிப்பாகப் பதிவு செய்கிறது. ஒரு நிறுவனத்துக்கு அணைக்கப்பட்ட புலம் ஒருபோதும் கட்டாயமில்லை, டிக்கெட்டுகளை ஒன்றிணைப்பது இதைத் தூண்டாது. டிக்கெட்டை மூடக்கூடிய எல்லா இடங்களிலும் செயல்படுத்தப்படும் - மொத்தச் செயல்கள், REST API மற்றும் பணிப்பாய்வு தானியக்கம் உட்பட',
            'card_cleanup_title' => 'பதில் சீரமைப்பு AI',
            'card_cleanup_body' => 'பதில் திருத்தியில் உள்ள ✨ Cleanup பொத்தானுக்கான Anthropic key + மாதிரி + தொனி. நுணுக்கமான கட்டணக் கணக்கீட்டுக்காக மற்ற AI அம்சங்களிலிருந்து தனி key',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'அனுப்பும் முறை (அணைப்பு / தானியங்கி / கைமுறை), தாமதம், ஒரு டிக்கெட்டுக்கு ஒன்று என்ற பாதுகாப்பு, அளவுகோல் (நட்சத்திரங்கள் அல்லது எமோஜிகள்). முழு ஓட்டத்துக்கு பிரிவு 6-ஐப் பாருங்கள்',
            'email_heading' => '<strong>மின்னஞ்சல் இறக்குமதி விரிவாக</strong>',
            'email_body' => 'மின்னஞ்சல் இறக்குமதி அம்சம் உங்கள் பகிரப்பட்ட அஞ்சல் பெட்டியுடன் இணைந்து புதிய செய்திகளை டிக்கெட்டுகளாக எடுத்துக்கொள்கிறது. இறுதிப் பயனர் உங்கள் ஆதரவு முகவரிக்கு (எ.கா. support@yourcompany.com) மின்னஞ்சல் அனுப்பும்போது, FreeITSM மின்னஞ்சலின் பொருளைத் தலைப்பாகவும் மின்னஞ்சலின் உள்ளடக்கத்தை விளக்கமாகவும் கொண்டு டிக்கெட்டை உருவாக்குகிறது. அனுப்புநர் அறிவிப்பு மின்னஞ்சலுக்குப் பதிலளித்தால், நகல் உருவாக்கப்படாமல் அந்தப் பதில் ஏற்கனவே உள்ள டிக்கெட்டில் இணைக்கப்படும்.',
            'email_step1' => '<strong>அஞ்சல் பெட்டியை உள்ளமைக்கவும்</strong> &mdash; அமைப்புகளுக்குச் சென்று உங்கள் Exchange அல்லது Microsoft 365 சான்றுகளை உள்ளிடுங்கள். பாதுகாப்பான, கடவுச்சொல் இல்லாத இணைப்புகளுக்கு OAuth அங்கீகாரம் ஆதரிக்கப்படுகிறது.',
            'email_step2' => '<strong>சரிபார்ப்பு இடைவெளியை அமைக்கவும்</strong> &mdash; புதிய செய்திகளுக்காக FreeITSM அஞ்சல் பெட்டியை எவ்வளவு அடிக்கடி சரிபார்க்கிறது என்பதைத் தேர்வு செய்யுங்கள். குறுகிய இடைவெளிகள் என்றால் வேகமாக டிக்கெட் உருவாக்கம்.',
            'email_step3' => '<strong>இயல்புநிலைகளை வரையறுக்கவும்</strong> &mdash; மின்னஞ்சலிலிருந்து உருவாகும் டிக்கெட்டுகளுக்கான இயல்புநிலைத் துறை, வகை மற்றும் முன்னுரிமையை அமைக்கவும். பகுப்பாய்வாளர்கள் இறக்குமதிக்குப் பின் இவற்றை மாற்றலாம்.',
            'tip' => 'எல்லா இறுதிப் பயனர் தொடர்புகளிலும் தொழில்முறையான, சீரான தொனியைப் பராமரிக்க மின்னஞ்சல் வார்ப்புருக்களைப் பயன்படுத்துங்கள். டிக்கெட் குறிப்பு, கோரிக்கையாளர் பெயர், பகுப்பாய்வாளர் பெயர் மற்றும் நிலைக்கான மாறும் இடக்குறிகளை வார்ப்புருக்கள் ஆதரிக்கின்றன.',
            'closemsg_heading' => '<strong>டிக்கெட்டை மூடும்போது ஒருமுறை செய்தி</strong>',
            'closemsg_body' => '<code>[ticket_closed_message]</code> என்பதை செயலில் உள்ள <strong>டிக்கெட் மூடப்பட்டது</strong> வார்ப்புருவில் எங்காவது வையுங்கள்; அதன்பின் டிக்கெட்டை மூடப்பட்ட நிலைக்கு அமைக்கும்போது பகுப்பாய்வாளரிடம் ஒரு வாக்கியம் கேட்கப்படும் - <em>&ldquo;உதிரி சார்ஜர் உங்கள் மேசையில் உள்ளது&rdquo;</em>, <em>&ldquo;தொலைபேசியில் ஒப்புக்கொண்டபடி மூடப்படுகிறது&rdquo;</em>. அவர்கள் தட்டச்சு செய்வது நீங்கள் இடக்குறியை வைத்த இடத்திலேயே சேரும், எனவே சுற்றியுள்ள சொற்களின் கட்டுப்பாடு உங்களிடமே இருக்கும். இது அமைப்பு அல்ல, எதுவும் இதைச் சேமிப்பதில்லை: ஒரு குறிப்பு, ஒரு டிக்கெட், ஒரு மின்னஞ்சல். எதுவும் தட்டச்சு செய்யாவிட்டால் அந்த வரி இருக்காது - இடைவெளியும் இல்லை, தேவையற்ற நிறுத்தற்குறியும் இல்லை.',
            'closemsg_note' => '<strong>வார்ப்புருவில் இடக்குறி உண்மையில் இருக்கும்போது மட்டுமே கேள்வி தோன்றும்.</strong> இல்லாவிட்டால் பகுப்பாய்வாளர் தட்டச்சு செய்தது அமைதியாக வீணாகும், இது தேவையில்லாத சேவை மையங்களுக்கு ஒவ்வொரு மூடலிலும் கூடுதல் கிளிக் ஆகும். எனவே நீங்கள் உள்ளமைக்கும்போது தானாக இயங்கும், உள்ளமைக்காதபோது குறுக்கிடாது.',
            'cat_heading' => '<strong>வகைகளும், அவற்றின் அருகிலுள்ள இரு புலங்களும்</strong>',
            'cat_body' => 'டிக்கெட் <em>வகை</em> இது என்ன மாதிரியான விஷயம் என்பதைச் சொல்கிறது; <em>வகைப்பாடு</em> இது எதைப் பற்றியது என்பதைச் சொல்கிறது. இவற்றில் எதாவது டிக்கெட்டில் தோன்ற வேண்டுமா என்பதைத் தீர்மானிக்கும் சுவிட்சுகளுடன் சேர்த்து, பட்டியலை <strong>அமைப்புகள் &rarr; வகைகள்</strong> என்பதில் உருவாக்குங்கள்.',
            'cat_card_one_title' => 'வகை',
            'cat_card_one_body' => 'டிக்கெட் எவ்வாறு புகாரளிக்கப்பட்டது என்பது, அது எழுப்பப்படும்போது தேர்வு செய்யப்படுகிறது. ஒரு டிக்கெட்டுக்கு சரியாக ஒன்று இருக்கும், எனவே உங்கள் வகைகளின் அறிக்கை எப்போதும் உங்களுக்கு இருந்த டிக்கெட்டுகளின் எண்ணிக்கையுடன் பொருந்தும்.',
            'cat_card_close_title' => 'மூடும்போதைய வகை',
            'cat_card_close_body' => 'டிக்கெட் முடியும்போது மீண்டும் கேட்கப்படும் அதே பட்டியல். பொதுவாக பகுப்பாய்வாளர் அதை உறுதிப்படுத்துவார் &mdash; முதல் ஊகம் தவறாக இருந்த டிக்கெட்டுகளில்தான் இது பயன் தருகிறது; உங்கள் முப்பத்தேழு "பிரிண்டர் பிரச்சனைகளில்" பன்னிரண்டு உண்மையில் நெட்வொர்க் பிரச்சனை என்பதை இப்படித்தான் கண்டுபிடிப்பீர்கள்.',
            'cat_card_res_title' => 'தீர்வுக் குறியீடு',
            'cat_card_res_body' => 'டிக்கெட் எதைப் பற்றியது என்பதை அல்ல, அது எப்படி முடிந்தது என்பதை &mdash; "தொலைவிலிருந்து சரிசெய்யப்பட்டது", "பயிற்சி வழங்கப்பட்டது", "பிழை எதுவும் இல்லை". பத்து பொருத்தமானவை தொடக்கத்திலேயே உள்ளன, அவை அனைத்தையும் மாற்றலாம்.',
            'cat_rule_off' => '<strong>மூன்றும் அணைக்கப்பட்டே தொடங்கும்.</strong> முதலில் உங்கள் பட்டியலை உருவாக்குங்கள், பிறகு தேவையானவற்றை இயக்குங்கள். ஒவ்வொன்றையும் ஒவ்வொரு நிறுவனத்துக்கும் வேறுபடுத்தி அமைக்கலாம்.',
            'cat_rule_levels' => 'வகைகளுக்கு மூன்று நிலைகள் வரை துணை வகைகள் இருக்கலாம், எந்த நிலையும் கட்டாயமில்லை.',
            'cat_rule_type' => 'ஒரு வகையை ஒரு டிக்கெட் வகையுடன் இணைக்கலாம், எனவே "பயனர் சேர்க்கை" என்பது சேவைக் கோரிக்கையில் மட்டுமே வழங்கப்படும். இணைப்பு உயர்நிலை வகைக்குரியது, அதன் துணை வகைகள் அதைப் பின்பற்றும்.',
            'cat_rule_typechange' => '<strong>டிக்கெட்டின் வகையை மாற்றினால் பழைய வகைக்குரிய வகைப்பாடு அழிக்கப்படும்</strong>, அது திரையிலும் சொல்லப்படும். எந்த வகையுடனும் இணைக்கப்படாத வகைப்பாடு மாற்றத்திலும் நீடிக்கும்.',
            'cat_rule_portal' => 'சுய-சேவை போர்டலில் ஒரு வகையை வழங்க <em>வாடிக்கையாளர்கள் இதைத் தேர்வு செய்யலாம்</em> என்பதைத் தேர்வு செய்யுங்கள். கோரிக்கையாளர்கள் எளிய மொழியில் சிறு பட்டியலைக் காண்பார்கள், பகுப்பாய்வாளர்கள் முழு மரத்தையும் காண்பார்கள்.',
            'cat_rule_retire' => 'ஒரு வகையை ஓய்வு பெறச் செய்ய அதை அணைக்கவும் &mdash; அது ஏற்கனவே உள்ள டிக்கெட்டுகளில் தொடரும், புதியவற்றில் வழங்கப்படாது. எதாவது இன்னும் பயன்படுத்தும் வரை மறுக்கப்படும் நீக்குதலை விட இது கிட்டத்தட்ட எப்போதும் சிறந்தது.',
            'cat_rule_report' => 'மூன்றையும் டிக்கெட் டாஷ்போர்டில் வரைபடமாக்கலாம். இரண்டு வகை வரைபடங்களும் உயர்நிலைக்குத் திரட்டப்படும், எதுவும் அமைக்கப்படாத டிக்கெட்டுகள் மறைக்கப்படாமல் <em>வகைப்படுத்தப்படவில்லை</em> எனக் கணக்கிடப்படும்.',
            'cat_tip' => 'எங்கே தொடங்குவது எனத் தெரியவில்லை என்றால், வகைகளை காலியாக விட்டு <strong>தீர்வுக் குறியீடு</strong> மட்டும் இயக்குங்கள். நீங்கள் செய்வதை மிக விரைவாக மாற்றும் புலம் அதுவே &mdash; உங்கள் டிக்கெட்டுகளில் ஐந்தில் ஒன்று "பயிற்சி வழங்கப்பட்டது" என வருவது IT பிரச்சனை அல்ல, ஆவணப்படுத்தல் பிரச்சனை.',
        ],
        'tips' => [
            'heading' => 'விரைவு குறிப்புகள்',
            'search_title' => 'அனைத்தையும் தேடுங்கள்',
            'search_body' => 'தேடல் சாளரம் டிக்கெட் குறிப்புகள், பொருள்கள், கோரிக்கையாளர் பெயர்கள் மற்றும் மின்னஞ்சல் முகவரிகளைச் சரிபார்க்கிறது. ஏற்கனவே உள்ள பிரச்சனை குறித்து பயனர் அழைக்கும்போது தொடர்புடைய டிக்கெட்டுகளை விரைவாகக் கண்டறிய இதைப் பயன்படுத்துங்கள்.',
            'sla_title' => 'உங்கள் SLA-களைக் கவனியுங்கள்',
            'sla_body' => 'SLA டைமர்கள் வாசிப்புப் பலகத்தில் ஒவ்வொரு டிக்கெட்டிலும் தெரியும். மீறல் நெருங்கும்போது நிறக் குறியீட்டு அடையாளங்கள் அம்பராகவும், இலக்கு தவறவிடப்பட்டால் சிவப்பாகவும் மாறும், எனவே அதற்கேற்ப முன்னுரிமை அளிக்கலாம்.',
            'reply_title' => 'இன்பாக்ஸிலிருந்தே பதிலளியுங்கள்',
            'reply_body' => 'இறுதிப் பயனருக்குப் பதிலளிக்க உங்கள் மின்னஞ்சல் கிளையண்டைத் திறக்கத் தேவையில்லை. வாசிப்புப் பலகத்தில் உள்ள பதில் பொத்தானைப் பயன்படுத்தி நேரடியாகச் செய்தி அனுப்புங்கள். அது தானாகவே டிக்கெட்டில் இணையும்.',
            'trail_title' => 'செயல்பாட்டுத் தடத்தைப் பயன்படுத்துங்கள்',
            'trail_body' => 'ஒரு டிக்கெட்டில் வேலை செய்யும் முன், அதன் செயல்பாட்டுத் தடத்தை உருட்டிப் பாருங்கள். முந்தைய பகுப்பாய்வாளர் குறிப்புகள், மின்னஞ்சல்கள் மற்றும் புல மாற்றங்கள் முழுச் சூழலையும் தரும், எனவே தகவலை மீண்டும் சொல்லுமாறு பயனரிடம் கேட்க வேண்டியதில்லை.',
            'dash_title' => 'மேலாளர்களுக்கான டாஷ்போர்டு',
            'dash_body' => 'SLA இணக்க விகிதங்கள், சராசரி தீர்வு நேரம் மற்றும் துறைவாரி டிக்கெட்டுகளுக்கான விட்ஜெட்டுகளுடன் ஒரு டாஷ்போர்டை உருவாக்குங்கள். தொடர்ச்சியான மேம்பாட்டை முன்னெடுக்க குழுக் கூட்டங்களில் அதைப் பகிருங்கள்.',
            'rota_title' => 'பணி அட்டவணையுடன் திட்டமிடுங்கள்',
            'rota_body' => 'பணி அட்டவணையை குறைந்தது இரண்டு வாரங்களுக்கு முன்பே நிரப்புங்கள். நாட்காட்டிக் காட்சியுடன் இணைக்கும்போது, பதில் நேரங்களுக்குச் சிக்கலாகும் முன் பணியாளர் இடைவெளிகளைக் கண்டறிய உதவுகிறது.',
            'drag_title' => 'இழுத்துத் தரம் பிரியுங்கள்',
            'drag_body' => 'டிக்கெட்டுகளைத் திறக்காமலேயே புதுப்பிக்க, பட்டியலிலிருந்து கோப்புறைகளின் மீது இழுக்கவும். துறை + நிலை துணைக் கோப்புறைகள் இரண்டையும் ஒரே நேரத்தில் புதுப்பிக்கும். இழுக்கும்போதே தானாக விரியும் வசதி உள்ளமைந்த நிலைகளை எட்டச் செய்கிறது.',
            'dbl_title' => 'முழுத்திரைக்கு இருமுறை கிளிக் செய்யுங்கள்',
            'dbl_body' => 'ஒரு கிளிக் டிக்கெட்டை வாசிப்புப் பலகத்தில் முன்னோட்டம் காட்டும்; இருமுறை கிளிக் கவனம் செலுத்தி வேலை செய்ய அதை முழுத்திரை முறையில் திறக்கும். மீண்டும் மாற, பொருளுக்கு அருகிலுள்ள பெரிதாக்கு ஐகானைக் கிளிக் செய்யுங்கள்.',
            'rightclick_title' => 'விரைவுச் செயல்களுக்கு வலது-கிளிக்',
            'rightclick_body' => 'எந்த டிக்கெட்டிலும் வலது-கிளிக் செய்தால் ஒரே கிளிக்கில் நிலை, முன்னுரிமை அல்லது ஒதுக்கப்பட்டவரை மாற்றலாம், மேலும் CMDB இணைப்பு மற்றும் நேரப் பதிவும் செய்யலாம் - நீங்கள் இப்போது படிக்கும் டிக்கெட்டை விட்டு விலகாமலேயே.',
            'ai_title' => 'AI உங்கள் பதிலைச் சீரமைக்கட்டும்',
            'ai_body' => 'ஒரு கரடுமுரடான வரைவை (அல்லது வெறும் புள்ளிகளை) தட்டச்சு செய்து <strong>✨ Cleanup</strong> என்பதைக் கிளிக் செய்யுங்கள் &mdash; வாழ்த்து, இலக்கணத் திருத்தம், முடிப்புடன் முறையான மின்னஞ்சலாக Claude மீண்டும் எழுதும். செயல்தவிர் இணைப்பு 30 விநாடிகள் தோன்றும்.',
            'feedback_title' => 'கருத்துக் கேளுங்கள்',
            'feedback_body' => 'டிக்கெட்டுகள் மூடப்படும்போது கோரிக்கையாளர்களுக்குத் தானாகக் கருத்துக்கணிப்பு அனுப்ப <strong>அமைப்புகள் &rarr; CSAT</strong> என்பதில் CSAT-ஐ இயக்குங்கள். ஒவ்வொரு பகுப்பாய்வாளரின் போக்குகளும் <code>tickets/csat/</code> என்பதில் உள்ளன &mdash; மேம்பாட்டு உரையாடல்களுக்கு தங்கம்.',
            'precreate_title' => 'இறுதிப் பயனர்களை முன்கூட்டியே உருவாக்குங்கள்',
            'precreate_body' => '<strong>பயனர்கள்</strong> வழிசெலுத்தல் பொத்தான், ஒருவர் டிக்கெட் பதிவு செய்யத் தேவைப்படும் முன்பே அவரைச் சேர்க்க உதவுகிறது &mdash; கடவுச்சொல்லை காலியாக விடுங்கள், அவர்கள் சுய-சேவை போர்டல் வழியாகத் தாங்களே கணக்கைக் கோரலாம்.',
        ],
        'companies' => [
            'heading' => 'நிறுவனங்கள் &amp; மின்னஞ்சல் வழித்தடம்',
            'intro' => 'உங்கள் நிறுவலில் ஒன்றுக்கும் மேற்பட்ட நிறுவனங்கள் இருக்கும்போது (எடுத்துக்காட்டாக, பல வாடிக்கையாளர்களுக்கு ஆதரவளிக்கும் IT வழங்குநர்), ஒவ்வொரு நிறுவனத்தின் டிக்கெட்டுகளும் தனித்தனியாக வைக்கப்படும். உள்வரும் மின்னஞ்சல் சரியான நிறுவனத்தை எவ்வாறு கண்டறிகிறது என்பதை இந்தப் பிரிவு விளக்குகிறது.',
            'switcher_body' => 'தலைப்பில் ஒரு <strong>நிறுவன மாற்றி</strong> தோன்றும். நீங்கள் பணிபுரியும் நிறுவனத்தை அது அமைக்கிறது &mdash; டிக்கெட் பட்டியல், கோப்புறைகள், எண்ணிக்கைகள் அனைத்தும் அந்த நிறுவனத்தை மட்டுமே காட்டும், நீங்கள் உருவாக்கும் ஒவ்வொரு டிக்கெட்டும் அதற்கே பதிவாகும். பல நிறுவனங்களுக்கு அணுகல் உள்ள பணியாளர்கள் அவற்றுக்கிடையே மாறலாம்; தவறான சூழலில் பதிலளிக்காமல் இருக்க தற்போதைய நிறுவனம் எப்போதும் காட்டப்படும். நிறுவனங்களை <strong>கணினி &rarr; நிறுவனங்கள்</strong> என்பதன் கீழ் நிர்வகிக்கலாம்.',
            'mailboxes_heading' => 'ஒவ்வொரு அஞ்சல் பெட்டியும் இரண்டு வகைகளில் ஒன்று &mdash; வழித்தடத்தை முடிவு செய்வது இதுவே:',
            'card_pinned_title' => 'பிணைக்கப்பட்ட அஞ்சல் பெட்டி',
            'card_pinned_body' => 'ஒரே நிறுவனத்துக்கு உரியது (எ.கா. வாடிக்கையாளரின் சொந்த <code>itsupport@</code>). அதன் <strong>அனைத்து</strong> அஞ்சலும் அந்த நிறுவனத்துக்கே பதிவாகும் &mdash; அனுப்புநர் கவனிக்கப்படுவதில்லை &mdash; பதில்களும் அதிலிருந்தே வெளியே செல்லும், எனவே வாடிக்கையாளர் தங்கள் சொந்த உதவி மையத்தையே முழுவதும் காண்பார்.',
            'card_shared_title' => 'பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி',
            'card_shared_body' => 'பல நிறுவனங்களுக்குச் சேவை செய்யும் ஒரே முகவரி (எ.கா. வழங்குநரின் ஒற்றை <code>support@theprovider.com</code>). முகவரியை வைத்து மட்டும் நிறுவனத்தை அறிய முடியாது, எனவே <strong>மின்னஞ்சலை அனுப்பியவர் யார்</strong> என்பதிலிருந்து அதைக் கண்டறிகிறது. பல வாடிக்கையாளர்களைக் கொண்ட வழங்குநருக்கு பரிந்துரைக்கப்படும் அமைப்பு இது.',
            'routing_heading' => 'பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி நிறுவனத்தை எவ்வாறு தேர்ந்தெடுக்கிறது',
            'routing_body' => 'ஒவ்வொரு உள்வரும் மின்னஞ்சலுக்கும் இவற்றை வரிசையாக முயல்கிறது, முதலில் பொருந்துவதே வெற்றி பெறும்:',
            'flow_reply' => 'டிக்கெட்டுக்கு பதில்',
            'flow_sender' => 'தெரிந்த அனுப்புநர்',
            'flow_domain' => 'தெரிந்த டொமைன்',
            'flow_triage' => 'டிரையேஜ்',
            'rule_reply' => '<strong>1. ஏற்கனவே உள்ள டிக்கெட்டுக்கு பதில்</strong> &mdash; அதன் குறிப்பெண்ணால் அடையாளம் காணப்பட்டு, மின்னஞ்சல் அந்த டிக்கெட்டில் இணைந்து அதன் நிறுவனத்தையே தக்கவைக்கும்.',
            'rule_sender' => '<strong>2. குறிப்பிட்ட அனுப்புநர் முகவரி</strong> ஒரு நிறுவனத்துடன் இணைக்கப்பட்டிருந்தால் (எ.கா. <code>jane@gmail.com</code> &rarr; Acme) &mdash; அந்த நிறுவனம். டொமைனுக்கு முன்பே சரிபார்க்கப்படுவதால், தனிப்பட்ட/வெப்மெயில் முகவரிகளுக்கும் இது செயல்படும்.',
            'rule_domain' => '<strong>3. அனுப்புநரின் டொமைன்</strong> ஒரு நிறுவனத்துடன் இணைக்கப்பட்டிருந்தால் (எ.கா. <code>@acme.com</code> இல் உள்ள யாரும் &rarr; Acme) &mdash; அந்த நிறுவனம்.',
            'rule_triage' => '<strong>4. பொருத்தம் இல்லை</strong> &mdash; மின்னஞ்சல் இழக்கப்படாமல் <strong>டிரையேஜ்</strong> வரிசைக்குச் செல்லும் (கீழே காண்க).',
            'keys_heading' => 'டொமைன்கள் &amp; குறிப்பிட்ட அனுப்புநர்கள் (கணினி &rarr; நிறுவனங்கள் என்பதன் கீழ் ஒவ்வொரு நிறுவனத்துக்கும் அமைக்கப்படும்)',
            'keys_body' => 'பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி பொருத்திப் பார்க்கும் விசைகள் இவை. ஒவ்வொரு நிறுவனமும் தனக்குச் சொந்தமான மின்னஞ்சல் டொமைன்களையும், விருப்பமிருந்தால் தனிப்பட்ட அனுப்புநர் முகவரிகளையும் பட்டியலிடுகிறது.',
            'card_domains_title' => 'மின்னஞ்சல் டொமைன்கள்',
            'card_domains_body' => 'ஒரு நிறுவனத்துக்குச் சொந்தமான டொமைன்கள் (acme.com, acme.co.uk). பதிவு செய்யப்பட்ட டொமைனில் உள்ள எந்த அனுப்புநரும் அந்த நிறுவனத்துக்கு வழிப்படுத்தப்படுவார். ஒரு டொமைன் ஒரே நிறுவனத்துக்கு மட்டுமே சொந்தம்.',
            'card_senders_title' => 'குறிப்பிட்ட அனுப்புநர்கள்',
            'card_senders_body' => 'ஒரு நிறுவனத்துடன் இணைக்கப்பட்ட தனிப்பட்ட முகவரிகள், டொமைனுக்கு முன்பே சரிபார்க்கப்படும். தனிப்பட்ட முகவரியிலிருந்து மின்னஞ்சல் அனுப்பும் ஃப்ரீலான்சர் அல்லது சிறிய வாடிக்கையாளருக்கு இதைப் பயன்படுத்தவும்.',
            'card_public_title' => 'பொது வழங்குநர்கள்',
            'card_public_body' => 'Gmail, Outlook, Yahoo போன்றவற்றை டொமைனாக இணைக்க முடியாது (தொடர்பில்லாத பலர் அவற்றைப் பகிர்கிறார்கள்) &mdash; அதற்குப் பதிலாக சரியான முகவரியையே குறிப்பிட்ட அனுப்புநராக இணைக்கவும்.',
            'triage_heading' => 'டிரையேஜ் வரிசை &mdash; பாதுகாப்பு வலை',
            'triage_body' => 'பகிரப்பட்ட உள்வரவு மின்னஞ்சல் எந்த நிறுவனத்துடனும் பொருந்தாதபோது, அது இழக்கப்படாமல் <strong>டிரையேஜ்</strong> பகுதிக்கு வரும் (நிறுவன மாற்றியிலிருந்து, நேரலை எண்ணிக்கையுடன் அணுகலாம்). ஒவ்வொரு உருப்படியும் அனுப்புநர், டொமைன், பொருள் மற்றும் எந்த அஞ்சல் பெட்டிக்கு வந்தது என்பதைக் காட்டும். ஒரே படியில் அதை ஒரு நிறுவனத்துக்குப் பதிவு செய்யலாம்:',
            'triage_create' => 'ஏற்கனவே உள்ள நிறுவனத்தைத் தேர்ந்தெடுக்கவும், அல்லது அங்கேயே புதியதை உருவாக்கவும்.',
            'triage_assign' => 'சாதாரண டொமைனுக்கு, விருப்பப்பட்டால் <strong>அந்த டொமைனை வழிப்படுத்தவும்</strong>; பொது/வெப்மெயில் முகவரிக்கு, விருப்பப்பட்டால் <strong>அந்த அனுப்புநரை எப்போதும் பதிவு செய்யவும்</strong>.',
            'triage_sweep' => 'எந்தத் தேர்வும் <em>துடைத்துவிடும்</em>: அந்த டொமைன் அல்லது முகவரியிலிருந்து வரிசையில் உள்ள மற்ற எல்லா மின்னஞ்சல்களையும் நகர்த்தி, எதிர்கால அஞ்சலைத் தானாக வழிப்படுத்தும் &mdash; எனவே ஒரு அனுப்புநரை ஒருமுறை மட்டுமே வரிசைப்படுத்தினால் போதும்.',
            'triage_tip' => 'எதுவும் இழக்கப்படுவதில்லை. பொருந்தாத அஞ்சல் யாராவது பதிவு செய்யும் வரை டிரையேஜில் காத்திருக்கும்; பதிவு செய்யப்படாத டிக்கெட் அதுவரை இயல்புநிலை நிறுவனத்தின் கீழ் தொடர்ந்து காட்டப்படும்.',
            'test_heading' => 'நேரலைக்கு முன் உங்கள் வழித்தடத்தைச் சோதிக்கவும்',
            'test_body' => '<strong>கணினி &rarr; மின்னஞ்சல் வழித்தடச் சோதனை</strong> என்பதன் கீழ் ஒரு மின்னஞ்சல் வந்தது போல் பாவனை செய்யலாம் &mdash; ஒரு அஞ்சல் பெட்டியைத் தேர்ந்தெடுத்து, அனுப்புநர் முகவரியை உள்ளிடுங்கள் &mdash; புதிய டிக்கெட் எந்த நிறுவனத்துக்குச் செல்லும் (அல்லது டிரையேஜுக்குச் செல்லும்) என்பதையும் எந்த விதி அதை முடிவு செய்தது என்பதையும் சரியாகக் காணலாம். இது எதையும் உருவாக்காது; உங்கள் அமைப்புகளை மட்டுமே படிக்கிறது.',
            'settings_heading' => 'அமைப்புகள்: இயல்பாகப் பகிரப்பட்டவை, தேவையான இடத்தில் தனிப்பயனாக்கப்பட்டவை',
            'settings_body' => 'இந்த அமைப்புகளில் சில <strong>நிறுவனத்துக்கு ஏற்ப தனிப்பயனாக்கப்படலாம்</strong>; மற்றவை வேண்டுமென்றே பகிரப்பட்டே இருக்கும். <strong>டிக்கெட் வகைகள்</strong> மற்றும் <strong>மூலங்கள்</strong> போன்ற எளிய விருப்பப் பட்டியலான அமைப்பில், ஒரு நிறுவனத்தின் சூழலுக்கு மாறினால் பகிரப்பட்ட இயல்புநிலைகளை (பயன்படுத்தாதவற்றை மறைக்க ஒவ்வொன்றுக்கும் கண் ஐகானுடன்) மற்றும் அந்த நிறுவனம் தனக்காகச் சேர்த்தவற்றையும் காண்பீர்கள். திறந்த டிக்கெட்டுகள் இன்னும் பயன்படுத்தும் விருப்பத்தை மறைக்கவோ நீக்கவோ முடியாது, பகிரப்பட்ட இயல்புநிலைகளை MSP / இயல்புநிலை நிறுவனத்திலிருந்தே திருத்த வேண்டும்.',
            'settings_custom_title' => 'நிறுவனத்துக்கு ஏற்ப தனிப்பயனாக்கப்பட்டவை',
            'settings_custom_body' => 'டிக்கெட் வகைகள் &amp; மூலங்கள் (இப்போது), மற்றும் வகைகள், SLA-கள் &amp; வணிக நேரங்கள் (விரைவில்) &mdash; ஒரு வாடிக்கையாளரிடமிருந்து மற்றொருவருக்கு உண்மையிலேயே வேறுபடும் விஷயங்கள்.',
            'settings_global_title' => 'ஒவ்வொரு நிறுவனத்துக்கும் பகிரப்பட்டவை',
            'settings_global_body' => 'நிலைகளும் முன்னுரிமைகளும் எல்லா இடங்களிலும் ஒரே மாதிரி இருக்கும், எனவே நிறுவனங்களுக்கிடையேயான அறிக்கையிடலும் SLA-களும் சீராக இருக்கும்; உங்கள் குழுக்கள், பணி அட்டவணை மற்றும் அஞ்சல் பெட்டிகளும் அப்படியே &mdash; அவை உங்கள் சொந்த செயல்பாடு, வாடிக்கையாளருடையவை அல்ல.',
            'allview_heading' => '<strong>எல்லா நிறுவனங்களுக்கும் ஒரே பலகை</strong>',
            'allview_body' => 'தலைப்பில் உள்ள நிறுவன மாற்றியில் <strong>அனைத்து நிறுவனங்கள்</strong> என்ற விருப்பம் உள்ளது. நீங்கள் பார்க்க அனுமதிக்கப்பட்ட ஒவ்வொரு டிக்கெட்டும் ஒரே பட்டியலில் தோன்றும், ஒவ்வொரு வரிசையிலும் அது சேர்ந்த நிறுவனம் காட்டப்படும் &mdash; பல நிறுவனங்களுக்கு ஆதரவளித்து, எது யாருடையது என்பதைத் தவறவிடாமல் அன்றைய நாளை ஒரே பார்வையில் காண விரும்பும்போது பயனுள்ளது.',
            'allview_card_scope_title' => 'இது புதிய அணுகலை வழங்காது',
            'allview_card_scope_body' => '"அனைத்தும்" என்பது நீங்கள் ஏற்கனவே ஒவ்வொன்றாக அணுகக்கூடிய எல்லா நிறுவனங்களையும் குறிக்கும். உங்கள் மூன்று நிறுவனங்களில் இரண்டுக்கு ஆதரவளிக்கும் பகுப்பாய்வாளர் சரியாக அந்த இரண்டையே காண்பார்; ஒரு நிறுவனம் உள்ள பகுப்பாய்வாளர் அந்த ஒரு நிறுவனத்தின் காட்சியைக் காண்பார்.',
            'allview_card_props_title' => 'ஒவ்வொரு நிறுவனமும் தனித்தே இருக்கும்',
            'allview_card_props_body' => 'ஒரு டிக்கெட்டைத் திறந்தால் அதன் வகை, மூலம், வகைப்பாடு மற்றும் தீர்வுப் பட்டியல் <em>அந்த</em> நிறுவனத்துக்கு உரியவையாக இருக்கும் &mdash; எனவே ஒரு நிறுவனத்தில் இருக்கும், மற்றொன்றில் இல்லாத வகைப்பாடு தவறான டிக்கெட்டில் ஒருபோதும் பயன்படுத்தப்படாது.',
            'allview_card_new_title' => 'புதிய டிக்கெட்டுகள் எந்த நிறுவனம் என்று கேட்கும்',
            'allview_card_new_body' => 'எடுத்துக்கொள்ள ஒரே செயலில் உள்ள நிறுவனம் இல்லை, மேலும் இந்தத் தேர்வே டிக்கெட் எண், பதில்கள் வரும் அஞ்சல் பெட்டி மற்றும் பொருந்தும் SLA ஆகியவற்றை முடிவு செய்கிறது. நீங்கள் தேர்ந்தெடுத்த பிறகே வகைப் பட்டியல் நிரம்பும்.',
            'allview_rule_chip' => 'மின்னஞ்சல் அல்லது போர்டல் வழியாக வந்து இன்னும் வழிப்படுத்தப்படாத டிக்கெட் இயல்புநிலை என்பதன் கீழ் காட்டப்படாமல் <strong>வழிப்படுத்தப்படாதது</strong> எனக் குறிக்கப்படும், எனவே டிரையேஜுக்காக தனித்து நிற்கும்.',
            'allview_rule_reply' => 'பதில்கள் இன்னும் டிக்கெட் வந்த அஞ்சல் பெட்டியிலிருந்தே வெளியே செல்லும் &mdash; அது காட்சியை அல்ல, டிக்கெட்டைப் பின்பற்றுகிறது, எனவே ஒருங்கிணைந்த பலகை தவறான முகவரியிலிருந்து அனுப்ப முடியாது.',
            'allview_rule_knowledge' => 'ஒருங்கிணைந்த காட்சி இயக்கத்தில் இருக்கும்போது <strong>AI-ஐ கேளுங்கள்</strong> ஒரு நிறுவனத்தை மட்டும் அல்லாமல், நீங்கள் காணக்கூடிய ஒவ்வொரு நிறுவனத்தையும் தேடும். எல்லா நிறுவனங்களுடனும் பகிரப்பட்ட கட்டுரைகள் இரண்டிலும் சேர்க்கப்படும்.',
            'allview_rule_trash' => '<strong>குப்பையைக் காலி செய்வது ஒருபோதும் நிறுவனங்களைக் கடந்து செல்லாது.</strong> நீங்கள் கடைசியாகத் தேர்ந்தெடுத்த ஒரே நிறுவனத்துக்கே எப்போதும் பொருந்தும், ஏனெனில் பல நிறுவனங்களில் "தொட்டியில் உள்ள எல்லாவற்றையும் நீக்கு" என்பதை ஒரே நேரத்தில் செய்வது யாரும் விரும்புவதல்ல.',
            'allview_rule_other' => 'டிக்கெட் பட்டியல் மட்டுமே விரிவடையும். சொத்துகள், மாற்றங்கள், பணிகள் மற்றும் CMDB இன்னும் ஒரு நேரத்தில் ஒரு நிறுவனத்தையே காட்டும் &mdash; அவற்றில் பணிபுரிய அந்த நிறுவனத்துக்கு மாறவும்.',
            'privacy_heading' => 'ஒவ்வொரு நிறுவனத்தின் டிக்கெட்டுகளும் தனிப்பட்டவை',
            'privacy_body' => 'ஒரு நிறுவனத்தின் சூழலில் பணிபுரியும்போது <strong>அந்த</strong> நிறுவனத்தின் டிக்கெட்டுகளை மட்டுமே காண்பீர்கள் &mdash; பட்டியலில், தேடலில், டாஷ்போர்டுகளில், நீங்கள் திறக்கும் ஒவ்வொரு டிக்கெட்டிலும் (அதன் மின்னஞ்சல்கள், இணைப்புகள், குறிப்புகள் மற்றும் வரலாறு உட்பட). ஒரு பணியாளருக்கு டிக்கெட்டின் நிறுவனத்துக்கு அணுகல் வழங்கப்பட்டிருந்தால் மட்டுமே அதை அடைய முடியும் (ஒவ்வொரு பகுப்பாய்வாளரின் நிறுவனங்களையும் கணினி &rarr; பகுப்பாய்வாளர்கள் என்பதன் கீழ் தேர்ந்தெடுக்கலாம், அல்லது முழு குழுவுக்கும் கணினி &rarr; குழுக்கள் என்பதில் வழங்கலாம்), எனவே மற்றொரு வாடிக்கையாளரின் தரவுக்குள் தவறி நுழைய வழியில்லை. இந்தப் பிரிப்பு பார்வையிலிருந்து மறைக்கப்படுவதோடு மட்டுமல்லாமல், திரைக்குப் பின்னாலும் எல்லா இடங்களிலும் அமல்படுத்தப்படுகிறது. ஒற்றை-நிறுவன நிறுவலில் இது தானியங்கியானது, கண்ணுக்குத் தெரியாதது &mdash; ஒரே ஒரு நிறுவனம் மட்டுமே இருப்பதால், எல்லாமே அதற்கே சொந்தம்.',
            'tip' => 'ஒற்றை-நிறுவன நிறுவலில் இவற்றில் எதுவும் தோன்றாது &mdash; ஒரே ஒரு நிறுவனம், ஒவ்வொரு டிக்கெட்டும் அதற்கே சொந்தம், மாற்றியோ டிரையேஜோ இருக்காது. இரண்டாவது நிறுவனம் உருவாக்கப்பட்ட பிறகே இந்த அம்சங்கள் இயங்கத் தொடங்கும்.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA மேலாண்மை',
        'back_link' => '&larr; டிக்கெட்டுகள் வழிகாட்டிக்குத் திரும்பு',
        'sidebar_title' => 'SLA வழிகாட்டி',
        'hero_title' => 'SLA மேலாண்மை',
        'hero_sub' => 'வணிக நேரத்தைக் கணக்கில் கொள்ளும் பதில் மற்றும் தீர்வு இலக்குகள், துறைவாரி மீறல் அறிவிப்புகளுடன்',
        'nav' => [
            'overview' => 'மேலோட்டம்',
            'building_blocks' => 'அடிப்படைக் கூறுகள்',
            'behaviour_settings' => 'நடத்தை அமைப்புகள்',
            'breach_notifications' => 'மீறல் அறிவிப்புகள்',
            'cron_setup' => 'Cron job அமைப்பு',
            'worked_examples' => 'எடுத்துக்காட்டுகள்',
            'troubleshooting' => 'சிக்கல் தீர்வு',
        ],
        'overview' => [
            'heading' => 'மேலோட்டம்',
            'sub' => 'SLA என்றால் என்ன, அவை ஏன் முக்கியம், FreeITSM இயந்திரம் உயர்மட்டத்தில் எவ்வாறு செயல்படுகிறது.',
            'p1' => 'சேவை நிலை ஒப்பந்தம் (SLA) என்பது ஒரு டிக்கெட்டுக்கு உங்கள் குழு எவ்வளவு விரைவாகப் பதிலளித்து அதைத் தீர்க்கும் என்பது பற்றிய உறுதிமொழி. FreeITSM ஒவ்வொரு டிக்கெட்டுக்கும் இரண்டு கடிகாரங்களைக் கண்காணிக்கிறது: <strong>பதில்</strong> (டிக்கெட் உருவாக்கப்பட்டதிலிருந்து பகுப்பாய்வாளரின் முதல் நடவடிக்கை வரையிலான நேரம்) மற்றும் <strong>தீர்வு</strong> (டிக்கெட் உருவாக்கப்பட்டதிலிருந்து அது மூடப்படும் வரையிலான நேரம்). இரண்டு இலக்குகளும் முன்னுரிமைக்கு ஏற்ப அமைக்கப்படுகின்றன &mdash; எனவே P1-க்கு பதிலுக்கு 30 நிமிடங்களும் தீர்வுக்கு 4 மணிநேரமும் இருக்கலாம், P4-க்கு 8 வேலை நேர மணிநேரமும் 5 வேலை நாட்களும் இருக்கலாம்.',
            'p2' => 'FreeITSM-இன் SLA இயந்திரத்தில் புரிந்துகொள்ள வேண்டிய நான்கு வடிவமைப்புத் தேர்வுகள் உள்ளன:',
            'choice_business' => '<strong>வணிக நேரம், சுவர் கடிகார நேரம் அல்ல.</strong> மாலை 4:30-க்கு எழுப்பப்பட்ட P2-க்கு 1 மணிநேர பதில் இலக்கு இருந்து, அலுவலகம் மாலை 5 மணிக்கு மூடப்படுமானால், 5:30-க்கு மீறல் ஏற்படாது. கடிகாரம் அடுத்த வேலை நாளில் காலை 9 மணிக்குத் தொடரும். இது தொழில்துறை தரநிலை; பகுப்பாய்வாளர்கள் இரவில் வீடு செல்லும்போது இதுவே நியாயமான மாதிரி.',
            'choice_pause' => '<strong>இடைநிறுத்தக்கூடியது.</strong> டிக்கெட் "SLA-வை இடைநிறுத்து" எனக் குறிக்கப்பட்ட நிலையில் (எ.கா. <em>பதிலுக்காகக் காத்திருக்கிறது</em> அல்லது <em>நிறுத்தி வைக்கப்பட்டது</em>) இருக்கும்போது கடிகாரம் நிற்கும். டிக்கெட் மீண்டும் வேலை நிலைக்குச் செல்லும்போது அது தொடரும்.',
            'choice_compute' => '<strong>படிக்கும்போது கணக்கிடல், சேமிப்பு அல்ல.</strong> நீங்கள் பார்க்கும் ஒவ்வொரு முறையும் இயந்திரம் டிக்கெட் தணிக்கைப் பதிவிலிருந்து SLA நிலையை மீண்டும் கணக்கிடுகிறது. ஒத்திசைவு தவறக்கூடிய சேமிக்கப்பட்ட கவுண்டர்கள் எதுவும் இல்லை. பின்னர் ஒரு வணிக நாட்காட்டியின் நேரங்களை மாற்றினால், ஒவ்வொரு பழைய டிக்கெட்டின் SLA-வும் அடுத்த முறை பார்க்கப்படும்போது புதிய நேரங்களின்படி மீண்டும் கணக்கிடப்படும்.',
            'choice_cutoff' => '<strong>அமலாக்க வரம்புத் தேதி.</strong> நிர்வாகி கட்டுப்படுத்தும் "SLA-களை அமல்படுத்தும் தேதி" இருப்பதால், SLA-களை இயக்கும்போது உங்கள் அமைப்பிலுள்ள ஏற்கனவே உள்ள டிக்கெட்டுகள் திடீரென பின்னோக்கி மீறப்பட்டதாகாது. வரம்புத் தேதியில் அல்லது அதற்குப் பிறகு உருவாக்கப்பட்ட டிக்கெட்டுகள் மட்டுமே கண்காணிக்கப்படும்.',
            'tip' => 'ITIL உங்களுக்குப் புதியது என்றால்: பதில் நேரம் என்பது ஏற்றுக்கொள்ளுதல் பற்றியது (யாரோ எடுத்துக்கொண்டார்); தீர்வு நேரம் என்பது நிறைவு பற்றியது (பயனரின் சிக்கல் சரிசெய்யப்பட்டது). இரண்டு கடிகாரங்களும் தனித்தனியாக ஓடுகின்றன, வெவ்வேறு இலக்குகளைக் கொண்டுள்ளன.',
        ],
        'blocks' => [
            'heading' => 'நான்கு அடிப்படைக் கூறுகள்',
            'sub' => 'இந்த நான்கையும் அமைத்தால் SLA கண்காணிப்பு செயல்படும். மற்றவை அனைத்தும் விருப்பமான மேம்படுத்தல்கள்.',
            'cal_heading' => '1. வணிக நாட்காட்டிகள்',
            'cal_intro' => 'உங்கள் சேவை மையம் எப்போது திறந்திருக்கும் என்பதை ஒரு நாட்காட்டி வரையறுக்கிறது. ஒவ்வொரு நாட்காட்டியிலும் இவை உள்ளன:',
            'cal_tz' => '<strong>நேர மண்டலம்</strong> &mdash; ஒரு IANA நேர மண்டல அடையாளங்காட்டி (எ.கா. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). DST மாற்றங்கள் தானாகக் கையாளப்படும்.',
            'cal_hours' => '<strong>வாராந்திர வேலை நேரங்கள்</strong> &mdash; ஒவ்வொரு வார நாளுக்கும் ஒரு வரிசை, அதில் திறந்தது தேர்வுப்பெட்டியும் தொடக்க / முடிவு நேரங்களும் இருக்கும். புதிய நாட்காட்டிகள் இயல்பாக திங்கள்-வெள்ளி 09:00-17:00, சனி/ஞாயிறு மூடப்பட்டவை. திறந்தது எனக் குறிக்கப்படாத வரிசை என்றால் அன்று மையம் மூடப்பட்டுள்ளது.',
            'cal_holidays' => '<strong>விடுமுறைகள்</strong> &mdash; தேதி + விருப்பப் பெயர். விடுமுறைகள் வாராந்திர முறையை மீறும் (திங்கட்கிழமையில் வந்தாலும் மையம் மூடப்படும்).',
            'cal_default' => '<strong>இயல்புநிலைக் குறி</strong> &mdash; சரியாக ஒரு நாட்காட்டி இயல்புநிலையாக இருக்கும். வேறுவிதமாகக் குறிப்பிடாவிட்டால் புதிய முன்னுரிமைகள் அதையே பெறும்.',
            'cal_outro' => 'உங்களுக்குத் தேவையான அளவு நாட்காட்டிகளை உருவாக்கலாம் &mdash; ஒரு அலுவலகத்துக்கு ஒன்று, ஒரு குழுவுக்கு ஒன்று, நீட்டிக்கப்பட்ட நேரங்களுடன் VIP வாடிக்கையாளர்களுக்கு ஒன்று. அவை SLA இலக்குகளாலும் மீறல் சரிபார்ப்பு இயந்திரத்தாலும் பகிர்ந்து பயன்படுத்தப்படுகின்றன.',
            'prio_heading' => '2. SLA இலக்குகளுடன் முன்னுரிமைகள்',
            'prio_intro' => 'முன்னுரிமைகள் தாவலில் (அல்லது SLA தாவலிலுள்ள SLA இலக்குகள் அட்டவணை வழியாக), ஒவ்வொரு முன்னுரிமைக்கும் இவை இருக்கலாம்:',
            'prio_response' => '<strong>பதில் இலக்கு (நிமிடங்கள்)</strong> &mdash; பகுப்பாய்வாளரின் முதல் நடவடிக்கை வரை எவ்வளவு நேரம்.',
            'prio_resolution' => '<strong>தீர்வு இலக்கு (நிமிடங்கள்)</strong> &mdash; டிக்கெட் மூடப்படும் வரை எவ்வளவு நேரம்.',
            'prio_calendar' => '<strong>நாட்காட்டி</strong> &mdash; இந்த முன்னுரிமையின் கடிகாரம் எந்த வணிக நாட்காட்டியின்படி ஓடும். இயல்புநிலை நாட்காட்டியைப் பயன்படுத்த வெறுமையாக விடவும்.',
            'prio_outro' => 'இரண்டு இலக்குப் புலங்களையும் வெறுமையாக விட்டால் அந்த முன்னுரிமைக்கான SLA கண்காணிப்பு முழுவதுமாக முடக்கப்படும் &mdash; நேர அழுத்தம் இல்லாத "தகவல்" அல்லது "நிலுவை" முன்னுரிமைக்குப் பயனுள்ளது.',
            'pause_heading' => '3. SLA இடைநிறுத்த நிலைகள்',
            'pause_intro' => 'நிலைகள் தாவலில் "SLA-வை இடைநிறுத்து" என்ற பிரத்யேக நெடுவரிசை உள்ளது. குழுவின் கட்டுப்பாட்டுக்கு வெளியே ஏதோ ஒன்றுக்காக டிக்கெட் காத்திருப்பதைக் குறிக்கும் எந்த நிலையையும் குறியிடவும். வழக்கமான எடுத்துக்காட்டுகள்:',
            'pause_awaiting' => '<strong>பதிலுக்காகக் காத்திருக்கிறது</strong> &mdash; வாடிக்கையாளர் நமக்குத் தகவல் தர வேண்டியுள்ளது. நியாயமான இடைநிறுத்தமாக கிட்டத்தட்ட அனைவராலும் ஏற்கப்படுகிறது.',
            'pause_vendor' => '<strong>நிறுத்தி வைக்கப்பட்டது (விற்பனையாளர்)</strong> &mdash; Microsoft / மூன்றாம் தரப்பு ஆதரவுக்காகக் காத்திருக்கிறது.',
            'pause_change' => '<strong>நிறுத்தி வைக்கப்பட்டது (மாற்றச் சாளரம்)</strong> &mdash; எதிர்கால பராமரிப்புச் சாளரத்துக்குத் திட்டமிடப்பட்டுள்ளது.',
            'pause_parts' => '<strong>நிறுத்தி வைக்கப்பட்டது (பாகங்கள்)</strong> &mdash; வன்பொருள் விநியோகத்துக்காகக் காத்திருக்கிறது.',
            'pause_warn' => 'டிக்கெட் கடினமாக இருக்கும்போது அல்லது பகுப்பாய்வாளர் பரபரப்பாக இருக்கும்போது, பொதுவான "நிறுத்தி வைக்கப்பட்டது" நிலையை SLA-விலிருந்து தப்பிக்கும் வழியாகத் தவறாகப் பயன்படுத்தலாம். உங்கள் குழுவுக்கு ஒழுக்கம் இருந்தால் இது பரவாயில்லை. இல்லையெனில், மேலே உள்ள குறிப்பிட்ட வகைகளால் இதை மாற்றுவதைப் பரிசீலிக்கவும், அல்லது 24 மணிநேரத்துக்கு மேல் இடைநிறுத்தப்பட்ட டிக்கெட்டுகளை அம்பர் எச்சரிக்கையாகக் குறிக்கும் <strong>Watchtower</strong> டாஷ்போர்டை நம்பவும்.',
            'cutoff_heading' => '4. அமலாக்க வரம்புத் தேதி (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'மிக முக்கியமான ஒரே உலகளாவிய அமைப்பு. இங்கே ஒரு தேதி-நேரத்தை அமைக்கும் வரை SLA கண்காணிப்பு முழுவதுமாக முடக்கப்பட்டிருக்கும் &mdash; கடிகாரங்கள் ஓடாது, இன்பாக்ஸில் குறிகள் காட்டப்படாது, மீறல் மின்னஞ்சல்கள் அனுப்பப்படாது. கடந்த தேதி-நேரத்தை அமைத்தால் அந்தப் புள்ளியிலிருந்து பின்னோக்கி SLA-கள் இயக்கப்படும். எதிர்கால தேதி-நேரத்தை அமைத்தால் இயக்கம் திட்டமிடப்படும்.',
            'cutoff_p2' => 'பெரும்பாலான குழுக்கள் SLA-களை முதலில் இயக்கும்போது இதை "இப்போது" என அமைக்கின்றன &mdash; ஏற்கனவே உள்ள டிக்கெட்டுகள் SLA-க்கு முந்தைய நிலையிலேயே இருக்கும், அந்த நேரத்திலிருந்து வரும் புதிய டிக்கெட்டுகள் கண்காணிக்கப்படும்.',
        ],
        'behaviour' => [
            'heading' => 'நடத்தை அமைப்புகள்',
            'sub' => 'விளிம்பு நிலைகளுக்கு இயந்திரம் எவ்வாறு எதிர்வினையாற்றுகிறது என்பதை இவை கட்டுப்படுத்துகின்றன. இயல்புநிலைகள் பொருத்தமானவை &mdash; குறிப்பிட்ட விருப்பம் இருந்தால் மட்டுமே இவற்றை மாற்றினால் போதும்.',
            'prio_heading' => 'நடுவில் முன்னுரிமை மாறும்போது',
            'prio_intro' => 'ஒரு P3 டிக்கெட் பாதி வழியில் P1 ஆக உயர்த்தப்பட்டால் (சிக்கல் நினைத்ததை விடப் பெரியது என்று தெரிந்ததால்), மூன்று நியாயமான நடத்தைகள் உள்ளன:',
            'prio_forward' => '<strong>முன்னோக்கு (இயல்புநிலை)</strong> &mdash; திரட்டப்பட்ட வணிக நிமிடங்களைப் பாதுகாத்து இலக்கை மட்டும் மாற்றும். டிக்கெட் அதன் 8 மணிநேர P3 இலக்கில் 2 மணிநேரத்தைப் பயன்படுத்தியிருந்தால், இப்போது அதன் 1 மணிநேர P1 இலக்கில் 2 மணிநேரம் பயன்படுத்தப்பட்டதாகும் &mdash; அதாவது ஏற்கனவே மீறப்பட்டுவிட்டது. இது சரியானதே எனலாம்: சிக்கல் தொடக்கத்திலிருந்தே P1 தான், குழுவுக்குத்தான் தெரியவில்லை.',
            'prio_recompute' => '<strong>மீண்டும் கணக்கிடு</strong> &mdash; கடிகாரத்தை மீட்டமைத்து, டிக்கெட் உருவாக்கப்பட்டதிலிருந்து புதிய இலக்கைப் பின்னோக்கிப் பயன்படுத்தும். தூய்மையான மறுகணக்கீடு.',
            'prio_reset' => '<strong>மீட்டமை</strong> &mdash; முன்னுரிமை மாறிய தருணத்திலிருந்து புதிய கடிகாரத்தைத் தொடங்கும். குழுவுக்கு மிகவும் சலுகையானது; ஆனால் அதிக முன்னுரிமை டிக்கெட்டுக்கு திடீரென புதிய நீண்ட கடிகாரம் கிடைத்தால் வாடிக்கையாளர்கள் ஏமாற்றப்பட்டதாக உணரலாம்.',
            'reopen_heading' => 'மூடப்பட்ட டிக்கெட் மீண்டும் திறக்கப்படும்போது',
            'reopen_intro' => 'ஒரு டிக்கெட் மீண்டும் திறக்கப்பட்டால் (மூடிய பிறகு பயனர் பதிலளித்தால்):',
            'reopen_reset' => '<strong>மீட்டமை (இயல்புநிலை)</strong> &mdash; மீண்டும் திறந்த தருணத்திலிருந்து புதிய பதில் மற்றும் தீர்வு கடிகாரத்தைத் தொடங்கும். மீண்டும் திறப்பை முழுமையாகப் புதிய டிக்கெட்டாகவே கருதும்.',
            'reopen_continue' => '<strong>தொடர்</strong> &mdash; மூடும்போது கழிந்த நேரத்திலிருந்து தொடரும். அசல் SLA இலக்குகள் தொடர்ந்து பொருந்தும்.',
            'first_heading' => 'முதல் பதிலின் வரையறை',
            'first_intro' => '"முதல் பதில்" எது &mdash; பதில் கடிகாரத்தை நிறுத்தும் தருணம் எது?',
            'first_either' => '<strong>ஏதேனும் ஒன்று (இயல்புநிலை)</strong> &mdash; எந்த வகையிலும் பகுப்பாய்வாளரின் முதல் நடவடிக்கை: வெளிச்செல்லும் மின்னஞ்சல், நிலை மாற்றம், ஒதுக்கீடு.',
            'first_status' => '<strong>நிலை மாற்றம்</strong> &mdash; இயல்புநிலையிலிருந்து விலகும் நிலை மாற்றம் மட்டுமே கணக்கில் வரும். கடுமையானது &mdash; பகுப்பாய்வாளர் டிக்கெட்டைத் திறந்து பார்த்தது மட்டும் போதாது, உண்மையில் வேலை செய்திருக்க வேண்டும்.',
            'first_email' => '<strong>வெளிச்செல்லும் மின்னஞ்சல்</strong> &mdash; கோரிக்கையாளருக்கான மின்னஞ்சல் பதில் மட்டுமே கணக்கில் வரும். மிகக் கடுமையானது &mdash; வாடிக்கையாளர் நம்மிடமிருந்து தகவல் பெற்றிருக்க வேண்டும்.',
            'warn_heading' => 'எச்சரிக்கை வரம்பு சதவீதம்',
            'warn_body' => 'காட்டி பச்சையிலிருந்து அம்பருக்கு மாறுவதற்கு முன் SLA இலக்கில் எவ்வளவு தூரம் கடக்க வேண்டும். இயல்புநிலை 80% &mdash; எனவே 60 நிமிட பதில் இலக்கு 48 நிமிடங்கள் கழிந்தபோது அம்பர் காட்டும். எச்சரிக்கை-தூண்டுதல் மீறல் அறிவிப்புகளையும் இது இயக்குகிறது.',
        ],
        'breach' => [
            'heading' => 'மீறல் அறிவிப்புகள்',
            'sub' => 'SLA-கள் மீறலை நெருங்கும்போது (எச்சரிக்கை) அல்லது உண்மையில் மீறும்போது இயங்கும், துறைவாரி அமைக்கக்கூடிய மின்னஞ்சல் விதிகள்.',
            'intro' => 'ஒவ்வொரு விதிக்கும் நான்கு பரிமாணங்கள் உள்ளன, அனைத்தும் தனித்தனியானவை:',
            'scope_heading' => '1. நோக்கம்',
            'scope_body' => '<strong>இயல்புநிலை</strong> (விதி ஒவ்வொரு துறையின் டிக்கெட்டுகளுக்கும் பொருந்தும்) அல்லது <strong>குறிப்பிட்ட துறை</strong>. தீர்வு: அந்தத் துறையின் டிக்கெட்டுகளுக்கு, துறை சார்ந்த விதி இயல்புநிலை விதியை விட மேலோங்கும். இயல்புநிலை விதி இல்லாவிட்டால், குறிப்பிட்ட விதி இல்லாத துறைகளுக்கு அறிவிப்புகள் எதுவும் கிடைக்காது.',
            'trigger_heading' => '2. தூண்டுதல்',
            'trigger_body' => '<strong>எச்சரிக்கை</strong> (டிக்கெட் எச்சரிக்கை வரம்பைக் கடந்துவிட்டது &mdash; சாத்தியமான மீறல்) அல்லது <strong>மீறல்</strong> (டிக்கெட் தன் இலக்கைத் தாண்டிவிட்டது &mdash; உண்மையான மீறல்). ஒவ்வொன்றும் தனி விதி, எனவே ஒவ்வொன்றுக்கும் வெவ்வேறு நபர்களுக்கு அறிவிக்கலாம்.',
            'target_heading' => '3. இலக்கு',
            'target_body' => 'எந்தக் கடிகாரத்தைக் கவனிக்க வேண்டும் &mdash; <strong>பதில்</strong>, <strong>தீர்வு</strong>, அல்லது <strong>இரண்டும்</strong>.',
            'recip_heading' => '4. பெறுநர்கள்',
            'recip_intro' => 'பின்வருவனவற்றின் எந்தக் கலவையும்:',
            'recip_assignee' => '<strong>டிக்கெட்டின் ஒதுக்கப்பட்டவர்</strong> &mdash; தற்போது டிக்கெட்டை வைத்திருக்கும் பகுப்பாய்வாளர். ஒதுக்கப்படவில்லை என்றால் தவிர்க்கப்படும்.',
            'recip_teams' => '<strong>டிக்கெட்டின் துறை குழுக்களின் உறுப்பினர்கள்</strong> &mdash; டிக்கெட்டின் துறையுடன் இணைக்கப்பட்ட எந்தக் குழுவிலுமுள்ள ஒவ்வொரு பகுப்பாய்வாளரும். விநியோகப் பட்டியலைப் பராமரிக்காமலே முழு வரிசையையும் உள்ளடக்கும்.',
            'recip_specific' => '<strong>குறிப்பிட்ட பகுப்பாய்வாளர்</strong> &mdash; பங்கு அல்லாமல் பெயரிடப்பட்ட நபரான "SLA சாம்பியன்" / "சேவை மேலாளர்" முறை.',
            'recip_custom' => '<strong>தனிப்பயன் மின்னஞ்சல் முகவரிகள்</strong> &mdash; கமாவால் பிரிக்கப்பட்ட கட்டற்ற உரை. பகிரப்பட்ட இன்பாக்ஸ்கள் (<code>sla-alerts@company.com</code>), Slack/Teams மின்னஞ்சல் பாலங்கள் அல்லது விநியோகப் பட்டியல்களுக்குப் பயனுள்ளது.',
            'tip' => 'ஒவ்வொரு டிக்கெட்டும் (இலக்கு, தூண்டுதல்) ஜோடிக்கு அதிகபட்சம் ஒரு மின்னஞ்சலை அனுப்பும் &mdash; என்ன அனுப்பப்பட்டது என்பதை cron worker <code>sla_notifications_sent</code> அட்டவணையில் கண்காணிக்கிறது. எனவே எச்சரிக்கை ஒருமுறை, மீறல் ஒருமுறை மட்டுமே அனுப்பப்படும் &mdash; தொடர் அஞ்சல் சுழற்சிகள் இல்லை.',
            'warn' => '<strong>விதிகள் இல்லை = மின்னஞ்சல்கள் இல்லை.</strong> அமைப்பிலுள்ள ஒவ்வொரு டிக்கெட்டும் மீறினாலும், குறைந்தது ஒரு விதியைச் சேர்க்கும் வரை எதுவும் அனுப்பப்படாது. அனைத்தையும் உள்ளடக்க, இயல்புநிலை நோக்கத்தில் ஒரு எச்சரிக்கை + மீறல் ஜோடியுடன் தொடங்குங்கள்.',
        ],
        'cron' => [
            'heading' => 'Cron job அமைத்தல்',
            'sub' => 'மீறல் சரிபார்ப்பு ஸ்கிரிப்ட் அட்டவணைப்படி இயங்க வேண்டும். ஒவ்வொரு 5 நிமிடத்துக்கு ஒருமுறை சிறந்தது.',
            'p1' => 'UI-இல் தெரியும் SLA காட்டிகள் (இன்பாக்ஸிலுள்ள குறிகள், வாசிப்புப் பலகத்திலுள்ள பலகங்கள்) பக்கம் ஏற்றப்படும்போது உடனுக்குடன் கணக்கிடப்படுகின்றன. ஆனால் யாரும் பார்க்காதபோதும் <em>ஏதோ ஒன்று</em> முன்கூட்டியே டிக்கெட்டுகளைச் சரிபார்த்தால் மட்டுமே மீறல் மின்னஞ்சல்கள் அனுப்பப்படும். அந்த ஏதோ ஒன்று ஒரு திட்டமிட்ட பணி &mdash; Windows-இல் Task Scheduler, Linux-இல் cron.',
            'p2' => 'ஸ்கிரிப்ட் FreeITSM நிறுவல் கோப்பகத்திலுள்ள <code>cron/sla_breach_check.php</code>. இதை இரண்டு வழிகளில் இயக்கலாம்:',
            'cli_heading' => 'A. CLI (நீங்கள் கட்டுப்படுத்தும் சேவையகத்துக்குப் பரிந்துரைக்கப்படுகிறது)',
            'cli_note' => 'அங்கீகாரம் தேவையில்லை &mdash; யார் இயக்கலாம் என்பதைக் கோப்பு முறைமை அனுமதிகளே ஏற்கனவே கட்டுப்படுத்துகின்றன.',
            'http_heading' => 'B. HTTP (பகிர்வு ஹோஸ்டிங் அல்லது தொலைநிலை அட்டவணையிடுபவர்களுக்கு)',
            'http_note' => 'டோக்கன் முதல் நிறுவலில் தானாக உருவாக்கப்பட்டு <code>system_settings</code>-இல் <code>sla_cron_token</code> என்ற விசையின் கீழ் சேமிக்கப்படுகிறது (32 ஹெக்ஸ் எழுத்துகள், ~128 பிட் என்ட்ரோபி). இது ஓய்வில் குறியாக்கம் செய்யப்பட்டுள்ளதால், வரிசையை நேரடியாகப் படித்தால் டோக்கனுக்குப் பதிலாக <code>ENC:…</code> கிடைக்கும். உங்களுடையதை இவ்வாறு கண்டறியவும்:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Task Scheduler-ஐத் (<code>taskschd.msc</code>) திறந்து, இந்த அமைப்புகளுடன் புதிய பணியை உருவாக்கவும்:',
            'tbl_field' => 'புலம்',
            'tbl_value' => 'மதிப்பு',
            'win_r1_k' => 'பெயர்',
            'win_r1_v' => 'FreeITSM &mdash; SLA Breach Check',
            'win_r2_k' => 'பயனர் உள்நுழைந்திருந்தாலும் இல்லாவிட்டாலும் இயக்கு',
            'win_r2_v' => 'இதைத் தேர்வு செய்யவும்',
            'win_r3_k' => 'தூண்டுதல்',
            'win_r3_v' => 'தினசரி, ஒவ்வொரு 1 நாளுக்கும் மீண்டும், 1 நாளுக்கு ஒவ்வொரு 5 நிமிடத்துக்கும் மீண்டும் செய்',
            'win_r4_k' => 'செயல்',
            'win_r4_v' => 'நிரலைத் தொடங்கு',
            'win_r5_k' => 'நிரல்/ஸ்கிரிப்ட்',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'வாதங்களைச் சேர்',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'தொடங்கும் இடம்',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'உங்கள் crontab-இல் (<code>crontab -e</code>) ஒரு வரியைச் சேர்க்கவும்:',
            'sec_heading' => 'பாதுகாப்பு &mdash; HTTP endpoint-ஐ எது பாதுகாக்கிறது',
            'sec_intro' => 'மூன்று அடுக்குகள், அனைத்தும் தானாக அமல்படுத்தப்படுகின்றன:',
            'sec_token' => '<strong>1. பகிர்ந்த ரகசிய டோக்கன்</strong> &mdash; ஒவ்வொரு நிறுவலுக்கும் 128-பிட் சீரற்றது, நேரத் தாக்குதல்களைத் தடுக்க மாறா-நேர ஒப்பீட்டுடன் சரிபார்க்கப்படுகிறது.',
            'sec_lockout' => '<strong>2. ஒரு IP-க்கான தோல்வி அங்கீகார பூட்டு</strong> &mdash; ஒரே IP-யிலிருந்து கடந்த ஒரு மணிநேரத்தில் 10-க்கும் மேற்பட்ட தவறான டோக்கன் முயற்சிகள் வந்தால் 1 மணிநேர 429 பூட்டு தூண்டப்படும். fail2ban தேவையின்றி brute-force சோதனையை முறியடிக்கிறது.',
            'sec_interval' => '<strong>3. வெற்றிகரமான இயக்கங்களுக்கு இடையே குறைந்தபட்ச இடைவெளி</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (இயல்புநிலை 30 வினாடி). செல்லுபடியாகும் டோக்கன் கொண்ட கோரிக்கையும், கடைசி வெற்றிகரமான இயக்கத்துக்குப் பிறகு இதை விட விரைவாக வந்தால் 429 பெறும். தற்செயலான இரட்டை அட்டவணையிடலையும் கட்டுப்பாடற்ற சுழற்சிகளையும் முறியடிக்கிறது.',
            'log_heading' => 'செயல்பாட்டுப் பதிவு',
            'log_body' => 'ஒவ்வொரு இயக்கமும் (ஏற்கப்பட்டாலும் நிராகரிக்கப்பட்டாலும்) நேரம், முடிவு, எண்ணிக்கைகள் மற்றும் கிளையன்ட் IP உடன் <code>sla_cron_runs</code> அட்டவணையில் பதிவு செய்யப்படுகிறது. SLA அமைப்புகள் தாவலின் கீழே உள்ள <strong>Cron Activity</strong> பலகத்தில் கடைசி 20 இயக்கங்களைப் பார்க்கலாம் &mdash; அட்டவணை இயங்குகிறதா என்பதைச் சரிபார்க்கவும், தோல்வியடைந்த அங்கீகார முயற்சிகளைத் தணிக்கை செய்யவும் பயனுள்ளது. அட்டவணை சிறியதாக இருக்க, <code>sla_cron_log_retention_days</code> (இயல்புநிலை 30) க்குப் பிறகு வரிசைகள் தானாக நீக்கப்படும்.',
        ],
        'examples' => [
            'heading' => 'செயல்முறை எடுத்துக்காட்டுகள்',
            'sub' => 'எளிய ஒற்றை நேர மண்டல நிலையிலிருந்து "நியாயம்" என்பதை வரையறுக்க வேண்டிய சிக்கலான பல நேர மண்டல நிலை வரை.',
            'ex1_heading' => 'எடுத்துக்காட்டு 1: டிக்கெட் UK-இல் உருவாக்கப்பட்டது, சர்வீஸ் டெஸ்க் UK-இல்',
            'ex1_title' => 'எளிய நிலை',
            'ex1_tag' => 'ஒற்றை நேர மண்டலம்',
            'ex1_setup' => '<strong>அமைப்பு:</strong> <em>UK Office</em> என்ற ஒரு வணிக நாட்காட்டி, நேர மண்டலம் <code>Europe/London</code>, திங்கள்-வெள்ளி 09:00-17:00, விடுமுறைகள் இல்லை. P2 முன்னுரிமைக்கு 1 மணி நேர பதிலளிப்பு இலக்கும் 4 மணி நேர தீர்வு இலக்கும் உள்ளன; இரண்டும் <em>UK Office</em> நாட்காட்டியின்படி இயங்குகின்றன.',
            'ex1_scenario' => '<strong>சூழ்நிலை:</strong> பயனர் <strong>புதன்கிழமை UK நேரம் 16:30</strong> மணிக்கு ஒரு P2 டிக்கெட்டை உருவாக்குகிறார்.',
            'ex1_timeline' => 'புதன் 16:30 UK &mdash; <strong>டிக்கெட் உருவாக்கப்பட்டது</strong>, பதிலளிப்பு கடிகாரம் தொடங்குகிறது.
புதன் 17:00 UK &mdash; அலுவலகம் மூடப்படுகிறது, கடிகாரம் நிற்கிறது (60 நிமிட இலக்கில் 30 நிமிடம் செலவானது).
வியாழன் 09:00 UK &mdash; அலுவலகம் திறக்கிறது, கடிகாரம் மீண்டும் ஓடுகிறது.
வியாழன் 09:30 UK &mdash; பகுப்பாய்வாளர் பதிலளிக்கிறார். பதிலளிப்பு SLA கடைசி நிமிடத்தில் பூர்த்தியானது (60 நிமிடம் செலவு, 60 நிமிட இலக்கு).',
            'ex1_outro' => 'பகுப்பாய்வாளர் <strong>வியாழன் 10:00 UK</strong> வரை பதிலளிக்காவிட்டால், பதிலளிப்பு <strong>30 நிமிடங்களால் மீறப்பட்டிருக்கும்</strong> (60 நிமிட இலக்கிற்கு எதிராக 90 நிமிடம் செலவு &mdash; புதன் மாலையிலிருந்து 30, வியாழன் காலையிலிருந்து 60). 1 மணி நேர கடிகாரம் வணிக நேரத்தில் மட்டுமே ஓடும், ஆனாலும் நாள் முடிவில் உருவாகும் டிக்கெட் அலுவலகம் மீண்டும் திறக்கும்போது அதன் ஒதுக்கீட்டில் பெரும்பகுதியை ஏற்கனவே இழந்திருக்கும் &mdash; 09:00-க்கு வரும் பகுப்பாய்வாளர் தனக்கு முழு ஒரு மணி நேரம் இருப்பதாக எண்ணுவது எளிது, உண்மையில் 30 நிமிடங்களே மீதமுள்ளன.',
            'ex2_heading' => 'எடுத்துக்காட்டு 2: டிக்கெட் UK-இல் உருவாக்கப்பட்டது, சர்வீஸ் டெஸ்க் எஸ்டோனியாவில்',
            'ex2_title' => 'பல நேர மண்டல நிலை',
            'ex2_tag' => '"நியாயம்" என்பதை வரையறுக்க 3 வழிகள்',
            'ex2_setup' => '<strong>அமைப்பு:</strong> UK வாடிக்கையாளர்கள் (<code>Europe/London</code>, GMT/BST), எஸ்டோனியா சர்வீஸ் டெஸ்க் (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>UK-ஐ விட 2 மணி நேரம் முன்னதாக</strong>). இரு டெஸ்க்குகளும் பெயரளவில் உள்ளூர் நேரம் 09:00-17:00 வேலை செய்கின்றன.',
            'ex2_scenario' => '<strong>சூழ்நிலை:</strong> UK வாடிக்கையாளர் <strong>வெள்ளிக்கிழமை UK நேரம் 16:30</strong> மணிக்கு ஒரு P2 டிக்கெட்டை உருவாக்குகிறார் (= எஸ்டோனியா 18:30, எஸ்டோனியா மூடிய பிறகு). எஸ்டோனியா பகுப்பாய்வாளர் அதில் வேலை செய்ய கிடைக்கும் அடுத்த வாய்ப்பு திங்கள் 09:00 எஸ்டோனியா (= UK 07:00). பதிலளிப்பு இலக்கு 1 மணி நேரம்.',
            'ex2_question' => 'SLA என்ன சொல்ல வேண்டும்? நியாயமான மூன்று பதில்கள் உள்ளன, ஒவ்வொன்றும் வெவ்வேறு அர்த்தத்தில் நியாயமானது. உங்கள் சேவை ஒப்பந்தம் எதை உறுதியளிக்கிறது என்பதன் அடிப்படையில் முன்னுரிமைக்கு எந்த நாட்காட்டியை ஒதுக்குவது என்பதை நீங்களே தேர்வு செய்கிறீர்கள்.',
            'optA_label' => 'விருப்பம் A &mdash; வாடிக்கையாளர் மையம்',
            'optA_p1' => '<strong>முன்னுரிமைக்கு <em>UK</em> நேரங்களைக் கொண்ட நாட்காட்டியைப் பயன்படுத்துமாறு அமைக்கவும்.</strong> பகுப்பாய்வாளர் எங்கிருந்தாலும் கடிகாரம் UK 09:00-17:00-க்கு எதிராக ஓடும்.',
            'optA_p2' => 'மேற்கண்ட சூழ்நிலையில், டிக்கெட் வெள்ளி UK 16:30-க்கு உருவாக்கப்பட்டது: கடிகாரம் வெள்ளி UK 16:30&ndash;17:00 ஓடுகிறது (30 நிமிடம் செலவு), இரவிலும் வார இறுதியிலும் நிற்கிறது, திங்கள் 09:00 UK-க்கு மீண்டும் ஓடுகிறது. எஸ்டோனியா பகுப்பாய்வாளர் திங்கள் 10:00 எஸ்டோனியாவில் (= 08:00 UK) பதிலளித்தால், UK நாட்காட்டி இன்னும் நிறுத்தத்தில் உள்ளது (UK அலுவலகம் 09:00 UK-க்கு திறக்கும்), எனவே கூடுதல் நிமிடங்கள் எதுவும் ஓடாது &mdash; செலவு 30 நிமிடமாகவே இருக்கும். <strong>SLA 30 நிமிட இடைவெளியுடன் பூர்த்தியானது</strong>. 09:30 UK-க்கு (= 11:30 எஸ்டோனியா) பிறகான எந்த பதிலும் மீறலாகும்.',
            'optA_p3' => '<em>யாருக்கு நியாயம்:</em> வாடிக்கையாளருக்கு. அவர்களின் அனுபவம் அவர்களின் வேலை நாளுடன் பொருந்துகிறது.<br><em>சமரசம்:</em> எஸ்டோனியா பகுப்பாய்வாளர்கள் UK நேரம் 09:00-17:00 (= எஸ்டோனியா 11:00-19:00) கிடைக்க வேண்டும் என எதிர்பார்க்கப்படுகிறது, இது அவர்களின் வேலை நாளை 2 மணி நேரம் நீட்டிக்கிறது.',
            'optB_label' => 'விருப்பம் B &mdash; பகுப்பாய்வாளர் மையம்',
            'optB_p1' => '<strong>முன்னுரிமைக்கு <em>எஸ்டோனியா</em> நேரங்களைக் கொண்ட நாட்காட்டியைப் பயன்படுத்துமாறு அமைக்கவும்.</strong> கடிகாரம் எஸ்டோனியா 09:00-17:00-க்கு எதிராக ஓடும்.',
            'optB_p2' => 'அதே சூழ்நிலை: டிக்கெட் வெள்ளி 18:30 எஸ்டோனியாவில் (மூடிய பிறகு) உருவாக்கப்பட்டது, கடிகாரம் வார இறுதி முழுவதும் நிற்கிறது, திங்கள் 09:00 எஸ்டோனியாவில் (= 07:00 UK) ஓடத் தொடங்குகிறது. பகுப்பாய்வாளர் திங்கள் 09:30 எஸ்டோனியாவில் (= 07:30 UK) பதிலளித்தால், பதிலளிப்பு SLA 60 நிமிட இலக்கில் 30 நிமிடத்தைச் செலவிட்டுள்ளது &mdash; <strong>30 நிமிட இடைவெளியுடன் பூர்த்தியானது</strong>. UK வாடிக்கையாளர் வெள்ளி 16:30 UK-க்கு உருவாக்கி திங்கள் 07:30 UK-க்கு பதில் பெற்றார் &mdash; அவர்களின் உண்மையான காத்திருப்பு SLA குறிப்பதை விட மிக நீண்டது.',
            'optB_p3' => '<em>யாருக்கு நியாயம்:</em> பகுப்பாய்வாளர்களுக்கு. அவர்கள் வழக்கமான நேரங்களில் வேலை செய்கிறார்கள்.<br><em>சமரசம்:</em> வெள்ளி பிற்பகல் டிக்கெட் திங்கள் காலை எஸ்டோனியா நேரம் வரை ஏற்றுக்கொள்ளப்படாமல், அறிக்கை பதிலளிப்பு SLA 1 மணி நேரம் என்று சொன்னால், UK வாடிக்கையாளர்களுக்கு SLA "பொய் சொல்வது" போல் தோன்றலாம். SLA ஆதரவு டெஸ்க் நேரங்களுக்கு எதிராக ஓடுகிறது என்பதை உங்கள் சேவை ஒப்பந்தம் தெளிவாகக் குறிப்பிடுவதை உறுதிசெய்யுங்கள்.',
            'optC_label' => 'விருப்பம் C &mdash; ஒன்றுசேரும் சாளரம் (மிகக் கடுமையானது)',
            'optC_p1' => '<strong>இரு டெஸ்க்குகளும் திறந்திருக்கும் நேரங்களை மட்டும் உள்ளடக்கிய நாட்காட்டியைப் பயன்படுத்துமாறு முன்னுரிமையை அமைக்கவும்.</strong> UK 09:00-17:00, எஸ்டோனியா 09:00-17:00 (= UK 07:00-15:00) உடன் <strong>UK 09:00-15:00 சாளரத்தில்</strong> ஒன்றுசேர்கிறது &mdash; வேலை நாளுக்கு 6 மணி நேரம்.',
            'optC_p2' => 'அதே சூழ்நிலை: டிக்கெட் வெள்ளி 16:30 UK-க்கு உருவாக்கப்பட்டது (ஒன்றுசேர்தல் 15:00 UK-க்கு முடிவதால் அதற்கு வெளியே), கடிகாரம் வார இறுதியில் நிற்கிறது, திங்கள் 09:00 UK-க்கு (= 11:00 எஸ்டோனியா, ஒன்றுசேர்தல் மீண்டும் திறக்கும் தருணம்) மீண்டும் ஓடுகிறது. எஸ்டோனியா பகுப்பாய்வாளர் 11:30 எஸ்டோனியாவில் (= 09:30 UK) பதிலளித்தால், பதிலளிப்பு SLA 60 நிமிட இலக்கில் 30 நிமிடத்தைச் செலவிட்டுள்ளது &mdash; <strong>30 நிமிட இடைவெளியுடன் பூர்த்தியானது</strong>. பதில் ஒன்றுசேரும் சாளரத்தில் நடந்ததால் உடனடியாகக் கணக்கிடப்படுகிறது.',
            'optC_p3' => '<em>யாருக்கு நியாயம்:</em> இரு தரப்புக்கும் &mdash; டெஸ்க் உண்மையில் டிக்கெட்டை முன்னெடுக்க முடியும் மற்றும் பதிலைப் பெற வாடிக்கையாளர் தன் மேசையில் இருக்கும் நேரங்களில் மட்டுமே SLA ஓடுகிறது.<br><em>சமரசம்:</em> குறுகிய தினசரி சாளரம் என்பது கடுமையான இலக்குகளை எட்ட நீண்ட உண்மையான நேரம் ஆகும். 4 மணி நேர தீர்வு இலக்கு 1.5 நாள் ஒன்றுசேர்தலை எடுக்கும்; வழக்கமான 8 மணி நேர நாட்காட்டியில் அது ஒரே நாளில் முடிந்துவிடும்.',
            'choose_tip' => '<strong>எப்படித் தேர்வு செய்வது:</strong> உங்கள் சேவை ஒப்பந்தத்தைப் பாருங்கள். அது "பெற்ற 1 மணி நேரத்திற்குள் பதில்" என்று சொன்னால் &mdash; அது விருப்பம் A (வாடிக்கையாளரின் கடிகாரம்). "1 வேலை மணி நேரத்திற்குள் பதில்" என்று சொன்னால் &mdash; அது பொதுவாக விருப்பம் B (எந்த டெஸ்க் வேலை செய்கிறதோ அது). "பரஸ்பர கிடைப்புத்தன்மையின் 1 மணி நேரத்திற்குள்" என்று சொன்னால் &mdash; அது விருப்பம் C. ஒப்பந்தம் இல்லையென்றால், குழுவிடம் கேளுங்கள்: எஸ்டோனியா நேரங்களுக்கு வெளியிலும் அழுத்தத்தை உணர விரும்புகிறீர்களா (விருப்பம் A), அல்லது UK வாடிக்கையாளர்கள் அவ்வப்போது புறக்கணிக்கப்பட்டதாக உணர்வதை ஏற்கிறீர்களா (விருப்பம் B)?',
            'ex3_heading' => 'எடுத்துக்காட்டு 3: விற்பனையாளருக்காகக் காத்திருக்கும்போது கடிகாரத்தை நிறுத்துதல்',
            'ex3_title' => 'நிறுத்த நிலைகள் நடைமுறையில் எப்படி வேலை செய்கின்றன',
            'ex3_tag' => 'கடிகாரத்தை நிறுத்து',
            'ex3_setup' => '<strong>அமைப்பு:</strong> P3 முன்னுரிமை, 8 வணிக மணி நேர தீர்வு இலக்கு, UK நாட்காட்டி, "Awaiting Vendor" நிலை <em>Pause SLA</em> எனக் குறிக்கப்பட்டுள்ளது.',
            'ex3_scenario' => '<strong>சூழ்நிலை:</strong> டிக்கெட் திங்கள் 09:00 UK-க்கு உருவாக்கப்பட்டது. பகுப்பாய்வாளர் திங்கள் 11:00 UK-க்கு Microsoft-க்கு அதை உயர்த்தி, டிக்கெட்டை "Awaiting Vendor" நிலைக்கு மாற்றுகிறார். Microsoft புதன் 14:00 UK-க்கு பதிலளிக்கிறது. பகுப்பாய்வாளர் சரிசெய்து வியாழன் 10:00 UK-க்கு மூடுகிறார்.',
            'ex3_timeline' => 'திங்கள் 09:00 &mdash; டிக்கெட் உருவாக்கப்பட்டது, தீர்வு கடிகாரம் ஓடுகிறது.
திங்கள் 11:00 &mdash; "Awaiting Vendor" நிலைக்கு மாற்றப்பட்டது, <strong>கடிகாரம் நிறுத்தப்பட்டது</strong> (2 மணி நேரம் செலவு).
புதன் 14:00 &mdash; மீண்டும் "In Progress" நிலைக்கு மாற்றப்பட்டது, <strong>கடிகாரம் மீண்டும் ஓடுகிறது</strong>.
புதன் 17:00 &mdash; அலுவலகம் மூடப்படுகிறது (மொத்தம் 5 மணி நேரம் செலவு).
வியாழன் 09:00 &mdash; அலுவலகம் திறக்கிறது.
வியாழன் 10:00 &mdash; டிக்கெட் மூடப்பட்டது (மொத்தம் 6 மணி நேரம் செலவு). 8 மணி நேர இலக்கிற்கு எதிராக <strong>SLA பூர்த்தியானது</strong>.',
            'ex3_outro' => 'உண்மையான கடந்த நேரம்: ~3 நாட்கள். SLA கடந்த நேரம்: 6 வேலை மணி நேரம். நிறுத்த-நிலை குறியீடு இல்லாவிட்டால், SLA விற்பனையாளர் காத்திருப்பின் முழு 2 நாட்களையும் வணிக நேரங்களையும் சேர்த்து, மொத்தம் ~18 வேலை மணி நேரம் எனக் கணக்கிட்டிருக்கும் &mdash; மீறலுக்கும் மிக அதிகம்.',
        ],
        'trouble' => [
            'heading' => 'சிக்கல் தீர்வு',
            'sub' => 'பொதுவான சிக்கல்களும் எதைச் சரிபார்க்க வேண்டும் என்பதும்.',
            'col_symptom' => 'அறிகுறி',
            'col_cause' => 'சாத்தியமான காரணம்',
            'r1_s' => 'இன்பாக்ஸில் SLA குறிகள் தோன்றவில்லை',
            'r1_c' => '<code>Enforce SLAs from</code> வெறுமையாக உள்ளது, முன்னுரிமைக்கு இலக்குகள் அமைக்கப்படவில்லை, அல்லது டிக்கெட் வரம்பு தேதிக்கு முந்தையது.',
            'r2_s' => 'பகுப்பாய்வாளர் இலக்குக்குள் பதிலளித்தும் SLA மீறப்பட்டதாகக் காட்டுகிறது',
            'r2_c' => 'முன்னுரிமை மாற்ற வரலாற்றைச் சரிபார்க்கவும் &mdash; இடையில் முன்னுரிமை உயர்த்தப்பட்டு நடத்தை "Forward" (இயல்புநிலை) என அமைக்கப்பட்டிருந்தால், சேர்ந்த நேரம் தொடர்ந்து எடுத்துச் செல்லப்படும்.',
            'r3_s' => 'மீறல் அறிவிப்புகள் அனுப்பப்படவில்லை',
            'r3_c' => '(1) விதிகள் எதுவும் உள்ளமைக்கப்படவில்லை. (2) Cron job திட்டமிடப்படவில்லை. (3) விதிகள் உள்ளமைக்கப்பட்டுள்ளன ஆனால் பெறுநர்களைத் தீர்மானிக்க முடியவில்லை (ஒதுக்கப்பட்டவர் இல்லை, துறை குழுக்களில் மின்னஞ்சல் உள்ள உறுப்பினர்கள் இல்லை). ஒவ்வொரு இயக்கத்தின் சுருக்கத்திற்கு Cron Activity பலகத்தைப் பாருங்கள்.',
            'r4_s' => 'Cron இயங்குகிறது ஆனால் "no matching rule" என அறிவிக்கிறது',
            'r4_c' => 'ஒவ்வொரு துறையும் உள்ளடங்கும்படி குறைந்தது ஒரு Default-scope விதியைச் சேர்க்கவும்.',
            'r5_s' => 'Watchtower "N tickets paused over 24h" எனக் காட்டுகிறது',
            'r5_c' => 'டிக்கெட்டுகள் ஒரு SLA-நிறுத்த நிலையில் உள்ளன. யாரோ அவற்றை வேண்டுமென்றே நிறுத்தி வைத்து மறந்துவிட்டனர், அல்லது யாரோ On Hold-ஐ SLA-இலிருந்து தப்பிக்கும் வழியாகப் பயன்படுத்துகின்றனர். ஒவ்வொன்றையும் திறந்து, அதை முன்னெடுக்கவும் அல்லது நிறுத்த நிலையை நீக்கவும்.',
            'r6_s' => 'HTTP cron 403 திருப்பி அனுப்புகிறது',
            'r6_c' => 'URL-இல் உள்ள டோக்கன் பொருந்தவில்லை. <code>SELECT setting_value FROM system_settings WHERE setting_key = \'sla_cron_token\'</code> மூலம் தேடிப் பாருங்கள்.',
            'r7_s' => 'HTTP cron 429 "Rate limited" திருப்பி அனுப்புகிறது',
            'r7_c' => 'வெற்றிகரமான இயக்கம் <code>sla_cron_min_interval_seconds</code>-க்கும் (இயல்புநிலை 30வி) குறைவான நேரத்துக்கு முன்பு முடிந்தது. காத்திருக்கவும் அல்லது அமைப்பைக் குறைக்கவும்.',
            'r8_s' => 'HTTP cron 429 "Too many failed attempts" திருப்பி அனுப்புகிறது',
            'r8_c' => 'இந்த IP கடந்த ஒரு மணி நேரத்தில் 10-க்கும் மேற்பட்ட தவறான டோக்கன் முயற்சிகளைச் செய்துள்ளது. 1 மணி நேரம் காத்திருக்கவும் அல்லது தோல்விகளை அழிக்கவும்: <code>DELETE FROM sla_cron_runs WHERE client_ip = \'...\' AND outcome = \'auth_failed\'</code>.',
            'tip' => 'Linux எடுத்துக்காட்டுகள் மற்றும் தொலைநிலை-அட்டவணையாளர் ஒருங்கிணைப்பு உட்பட cron அமைப்பின் ஆழமான தொழில்நுட்ப விளக்கத்திற்கு, FreeITSM நிறுவல் கோப்பகத்தில் உள்ள <code>docs/sla-cron-setup.md</code> ஐப் பாருங்கள்.',
        ],
    ],
];
